// ---------- Exceptions ----------
struct CmdLineException : std::runtime_error {
  std::string extra;
  CmdLineException(const std::string &m, const std::string &e = "") : std::runtime_error(m), extra(e) {}
};
struct SystemException : std::runtime_error {
  int code; // errno or HRESULT-like
  bool isErrno;
  SystemException(int err, bool isErr = true) : std::runtime_error(""), code(err), isErrno(isErr) {}
};
struct MessageException : std::runtime_error {
  MessageException(const std::string &m) : std::runtime_error(m) {}
};
struct BreakException {};

// HRESULT-like codes
enum HRes : UInt32 {
  S_OK_ = 0,
  S_FALSE_ = 1,
  E_NOTIMPL_ = 0x80004001,
  E_NOINTERFACE_ = 0x80004002,
  E_ABORT_ = 0x80004004,
  E_FAIL_ = 0x80004005,
  E_INVALIDARG_ = 0x80070057,
  E_OUTOFMEMORY_ = 0x8007000E,
};

// ---------- Byte order helpers ----------
inline UInt32 GetUi16(const Byte *p) { return (UInt32)p[0] | ((UInt32)p[1] << 8); }
inline UInt32 GetUi32(const Byte *p) { return (UInt32)p[0] | ((UInt32)p[1] << 8) | ((UInt32)p[2] << 16) | ((UInt32)p[3] << 24); }
inline UInt64 GetUi64(const Byte *p) { return (UInt64)GetUi32(p) | ((UInt64)GetUi32(p + 4) << 32); }
inline UInt32 GetBe32(const Byte *p) { return ((UInt32)p[0] << 24) | ((UInt32)p[1] << 16) | ((UInt32)p[2] << 8) | (UInt32)p[3]; }
inline UInt64 GetBe64(const Byte *p) { return ((UInt64)GetBe32(p) << 32) | GetBe32(p + 4); }
inline void SetUi16(Byte *p, UInt32 v) { p[0] = (Byte)v; p[1] = (Byte)(v >> 8); }
inline void SetUi32(Byte *p, UInt32 v) { p[0] = (Byte)v; p[1] = (Byte)(v >> 8); p[2] = (Byte)(v >> 16); p[3] = (Byte)(v >> 24); }
inline void SetUi64(Byte *p, UInt64 v) { SetUi32(p, (UInt32)v); SetUi32(p + 4, (UInt32)(v >> 32)); }
inline void SetBe32(Byte *p, UInt32 v) { p[0] = (Byte)(v >> 24); p[1] = (Byte)(v >> 16); p[2] = (Byte)(v >> 8); p[3] = (Byte)v; }
inline void SetBe64(Byte *p, UInt64 v) { SetBe32(p, (UInt32)(v >> 32)); SetBe32(p + 4, (UInt32)v); }

