// FILETIME: 100-ns intervals since 1601-01-01
const UInt64 kFileTimeUnixEpoch = 116444736000000000ULL;
inline UInt64 UnixToFileTime(Int64 sec, UInt32 nsec = 0) { return (UInt64)(sec * 10000000LL + (Int64)(nsec / 100)) + kFileTimeUnixEpoch; }
