inline UInt32 Crc32Calc(const void *data, size_t size) { return Crc32Update(0, data, size); }
UInt64 Crc64Update(UInt64 crc, const void *data, size_t size);
void Sha256Calc(const Byte *data, size_t size, Byte *digest);
void Sha1Calc(const Byte *data, size_t size, Byte *digest);

class IHasher {
public:
  virtual ~IHasher() {}
  virtual void Init() = 0;
  virtual void Update(const void *data, size_t size) = 0;
  virtual void Final(Byte *digest) = 0;
  virtual unsigned DigestSize() const = 0;
  virtual std::string Name() const = 0;
};
std::unique_ptr<IHasher> CreateHasher(const std::string &name); // CRC32 CRC64 SHA256 SHA1 XXH64 BLAKE2sp? (nullptr if unknown)

// ---------- Output streams ----------
class OutStream {
public:
  FILE *f = nullptr;
  bool enabled = true;
  void Set(FILE *ff) { f = ff; }
  void Write(const std::string &s) { if (enabled && f) fwrite(s.data(), 1, s.size(), f); }
  void Write(const char *s) { if (enabled && f) fputs(s, f); }
  void Flush() { if (f) fflush(f); }
  OutStream &operator<<(const std::string &s) { Write(s); return *this; }
  OutStream &operator<<(const char *s) { Write(s); return *this; }
  OutStream &operator<<(char c) { if (enabled && f) fputc(c, f); return *this; }
  OutStream &operator<<(UInt64 v) { Write(UInt64ToStr(v)); return *this; }
  OutStream &operator<<(UInt32 v) { Write(UInt64ToStr(v)); return *this; }
  OutStream &operator<<(int v) { Write(Int64ToStr(v)); return *this; }
  OutStream &operator<<(unsigned long v) { Write(UInt64ToStr(v)); return *this; }
  OutStream &operator<<(long v) { Write(Int64ToStr(v)); return *this; }
};
extern OutStream g_StdOut;   // real stdout
extern OutStream g_StdErr;   // real stderr
extern OutStream *g_Out;     // message stream (may be null => disabled)
extern OutStream *g_Err;     // error stream
extern OutStream *g_Percent; // progress stream
