#define endl "\n"

inline void PrintNewLine(OutStream *s) { if (s) *s << "\n"; }

std::string ErrnoMessage(int err);        // "errno=2 : No such file or directory"
std::string HResultMessage(UInt32 hr);    // "E_NOTIMPL : Not implemented"

// ---------- misc ----------
std::string GetBaseName(const std::string &path);   // last path component
std::string GetDirPrefix(const std::string &path);  // with trailing slash or empty
