{"command":"cd /workspace/src && cat > common.cpp <<'EOF'
#include "common.h"
#include <ctime>
#include <cerrno>
#include <unistd.h>
#include <sys/time.h>

OutStream g_StdOut, g_StdErr;
OutStream *g_Out = &g_StdOut;
OutStream *g_Err = &g_StdErr;
OutStream *g_Percent = nullptr;
const char *endl_ = "\n";

std::string UInt64ToStr(UInt64 v) { char b[32]; snprintf(b, sizeof(b), "%llu", (unsigned long long)v); return b; }
std::string Int64ToStr(Int64 v) { char b[32]; snprintf(b, sizeof(b), "%lld", (long long)v); return b; }
std::string Hex8(UInt32 v) { char b[16]; snprintf(b, sizeof(b), "%08X", v); return b; }
std::string HexBytes(const Byte *p, size_t n, bool upper) {
  static const char *lo = "0123456789abcdef", *up = "0123456789ABCDEF";
  const char *d = upper ? up : lo;
  std::string s; s.reserve(n * 2);
  for (size_t i = 0; i < n; i++) { s += d[p[i] >> 4]; s += d[p[i] & 15]; }
  return s;
}
std::string ToLower(const std::string &s) { std::string r = s; for (auto &c : r) if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a'; return r; }
std::string ToUpper(const std::string &s) { std::string r = s; for (auto &c : r) if (c >= 'a' && c <= 'z') c = c - 'a' + 'A'; return r; }
bool StrEqNoCase(const std::string &a, const std::string &b) { return ToLower(a) == ToLower(b); }
bool StartsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool EndsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }
std::vector<std::string> SplitString(const std::string &s, char sep) {
  std::vector<std::string> r; std::string cur;
  for (char c : s) { if (c == sep) { r.push_back(cur); cur.clear(); } else cur += c; }
  r.push_back(cur); return r;
}
std::string Trim(const std::string &s) {
  size_t a = 0, b = s.size();
  while (a < b && (s[a] == ' ' || s[a] == '\t' || s[a] == '\r' || s[a] == '\n')) a++;
  while (b > a && (s[b-1] == ' ' || s[b-1] == '\t' || s[b-1] == '\r' || s[b-1] == '\n')) b--;
  return s.substr(a, b - a);
}
bool ParseUInt64(const std::string &s, UInt64 &v, size_t *endPos) {
  v = 0; size_t i = 0;
  for (; i < s.size() && s[i] >= '0' && s[i] <= '9'; i++) {
    if (v > (UInt64)-1 / 10) return false;
    v = v * 10 + (s[i] - '0');
  }
  if (endPos) *endPos = i;
  return i > 0;
}

std::u32string Utf8ToU32(const std::string &s) {
  std::u32string r;
  size_t i = 0, n = s.size();
  while (i < n) {
    unsigned c = (Byte)s[i++];
    if (c < 0x80) { r += (char32_t)c; continue; }
    unsigned need = 0; unsigned v = 0;
    if ((c & 0xE0) == 0xC0) { need = 1; v = c & 0x1F; }
    else if ((c & 0xF0) == 0xE0) { need = 2; v = c & 0x0F; }
    else if ((c & 0xF8) == 0xF0) { need = 3; v = c & 0x07; }
    else { r += (char32_t)(0xDC00 + c); continue; } // invalid byte -> map to low surrogate like 7-zip's escape
    if (i + need > n) { r += (char32_t)(0xDC00 + c); continue; }
    bool ok = true; unsigned vv = v;
    for (unsigned k = 0; k < need; k++) { unsigned cc = (Byte)s[i + k]; if ((cc & 0xC0) != 0x80) { ok = false; break; } vv = (vv << 6) | (cc & 0x3F); }
    if (!ok) { r += (char32_t)(0xDC00 + c); continue; }
    i += need; r += (char32_t)vv;
  }
  return r;
}
std::string U32ToUtf8(const std::u32string &s) {
  std::string r;
  for (char32_t c : s) {
    if (c >= 0xDC80 && c <= 0xDCFF) { r += (char)(c - 0xDC00); continue; }
