  const char *d = upper ? up : lo;
  std::string s; s.reserve(n * 2);
  for (size_t i = 0; i < n; i++) { s += d[p[i] >> 4]; s += d[p[i] & 15]; }
  return s;
}
std::string ToLower(const std::string &s) { std::string r = s; for (auto &c : r) if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a'; return r; }
std::string ToUpper(const std::string &s) { std::string r = s; for (auto &c : r) if (c >= 'a' && c <= 'z') c = c - 'a' + 'A'; return r; }
bool StrEqNoCase(const std::string &a, const std::string &b) { return ToLower(a) == ToLower(b); }
bool StartsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool EndsWith(const std::string &s, const std::string &p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }
std::vector<std::string> SplitString(const std::string &s, char sep) {
  std::vector<std::string> r; std::string cur;
  for (char c : s) { if (c == sep) { r.push_back(cur); cur.clear(); } else cur += c; }
  r.push_back(cur); return r;
}
std::string Trim(const std::string &s) {
  size_t a = 0, b = s.size();
  while (a < b && (s[a] == ' ' || s[a] == '\t' || s[a] == '\r' || s[a] == '\n')) a++;
  while (b > a && (s[b-1] == ' ' || s[b-1] == '\t' || s[b-1] == '\r' || s[b-1] == '\n')) b--;
  return s.substr(a, b - a);
}
bool ParseUInt64(const std::string &s, UInt64 &v, size_t *endPos) {
  v = 0; size_t i = 0;
  for (; i < s.size() && s[i] >= '0' && s[i] <= '9'; i++) {
    if (v > (UInt64)-1 / 10) return false;
    v = v * 10 + (s[i] - '0');
  }
  if (endPos) *endPos = i;
  return i > 0;
}

std::u32string Utf8ToU32(const std::string &s) {
  std::u32string r;
  size_t i = 0, n = s.size();
  while (i < n) {
    unsigned c = (Byte)s[i++];
    if (c < 0x80) { r += (char32_t)c; continue; }
    unsigned need = 0; unsigned v = 0;
    if ((c & 0xE0) == 0xC0) { need = 1; v = c & 0x1F; }
    else if ((c & 0xF0) == 0xE0) { need = 2; v = c & 0x0F; }
    else if ((c & 0xF8) == 0xF0) { need = 3; v = c & 0x07; }
    else { r += (char32_t)(0xDC00 + c); continue; } // invalid byte -> map to low surrogate like 7-zip's escape
    if (i + need > n) { r += (char32_t)(0xDC00 + c); continue; }
    bool ok = true; unsigned vv = v;
    for (unsigned k = 0; k < need; k++) { unsigned cc = (Byte)s[i + k]; if ((cc & 0xC0) != 0x80) { ok = false; break; } vv = (vv << 6) | (cc & 0x3F); }
    if (!ok) { r += (char32_t)(0xDC00 + c); continue; }
    i += need; r += (char32_t)vv;
  }
  return r;
}
std::string U32ToUtf8(const std::u32string &s) {
  std::string r;
  for (char32_t c : s) {
    if (c >= 0xDC80 && c <= 0xDCFF) { r += (char)(c - 0xDC00); continue; }
    if (c < 0x80) r += (char)c;
    else if (c < 0x800) { r += (char)(0xC0 | (c >> 6)); r += (char)(0x80 | (c & 0x3F)); }
    else if (c < 0x10000) { r += (char)(0xE0 | (c >> 12)); r += (char)(0x80 | ((c >> 6) & 0x3F)); r += (char)(0x80 | (c & 0x3F)); }
    else { r += (char)(0xF0 | (c >> 18)); r += (char)(0x80 | ((c >> 12) & 0x3F)); r += (char)(0x80 | ((c >> 6) & 0x3F)); r += (char)(0x80 | (c & 0x3F)); }
  }
  return r;
}
std::vector<uint16_t> Utf8ToUtf16(const std::string &s) {
  std::u32string u = Utf8ToU32(s);
  std::vector<uint16_t> r;
  for (char32_t c : u) {
    if (c >= 0x10000) { c -= 0x10000; r.push_back((uint16_t)(0xD800 + (c >> 10))); r.push_back((uint16_t)(0xDC00 + (c & 0x3FF))); }
    else r.push_back((uint16_t)c);
  }
  return r;
}
std::string Utf16ToUtf8(const std::vector<uint16_t> &w) {
  std::u32string u;
  for (size_t i = 0; i < w.size(); i++) {
    uint32_t c = w[i];
    if (c >= 0xD800 && c < 0xDC00 && i + 1 < w.size() && w[i+1] >= 0xDC00 && w[i+1] < 0xE000) {
      c = 0x10000 + ((c - 0xD800) << 10) + (w[i+1] - 0xDC00); i++;
    }
    u += (char32_t)c;
  }
  return U32ToUtf8(u);
}
std::string Utf16LEBytesToUtf8(const Byte *p, size_t numChars) {
  std::vector<uint16_t> w(numChars);
  for (size_t i = 0; i < numChars; i++) w[i] = (uint16_t)GetUi16(p + i * 2);
  return Utf16ToUtf8(w);
}
int CompareFileNames(const std::string &a, const std::string &b) {
  std::vector<uint16_t> wa = Utf8ToUtf16(a), wb = Utf8ToUtf16(b);
  size_t n = std::min(wa.size(), wb.size());
  for (size_t i = 0; i < n; i++) if (wa[i] != wb[i]) return wa[i] < wb[i] ? -1 : 1;
  if (wa.size() != wb.size()) return wa.size() < wb.size() ? -1 : 1;
  return 0;
}
int CompareFileNamesNoCase(const std::string &a, const std::string &b) {
  return CompareFileNames(ToUpper(a), ToUpper(b));
}

std::string SizeToString_Smart(UInt64 val) {
  std::string s = UInt64ToStr(val) + " bytes";
  if (val == 0) return s;
  unsigned numBits = 10; char c = 'K';
  if (val >= ((UInt64)10 << 30)) { numBits = 30; c = 'G'; }
  else if (val >= ((UInt64)10 << 20)) { numBits = 20; c = 'M'; }
  s += " (";
  s += UInt64ToStr((val + (((UInt64)1 << numBits) - 1)) >> numBits);
  s += ' '; s += c; s += "iB)";
  return s;
}
std::string FilesFoldersString(UInt64 numDirs, UInt64 numFiles, bool haveSize, UInt64 size, bool alwaysDirs) {
  std::string s;
  if (numDirs != 0 || alwaysDirs) { s += UInt64ToStr(numDirs); s += (numDirs == 1 ? " folder, " : " folders, "); }
  s += UInt64ToStr(numFiles); s += (numFiles == 1 ? " file" : " files");
  if (haveSize) { s += ", "; s += SizeToString_Smart(size); }
  return s;
}

void FileTimeToLocalTm(UInt64 ft, struct tm &t, UInt32 &sub) {
  Int64 sec = FileTimeToUnix(ft, &sub);
  time_t tt = (time_t)sec;
  localtime_r(&tt, &t);
}
std::string FileTimeToString(UInt64 ft, bool withTime, int prec, UInt32 ns) {
  struct tm t; UInt32 sub;
  FileTimeToLocalTm(ft, t, sub);
  char b[64];
  snprintf(b, sizeof(b), "%04d-%02d-%02d", t.tm_year + 1900, t.tm_mon + 1, t.tm_mday);
  std::string s = b;
  if (withTime) {
    snprintf(b, sizeof(b), " %02d:%02d:%02d", t.tm_hour, t.tm_min, t.tm_sec);
    s += b;
    if (prec == 7) { snprintf(b, sizeof(b), ".%07u", sub); s += b; }
    else if (prec == 9) { snprintf(b, sizeof(b), ".%09u", ns); s += b; }
    else if (prec >= 1 && prec <= 6) { snprintf(b, sizeof(b), ".%07u", sub); s += std::string(b).substr(0, 1 + prec); }
  }
  return s;
}
UInt64 CurrentFileTime() {
  struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);
  return UnixToFileTime(ts.tv_sec, (UInt32)ts.tv_nsec);
}
UInt64 LocalTmToFileTime(const struct tm &t0) {
  struct tm t = t0; t.tm_isdst = -1;
  time_t tt = mktime(&t);
  return UnixToFileTime((Int64)tt, 0);
}
UInt32 FileTimeToDosTime(UInt64 ft) {
  struct tm t; UInt32 sub;
  FileTimeToLocalTm(ft, t, sub);
  int year = t.tm_year + 1900;
  if (year < 1980) return (1 << 21) | (1 << 16); // 1980-01-01 00:00
  if (year > 2107) { year = 2107; }
  UInt32 d = ((UInt32)(year - 1980) << 9) | ((UInt32)(t.tm_mon + 1) << 5) | (UInt32)t.tm_mday;
  UInt32 tm = ((UInt32)t.tm_hour << 11) | ((UInt32)t.tm_min << 5) | ((UInt32)t.tm_sec >> 1);
  return (d << 16) | tm;
}
UInt64 DosTimeToFileTime(UInt32 dos) {
  struct tm t; memset(&t, 0, sizeof(t));
  t.tm_year = (int)((dos >> 25) & 0x7F) + 80;
  t.tm_mon = (int)((dos >> 21) & 0xF) - 1;
  t.tm_mday = (int)((dos >> 16) & 0x1F);
  t.tm_hour = (int)((dos >> 11) & 0x1F);
  t.tm_min = (int)((dos >> 5) & 0x3F);
  t.tm_sec = (int)((dos & 0x1F) * 2);
  return LocalTmToFileTime(t);
}

std::string AttribToString5(UInt32 wa, bool isDir) {
  std::string s = ".....";
  if (isDir) wa |= FILE_ATTRIBUTE_DIRECTORY_;
  if (wa & FILE_ATTRIBUTE_DIRECTORY_) s[0] = 'D';
  if (wa & FILE_ATTRIBUTE_READONLY_) s[1] = 'R';
  if (wa & FILE_ATTRIBUTE_HIDDEN_) s[2] = 'H';
  if (wa & FILE_ATTRIBUTE_SYSTEM_) s[3] = 'S';
  if (wa & FILE_ATTRIBUTE_ARCHIVE_) s[4] = 'A';
