std::string PosixModeToString(UInt32 a) {
  static const char kPosixTypes[16] = { '0', 'p', 'c', '3', 'd', '5', 'b', '7', '-', '9', 'l', 'B', 's', 'D', 'E', 'F' };
  char s[32];
  s[0] = kPosixTypes[(a >> 12) & 0xF];
  for (int i = 6; i >= 0; i -= 3) {
    s[7 - i] = (a & (1u << (i + 2))) ? 'r' : '-';
    s[8 - i] = (a & (1u << (i + 1))) ? 'w' : '-';
    s[9 - i] = (a & (1u << i)) ? 'x' : '-';
  }
  if (a & 0x800) s[3] = (a & (1 << 6)) ? 's' : 'S';
  if (a & 0x400) s[6] = (a & (1 << 3)) ? 's' : 'S';
  if (a & 0x200) s[9] = (a & 1) ? 't' : 'T';
  s[10] = 0;
  a &= ~(UInt32)0xFFF;
  std::string r = s;
  if (a != 0) { r += ' '; r += Hex8(a); }
  return r;
}
std::string AttribToStringFull(UInt32 wa) {
  static const char g_WinAttribChars[17] = "RHS8DAdNTsLCOIEV";
  bool isPosix = (wa & 0xF0000000) != 0;
  UInt32 posix = 0;
  if (isPosix) { posix = wa >> 16; wa &= 0x3FFF; }
  std::string s;
  for (unsigned i = 0; i < 16; i++) {
    UInt32 flag = 1u << i;
    if (wa & flag) { char c = g_WinAttribChars[i]; if (c) { s += c; wa &= ~flag; } }
  }
  if (wa != 0) { s += ' '; s += Hex8(wa); }
  if (isPosix) { s += ' '; s += PosixModeToString(posix); }
  return s;
}

// ---------- CRC32 ----------
static UInt32 g_crcTable[256];
static bool g_crcInit = false;
static void InitCrc() {
  if (g_crcInit) return;
  for (UInt32 i = 0; i < 256; i++) { UInt32 r = i; for (int j = 0; j < 8; j++) r = (r >> 1) ^ (0xEDB88320 & (0 - (r & 1))); g_crcTable[i] = r; }
  g_crcInit = true;
}
UInt32 Crc32Update(UInt32 crc, const void *data, size_t size) {
  InitCrc();
  const Byte *p = (const Byte *)data; crc = ~crc;
  for (size_t i = 0; i < size; i++) crc = g_crcTable[(crc ^ p[i]) & 0xFF] ^ (crc >> 8);
  return ~crc;
}
// ---------- CRC64 (ECMA-182, reflected) ----------
static UInt64 g_crc64Table[256];
static bool g_crc64Init = false;
UInt64 Crc64Update(UInt64 crc, const void *data, size_t size) {
  if (!g_crc64Init) {
    for (UInt32 i = 0; i < 256; i++) { UInt64 r = i; for (int j = 0; j < 8; j++) r = (r >> 1) ^ (0xC96C5795D7870F42ULL & (0 - (r & 1))); g_crc64Table[i] = r; }
    g_crc64Init = true;
  }
  const Byte *p = (const Byte *)data; crc = ~crc;
  for (size_t i = 0; i < size; i++) crc = g_crc64Table[(crc ^ p[i]) & 0xFF] ^ (crc >> 8);
  return ~crc;
}

