struct Xxh64Ctx {
  static const UInt64 P1 = 11400714785074694791ULL, P2 = 14029467366897019727ULL, P3 = 1609587929392839161ULL, P4 = 9650029242287828579ULL, P5 = 2870177450012600261ULL;
  UInt64 v[4]; UInt64 total; Byte buf[32]; unsigned bufLen;
  static UInt64 rotl(UInt64 x, int r) { return (x << r) | (x >> (64 - r)); }
  static UInt64 round(UInt64 acc, UInt64 in) { acc += in * P2; acc = rotl(acc, 31); acc *= P1; return acc; }
  static UInt64 merge(UInt64 acc, UInt64 val) { val = round(0, val); acc ^= val; acc = acc * P1 + P4; return acc; }
  void Init() { v[0] = P1 + P2; v[1] = P2; v[2] = 0; v[3] = 0 - P1; total = 0; bufLen = 0; }
  void Block(const Byte *p) { for (int i = 0; i < 4; i++) v[i] = round(v[i], GetUi64(p + i * 8)); }
  void Update(const Byte *p, size_t n) {
    total += n;
    while (n > 0) {
      if (bufLen == 0 && n >= 32) { Block(p); p += 32; n -= 32; continue; }
      size_t take = std::min(n, (size_t)(32 - bufLen));
      memcpy(buf + bufLen, p, take); bufLen += take; p += take; n -= take;
      if (bufLen == 32) { Block(buf); bufLen = 0; }
    }
  }
  UInt64 Final() {
    UInt64 h;
    if (total >= 32) {
      h = rotl(v[0], 1) + rotl(v[1], 7) + rotl(v[2], 12) + rotl(v[3], 18);
      h = merge(h, v[0]); h = merge(h, v[1]); h = merge(h, v[2]); h = merge(h, v[3]);
    } else h = P5;
    h += total;
    const Byte *p = buf; size_t n = bufLen;
    while (n >= 8) { UInt64 k = round(0, GetUi64(p)); h ^= k; h = rotl(h, 27) * P1 + P4; p += 8; n -= 8; }
    if (n >= 4) { h ^= (UInt64)GetUi32(p) * P1; h = rotl(h, 23) * P2 + P3; p += 4; n -= 4; }
    while (n > 0) { h ^= (*p) * P5; h = rotl(h, 11) * P1; p++; n--; }
