  void Init() override { c.Init(); } void Update(const void *d, size_t n) override { c.Update((const Byte*)d, n); }
  void Final(Byte *dg) override { c.Final(dg); } unsigned DigestSize() const override { return 32; } std::string Name() const override { return "SHA256"; } };
class HasherSha1 : public IHasher { Sha1Ctx c; public:
  void Init() override { c.Init(); } void Update(const void *d, size_t n) override { c.Update((const Byte*)d, n); }
  void Final(Byte *dg) override { c.Final(dg); } unsigned DigestSize() const override { return 20; } std::string Name() const override { return "SHA1"; } };
class HasherXxh64 : public IHasher { Xxh64Ctx c; public:
  void Init() override { c.Init(); } void Update(const void *d, size_t n) override { c.Update((const Byte*)d, n); }
  void Final(Byte *dg) override { SetUi64(dg, c.Final()); } unsigned DigestSize() const override { return 8; } std::string Name() const override { return "XXH64"; } };
}

std::unique_ptr<IHasher> CreateHasher(const std::string &name0) {
  std::string name = ToUpper(name0);
  std::unique_ptr<IHasher> h;
  if (name == "CRC32") h.reset(new HasherCrc32());
  else if (name == "CRC64") h.reset(new HasherCrc64());
  else if (name == "SHA256") h.reset(new HasherSha256());
  else if (name == "SHA1") h.reset(new HasherSha1());
  else if (name == "XXH64") h.reset(new HasherXxh64());
  if (h) h->Init();
  return h;
}

std::string ErrnoMessage(int err) {
  std::string s = "errno=" + Int64ToStr(err) + " : ";
  s += strerror(err);
  return s;
}
std::string HResultMessage(UInt32 hr) {
  switch (hr) {
    case E_NOTIMPL_: return "E_NOTIMPL : Not implemented";
    case E_NOINTERFACE_: return "E_NOINTERFACE : No such interface supported";
    case E_ABORT_: return "E_ABORT : Operation aborted";
    case E_FAIL_: return "E_FAIL : Unspecified error";
    case E_INVALIDARG_: return "E_INVALIDARG : One or more arguments are invalid";
    case E_OUTOFMEMORY_: return "E_OUTOFMEMORY : Can't allocate required memory";
    case S_FALSE_: return "S_FALSE : Incorrect function"; // approximation
  }
  if ((hr & 0xFFFF0000) == 0x80070000) return ErrnoMessage((int)(hr & 0xFFFF));
  char b[64]; snprintf(b, sizeof(b), "Unknown error 0x%08X", hr); return b;
}

std::string GetBaseName(const std::string &path) {
  size_t p = path.find_last_of('/');
  return p == std::string::npos ? path : path.substr(p + 1);
}
std::string GetDirPrefix(const std::string &path) {
  size_t p = path.find_last_of('/');
  return p == std::string::npos ? std::string() : path.substr(0, p + 1);
}
unsigned GetNumCpus() {
  long n = sysconf(_SC_NPROCESSORS_ONLN);
  return n <= 0 ? 1 : (unsigned)n;
}
