struct SwitchResult {
  bool thereIs = false;
  bool withMinus = false;
  int postCharIndex = -1;
  std::vector<std::string> postStrings;
};

struct Parser {
  SwitchResult sw[kNumSwitches];
  std::vector<std::string> nonSwitch;
  int stopSwitchIndex = -1;
};

static bool PrefixNoCase(const std::string &s, size_t pos, const char *key) {
  size_t n = strlen(key);
  if (pos + n > s.size()) return false;
  for (size_t i = 0; i < n; i++) {
    char a = s[pos + i], b = key[i];
    if (a >= 'A' && a <= 'Z') a = a - 'A' + 'a';
    if (b >= 'A' && b <= 'Z') b = b - 'A' + 'a';
    if (a != b) return false;
  }
  return true;
}

static void ParseSwitchString(Parser &p, const std::string &s) {
  size_t pos = 1;
  int maxLen = -1; unsigned switchIndex = 0;
  for (unsigned i = 0; i < kNumSwitches; i++) {
    const char *key = kSwitchForms[i].id;
    unsigned len = (unsigned)strlen(key);
    if ((int)len <= maxLen || pos + len > s.size()) continue;
    if (PrefixNoCase(s, pos, key)) { switchIndex = i; maxLen = (int)len; }
  }
  if (maxLen < 0) throw CmdLineException("Unknown switch:", s);
  pos += (unsigned)maxLen;
  SwitchResult &r = p.sw[switchIndex];
  const SwitchForm &form = kSwitchForms[switchIndex];
  if (!form.multi && r.thereIs) throw CmdLineException("Multiple instances for switch:", s);
  r.thereIs = true;
  size_t rem = s.size() - pos;
  if (rem < form.minLen) throw CmdLineException("Too short switch:", s);
  switch (form.type) {
    case kMinus:
      if (rem == 1) { r.withMinus = (s[pos] == '-'); if (r.withMinus) return; throw CmdLineException("Incorrect switch postfix:", s); }
      break;
    case kChar:
      if (rem == 1) {
        char c = s[pos];
        const char *f = strchr(form.charSet, c);
        if (c != 0 && f) { r.postCharIndex = (int)(f - form.charSet); return; }
        throw CmdLineException("Incorrect switch postfix:", s);
      }
      break;
    case kString:
      r.postStrings.push_back(s.substr(pos));
      return;
    default: break;
  }
  if (pos != s.size()) throw CmdLineException("Too long switch:", s);
}

static Parser g_parser;

bool DoesNameContainWildcard(const std::string &s) { return s.find('*') != std::string::npos || s.find('?') != std::string::npos; }

static bool WildMatch(const std::u32string &mask, size_t mi, const std::u32string &name, size_t ni) {
  for (;;) {
    if (mi == mask.size()) return ni == name.size();
    char32_t m = mask[mi];
    if (m == '*') {
      if (mi + 1 == mask.size()) return true;
      for (size_t k = ni; k <= name.size(); k++) if (WildMatch(mask, mi + 1, name, k)) return true;
      return false;
    }
    if (ni == name.size()) return false;
    if (m == '?' || m == name[ni]) { mi++; ni++; continue; }
    return false;
  }
}
extern bool g_CaseSensitive;
bool g_CaseSensitive = true;
bool DoesWildcardMatchName(const std::string &mask, const std::string &name) {
  if (g_CaseSensitive) return WildMatch(Utf8ToU32(mask), 0, Utf8ToU32(name), 0);
  return WildMatch(Utf8ToU32(ToUpper(mask)), 0, Utf8ToU32(ToUpper(name)), 0);
}
static bool NamesEqual(const std::string &a, const std::string &b) {
  if (g_CaseSensitive) return a == b;
  return ToUpper(a) == ToUpper(b);
}

std::vector<std::string> SplitPathToParts(const std::string &path) {
  std::vector<std::string> parts;
  std::string cur;
  for (char c : path) { if (c == '/') { parts.push_back(cur); cur.clear(); } else cur += c; }
  parts.push_back(cur);
  return parts;
}

static bool ItemCheckPath(const CensorItem &item, const std::vector<std::string> &pathParts, bool isFile) {
  if (!isFile && !item.forDir) return false;
  int delta = (int)pathParts.size() - (int)item.parts.size();
  if (delta < 0) return false;
  if (isFile && !item.forFile && delta == 0) return false;
  int start = 0, finish = 0;
  if (item.recursive) { finish = delta; }
  for (int d = start; d <= finish; d++) {
    size_t i;
    for (i = 0; i < item.parts.size(); i++) {
      if (item.wildcardMatching) { if (!DoesWildcardMatchName(item.parts[i], pathParts[i + d])) break; }
      else if (!NamesEqual(item.parts[i], pathParts[i + d])) break;
    }
    if (i == item.parts.size()) return true;
  }
  return false;
}

void CensorNode::AddItem(const CensorItem &item, bool include) {
  if (include) includeItems.push_back(item); else excludeItems.push_back(item);
}
void CensorNode::Add(const std::string &path, bool include, bool recursive, bool wildcardMatching) {
  CensorItem item;
  item.origPath = path;
  std::string p = path;
  item.recursive = recursive;
  item.wildcardMatching = wildcardMatching;
  if (!p.empty() && p.back() == '/') { item.forFile = false; item.isFromDirPath = true; p.pop_back(); }
  item.parts = SplitPathToParts(p);
  // remove empty leading parts? keep as is
  AddItem(item, include);
}
bool CensorNode::CheckPathParts(const std::vector<std::string> &parts, bool isFile) const {
  for (const auto &it : excludeItems) if (ItemCheckPath(it, parts, isFile)) return false;
  if (includeItems.empty()) return true;
  for (const auto &it : includeItems) if (ItemCheckPath(it, parts, isFile)) return true;
  return false;
}
bool CensorNode::CheckPath(const std::string &path, bool isFile) const {
  return CheckPathParts(SplitPathToParts(path), isFile);
}
bool CensorNode::AllAreRelative() const {
  for (const auto &it : includeItems) if (!it.parts.empty() && it.parts[0].empty()) return false;
  return true;
}

// -------- Phase 1 ---------
void ParseCommandLine1(const std::vector<std::string> &args, Options &o) {
  Parser &p = g_parser;
  bool stop = false;
  for (size_t i = 0; i < args.size(); i++) {
    const std::string &s = args[i];
    if (!stop && s == "--") { stop = true; p.stopSwitchIndex = (int)p.nonSwitch.size(); continue; }
    if (!stop && !s.empty() && s[0] == '-') { ParseSwitchString(p, s); continue; }
    p.nonSwitch.push_back(s);
  }
  o.nonSwitchStrings = p.nonSwitch;
  o.isInTerminal = isatty(0); o.isStdOutTerminal = isatty(1); o.isStdErrTerminal = isatty(2);
  o.helpMode = p.sw[kHelp1].thereIs || p.sw[kHelp2].thereIs || p.sw[kHelp3].thereIs;
  o.stdInMode = p.sw[kStdIn].thereIs;
  if (o.stdInMode && !p.sw[kStdIn].postStrings.empty()) o.stdInName = p.sw[kStdIn].postStrings[0];
  o.stdOutMode = p.sw[kStdOut].thereIs;
  o.enableHeaders = !p.sw[kDisableHeaders].thereIs;
  o.techMode = p.sw[kTechMode].thereIs;
  o.showTime = p.sw[kShowTime].thereIs;
  o.yesToAll = p.sw[kYes].thereIs;
  if (p.sw[kDisablePercents].thereIs || o.stdOutMode || !o.isStdOutTerminal) o.disablePercents = true;
  if (p.sw[kLogLevel].thereIs) {
    const std::string &s = p.sw[kLogLevel].postStrings[0];
    if (s.empty()) o.logLevel = 1;
    else {
      UInt64 v; size_t end;
      if (!ParseUInt64(s, v, &end) || end != s.size() || v > 0xFFFFFFFF) throw CmdLineException("Unsupported switch postfix -bb", s);
      o.logLevel = (unsigned)v;
    }
  }
  if (p.sw[kCaseSensitive].thereIs) { o.caseSensitiveChange = true; o.caseSensitive = !p.sw[kCaseSensitive].withMinus; o.caseSensitiveSet = true; }
  else o.caseSensitive = true;
  if (p.sw[kOutStream].thereIs) { o.numberForOut = p.sw[kOutStream].postCharIndex; o.outSet = true; }
  if (p.sw[kErrStream].thereIs) { o.numberForErrors = p.sw[kErrStream].postCharIndex; o.errSet = true; }
  if (p.sw[kPercentStream].thereIs) { o.numberForPercents = p.sw[kPercentStream].postCharIndex; o.percentSet = true; }
  if (p.sw[kLargePages].thereIs) {
    const std::string &s = p.sw[kLargePages].postStrings[0];
    if (s.empty()) o.largePages = true;
    else if (s != "-") {
      UInt64 v; size_t end;
      if (!ParseUInt64(s, v, &end) || end != s.size()) throw CmdLineException("Unsupported switch postfix for -slp", s);
      o.largePages = v != 0;
    }
  }
  if (p.sw[kAffinity].thereIs) {
    const std::string &s = p.sw[kAffinity].postStrings[0];
    if (!s.empty()) {
      UInt64 v = 0; bool ok = true;
      for (char c : s) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0'; else if (c >= 'a' && c <= 'f') d = c - 'a' + 10; else if (c >= 'A' && c <= 'F') d = c - 'A' + 10; else { ok = false; break; }
        v = (v << 4) | (UInt64)d;
      }
      if (!ok || s.size() > 16) throw CmdLineException("Unsupported switch postfix -stm", s);
      o.affinitySet = true; o.affinity = v;
    }
  }
}

static bool ParseCommand(const std::string &s0, CommandType &c) {
  std::string s = ToLower(s0);
  if (s == "a") c = kAdd; else if (s == "u") c = kUpdate; else if (s == "d") c = kDelete; else if (s == "t") c = kTest;
  else if (s == "e") c = kExtract; else if (s == "x") c = kExtractFull; else if (s == "l") c = kList; else if (s == "b") c = kBenchmark;
  else if (s == "i") c = kInfo; else if (s == "h") c = kHash; else if (s == "rn") c = kRename; else return false;
  return true;
}

static void ParseCharset(const std::string &s, bool allowNum) {
  std::string l = ToLower(s);
  if (l == "utf-8" || l == "win" || l == "dos") return;
  if (allowNum) { UInt64 v; size_t e; if (ParseUInt64(s, v, &e) && e == s.size()) return; }
  if (l == "utf-16le" || l == "utf-16be") { if (allowNum) return; }
  throw CmdLineException("Unsupported charset:", l);
}

static std::vector<std::string> ReadListFile(const std::string &name) {
  FILE *f = fopen(name.c_str(), "rb");
  if (!f) throw CmdLineException("The file operation error for listfile", ErrnoMessage(errno) + "\n" + name);
  std::string data; char buf[65536]; size_t n;
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0) data.append(buf, n);
  fclose(f);
  // strip BOM
  if (data.size() >= 3 && (Byte)data[0] == 0xEF && (Byte)data[1] == 0xBB && (Byte)data[2] == 0xBF) data = data.substr(3);
  std::vector<std::string> res;
  std::string cur;
  for (size_t i = 0; i <= data.size(); i++) {
    if (i == data.size() || data[i] == '\n' || data[i] == '\r') {
      // trim
      std::string t = cur;
      size_t a = 0, b = t.size();
      while (a < b && (t[a] == ' ' || t[a] == '\t')) a++;
      while (b > a && (t[b-1] == ' ' || t[b-1] == '\t')) b--;
      t = t.substr(a, b - a);
      if (!t.empty()) res.push_back(t);
      cur.clear();
    } else cur += data[i];
  }
  return res;
}

struct NameOption { bool include = true; int recursedType = 0; bool wildcardMatching = true; };

static void AddNameToCensor(CensorNode &censor, const NameOption &nop, const std::string &name) {
  bool recursive = false;
  if (nop.recursedType == 1) recursive = true;
  else if (nop.recursedType == 2) recursive = DoesNameContainWildcard(GetBaseName(name));
  censor.Add(name, nop.include, recursive, nop.wildcardMatching);
}

static void AddSwitchWildcardsToCensor(CensorNode &censor, const std::vector<std::string> &strings, const NameOption &nop0) {
  for (const std::string &name : strings) {
    NameOption nop = nop0;
    size_t pos = 0;
    // r[-|0]
    if (pos < name.size() && (name[pos] == 'r' || name[pos] == 'R')) {
      pos++; nop.recursedType = 1;
      if (pos < name.size()) { if (name[pos] == '-') { nop.recursedType = 0; pos++; } else if (name[pos] == '0') { nop.recursedType = 2; pos++; } }
    }
    // m[-|2]
    if (pos < name.size() && (name[pos] == 'm' || name[pos] == 'M')) {
      pos++; nop.wildcardMatching = false;
      if (pos < name.size()) { if (name[pos] == '-') { nop.wildcardMatching = true; pos++; } else if (name[pos] == '2') { pos++; } }
    }
    // w[-]
    if (pos < name.size() && (name[pos] == 'w' || name[pos] == 'W')) {
      pos++; nop.wildcardMatching = true;
      if (pos < name.size() && name[pos] == '-') { nop.wildcardMatching = false; pos++; }
    }
    if (name.size() < pos + 2) throw CmdLineException("Too short switch", name);
    char c = name[pos];
    std::string tail = name.substr(pos + 1);
    if (c == '@') {
      std::vector<std::string> lines = ReadListFile(tail);
      for (const auto &l : lines) AddNameToCensor(censor, nop, l);
    } else if (c == '!') {
      AddNameToCensor(censor, nop, tail);
    } else throw CmdLineException("Incorrect wildcard type marker", name);
  }
}

void ParseCommandLine2(Options &o) {
  Parser &p = g_parser;
  const std::vector<std::string> &ns = p.nonSwitch;
  if (ns.size() < 1) throw CmdLineException("The command must be specified");
  if (!ParseCommand(ns[0], o.command)) throw CmdLineException("Unsupported command:", ns[0]);
  if (p.sw[kCRC].thereIs) o.hashMethods = p.sw[kCRC].postStrings;
  if (p.sw[kElimDup].thereIs) { o.elimDupSet = true; o.elimDup = !p.sw[kElimDup].withMinus; }
  o.pathMode = 0;
  if (p.sw[kFullPathMode].thereIs) {
    o.pathMode = 1;
    const std::string &s = p.sw[kFullPathMode].postStrings[0];
    if (!s.empty()) { if (s == "2") o.pathMode = 2; else throw CmdLineException("Unsupported -spf:", s); }
  }
  if (p.sw[kConsoleCharSet].thereIs) { ParseCharset(p.sw[kConsoleCharSet].postStrings[0], false); o.consoleCodePage = p.sw[kConsoleCharSet].postStrings[0]; }
  if (p.sw[kListfileCharSet].thereIs) ParseCharset(p.sw[kListfileCharSet].postStrings[0], true);

  NameOption nop;
  if (p.sw[kRecursed].thereIs) {
    int idx = p.sw[kRecursed].postCharIndex;
    if (idx < 0) nop.recursedType = 1; else if (idx == 0) nop.recursedType = 2; else nop.recursedType = 0;
  } else nop.recursedType = 0;
  o.recurseMode = nop.recursedType;
  nop.wildcardMatching = !p.sw[kDisableWildcard].thereIs;
  o.disableWildcard = p.sw[kDisableWildcard].thereIs;
  g_CaseSensitive = o.caseSensitive;

  bool thereAreSwitchIncludes = false;
  if (p.sw[kInclude].thereIs) { thereAreSwitchIncludes = true; nop.include = true; AddSwitchWildcardsToCensor(o.censor, p.sw[kInclude].postStrings, nop); }
  if (p.sw[kExclude].thereIs) { nop.include = false; AddSwitchWildcardsToCensor(o.censor, p.sw[kExclude].postStrings, nop); }
  nop.include = true;

  size_t cur = 1;
  bool thereIsArchiveName = !p.sw[kNoArName].thereIs && o.command != kBenchmark && o.command != kInfo && o.command != kHash;
  o.disableArchiveName = p.sw[kNoArName].thereIs;
  bool isExtractGroup = (o.command == kExtract || o.command == kExtractFull || o.command == kTest);
  bool isExtractOrList = isExtractGroup || o.command == kList;
  bool isRename = o.command == kRename;
  if ((isExtractOrList || isRename) && o.stdInMode) thereIsArchiveName = false;
  if (p.sw[kArcNameMode].thereIs) o.arcNameMode = p.sw[kArcNameMode].postCharIndex;
  if (thereIsArchiveName) {
    if (cur >= ns.size()) throw CmdLineException("Cannot find archive name");
