  }
  // non-switch names
  {
    bool oldIndex = false; (void)oldIndex;
    std::vector<std::string> names;
    for (size_t i = cur; i < ns.size(); i++) {
      const std::string &s = ns[i];
      bool isStopped = p.stopSwitchIndex >= 0 && (int)i >= p.stopSwitchIndex;
      if (!isStopped && !s.empty() && s[0] == '@') {
        std::vector<std::string> lines = ReadListFile(s.substr(1));
