  }
  o.passwordEnabled = p.sw[kPassword].thereIs;
  if (o.passwordEnabled) o.password = p.sw[kPassword].postStrings[0];
  if (p.sw[kArchiveType].thereIs) { o.arcType = p.sw[kArchiveType].postStrings[0]; o.arcTypeSet = true; }
  o.excludedArcTypes = p.sw[kExcludedArcType].postStrings;
  // properties
  for (const std::string &s : p.sw[kProperty].postStrings) {
    Property prop;
    size_t eq = s.find('=');
    if (eq == std::string::npos) { prop.name = s; prop.hasValue = false; }
    else { prop.name = s.substr(0, eq); prop.value = s.substr(eq + 1); prop.hasValue = true; }
    o.properties.push_back(prop);
  }
  o.ntSecurity = p.sw[kNtSecurity].thereIs;
  if (p.sw[kAltStreams].thereIs) { o.altStreamsSet = true; o.altStreams = !p.sw[kAltStreams].withMinus; }
  if (p.sw[kHardLinks].thereIs) o.hardLinks = !p.sw[kHardLinks].withMinus;
  if (p.sw[kSymLinks].thereIs) o.symLinks = !p.sw[kSymLinks].withMinus;
  o.preserveATime = p.sw[kPreserveATime].thereIs;
  o.shareForWrite = p.sw[kShareForWrite].thereIs;
  o.stopAfterOpenError = p.sw[kStopAfterOpenError].thereIs;
  o.sdel = p.sw[kDeleteAfterCompressing].thereIs;
  o.setArcMTime = p.sw[kSetArcMTime].thereIs;
  o.email = p.sw[kEmail].thereIs;
  if (o.email && !p.sw[kEmail].postStrings.empty()) o.emailAddr = p.sw[kEmail].postStrings[0];
  o.sfxMode = p.sw[kSfx].thereIs;
  if (o.sfxMode) o.sfxModule = p.sw[kSfx].postStrings[0];
  if (p.sw[kWorkingDir].thereIs) { o.workDirSet = true; o.workDir = p.sw[kWorkingDir].postStrings[0]; }

  if (isExtractOrList) {
    NameOption anop; anop.recursedType = 0; anop.wildcardMatching = true;
    if (p.sw[kArInclude].thereIs) { anop.include = true; AddSwitchWildcardsToCensor(o.arcCensor, p.sw[kArInclude].postStrings, anop); }
    if (p.sw[kArExclude].thereIs) { anop.include = false; AddSwitchWildcardsToCensor(o.arcCensor, p.sw[kArExclude].postStrings, anop); }
    anop.include = true;
    if (thereIsArchiveName) AddNameToCensor(o.arcCensor, anop, o.archiveName);
    if (isExtractGroup) {
      if (p.sw[kOutputDir].thereIs) { o.outputDirSet = true; o.outputDir = p.sw[kOutputDir].postStrings[0]; if (!o.outputDir.empty() && o.outputDir.back() != '/') o.outputDir += '/'; }
      o.overwriteMode = -1;
      if (p.sw[kOverwrite].thereIs) o.overwriteMode = p.sw[kOverwrite].postCharIndex;
      else if (o.yesToAll) o.overwriteMode = 0;
    }
  } else if (o.command == kAdd || o.command == kUpdate || o.command == kDelete || o.command == kRename) {
    if (p.sw[kArInclude].thereIs) throw CmdLineException("-ai switch is not supported for this command");
    o.updateOptions = p.sw[kUpdate].postStrings;
    o.volumeStrings = p.sw[kVolume].postStrings;
    for (const std::string &v : o.volumeStrings) {
      UInt64 n; size_t end;
      if (!ParseUInt64(v, n, &end)) throw CmdLineException("Incorrect volume size:", v);
      std::string suf = ToLower(v.substr(end));
      if (suf == "" || suf == "b") {} else if (suf == "k") n <<= 10; else if (suf == "m") n <<= 20; else if (suf == "g") n <<= 30; else if (suf == "t") n <<= 40;
      else throw CmdLineException("Incorrect volume size:", v);
