    }
    if (o.stdOutMode && o.email) throw CmdLineException("stdout mode and email mode cannot be combined");
    if (o.stdOutMode && o.isStdOutTerminal) throw CmdLineException("I won't write compressed data to a terminal");
    if (p.sw[kOutputDir].thereIs) { o.outputDirSet = true; o.outputDir = p.sw[kOutputDir].postStrings[0]; }
  } else if (o.command == kBenchmark) {
    o.numIterations = 1; o.numIterationsSet = false;
    if (cur < ns.size()) {
      UInt64 v; size_t end;
      if (!ParseUInt64(ns[cur], v, &end) || end != ns[cur].size() || v > 0xFFFFFFFF) throw CmdLineException("Incorrect number of benchmark iterations", ns[cur]);
      o.numIterations = (UInt32)v; o.numIterationsSet = true;
    }
  } else if (o.command == kHash) {
  } else if (o.command == kInfo) {
  }
}
