struct SwitchResult {
  bool thereIs = false;
  bool withMinus = false;
  int postCharIndex = -1;
  std::vector<std::string> postStrings;
};

struct Parser {
  SwitchResult sw[kNumSwitches];
  std::vector<std::string> nonSwitch;
  int stopSwitchIndex = -1;
};

static bool PrefixNoCase(const std::string &s, size_t pos, const char *key) {
  size_t n = strlen(key);
  if (pos + n > s.size()) return false;
  for (size_t i = 0; i < n; i++) {
    char a = s[pos + i], b = key[i];
    if (a >= 'A' && a <= 'Z') a = a - 'A' + 'a';
    if (b >= 'A' && b <= 'Z') b = b - 'A' + 'a';
    if (a != b) return false;
  }
  return true;
}

static void ParseSwitchString(Parser &p, const std::string &s) {
  size_t pos = 1;
  int maxLen = -1; unsigned switchIndex = 0;
  for (unsigned i = 0; i < kNumSwitches; i++) {
    const char *key = kSwitchForms[i].id;
    unsigned len = (unsigned)strlen(key);
    if ((int)len <= maxLen || pos + len > s.size()) continue;
    if (PrefixNoCase(s, pos, key)) { switchIndex = i; maxLen = (int)len; }
  }
  if (maxLen < 0) throw CmdLineException("Unknown switch:", s);
  pos += (unsigned)maxLen;
  SwitchResult &r = p.sw[switchIndex];
  const SwitchForm &form = kSwitchForms[switchIndex];
  if (!form.multi && r.thereIs) throw CmdLineException("Multiple instances for switch:", s);
  r.thereIs = true;
  size_t rem = s.size() - pos;
  if (rem < form.minLen) throw CmdLineException("Too short switch:", s);
  switch (form.type) {
    case kMinus:
      if (rem == 1) { r.withMinus = (s[pos] == '-'); if (r.withMinus) return; throw CmdLineException("Incorrect switch postfix:", s); }
      break;
    case kChar:
      if (rem == 1) {
        char c = s[pos];
        const char *f = strchr(form.charSet, c);
        if (c != 0 && f) { r.postCharIndex = (int)(f - form.charSet); return; }
        throw CmdLineException("Incorrect switch postfix:", s);
      }
      break;
    case kString:
      r.postStrings.push_back(s.substr(pos));
      return;
    default: break;
  }
  if (pos != s.size()) throw CmdLineException("Too long switch:", s);
}

static Parser g_parser;

bool DoesNameContainWildcard(const std::string &s) { return s.find('*') != std::string::npos || s.find('?') != std::string::npos; }

static bool WildMatch(const std::u32string &mask, size_t mi, const std::u32string &name, size_t ni) {
  for (;;) {
    if (mi == mask.size()) return ni == name.size();
    char32_t m = mask[mi];
    if (m == '*') {
      if (mi + 1 == mask.size()) return true;
      for (size_t k = ni; k <= name.size(); k++) if (WildMatch(mask, mi + 1, name, k)) return true;
      return false;
    }
    if (ni == name.size()) return false;
    if (m == '?' || m == name[ni]) { mi++; ni++; continue; }
    return false;
  }
}
extern bool g_CaseSensitive;
bool g_CaseSensitive = true;
bool DoesWildcardMatchName(const std::string &mask, const std::string &name) {
  if (g_CaseSensitive) return WildMatch(Utf8ToU32(mask), 0, Utf8ToU32(name), 0);
  return WildMatch(Utf8ToU32(ToUpper(mask)), 0, Utf8ToU32(ToUpper(name)), 0);
}
static bool NamesEqual(const std::string &a, const std::string &b) {
  if (g_CaseSensitive) return a == b;
  return ToUpper(a) == ToUpper(b);
}

std::vector<std::string> SplitPathToParts(const std::string &path) {
  std::vector<std::string> parts;
  std::string cur;
  for (char c : path) { if (c == '/') { parts.push_back(cur); cur.clear(); } else cur += c; }
  parts.push_back(cur);
  return parts;
}

static bool ItemCheckPath(const CensorItem &item, const std::vector<std::string> &pathParts, bool isFile) {
  if (!isFile && !item.forDir) return false;
  int delta = (int)pathParts.size() - (int)item.parts.size();
  if (delta < 0) return false;
  if (isFile && !item.forFile && delta == 0) return false;
  int start = 0, finish = 0;
  if (item.recursive) { finish = delta; }
  for (int d = start; d <= finish; d++) {
    size_t i;
    for (i = 0; i < item.parts.size(); i++) {
      if (item.wildcardMatching) { if (!DoesWildcardMatchName(item.parts[i], pathParts[i + d])) break; }
      else if (!NamesEqual(item.parts[i], pathParts[i + d])) break;
    }
    if (i == item.parts.size()) return true;
  }
  return false;
}

void CensorNode::AddItem(const CensorItem &item, bool include) {
  if (include) includeItems.push_back(item); else excludeItems.push_back(item);
}
void CensorNode::Add(const std::string &path, bool include, bool recursive, bool wildcardMatching) {
  CensorItem item;
  item.origPath = path;
  std::string p = path;
  item.recursive = recursive;
  item.wildcardMatching = wildcardMatching;
  if (!p.empty() && p.back() == '/') { item.forFile = false; item.isFromDirPath = true; p.pop_back(); }
  item.parts = SplitPathToParts(p);
  // remove empty leading parts? keep as is
  AddItem(item, include);
}
bool CensorNode::CheckPathParts(const std::vector<std::string> &parts, bool isFile) const {
  for (const auto &it : excludeItems) if (ItemCheckPath(it, parts, isFile)) return false;
  if (includeItems.empty()) return true;
  for (const auto &it : includeItems) if (ItemCheckPath(it, parts, isFile)) return true;
  return false;
}
bool CensorNode::CheckPath(const std::string &path, bool isFile) const {
  return CheckPathParts(SplitPathToParts(path), isFile);
}
bool CensorNode::AllAreRelative() const {
  for (const auto &it : includeItems) if (!it.parts.empty() && it.parts[0].empty()) return false;
  return true;
}

// -------- Phase 1 ---------
void ParseCommandLine1(const std::vector<std::string> &args, Options &o) {
  Parser &p = g_parser;
  bool stop = false;
  for (size_t i = 0; i < args.size(); i++) {
    const std::string &s = args[i];
    if (!stop && s == "--") { stop = true; p.stopSwitchIndex = (int)p.nonSwitch.size(); continue; }
    if (!stop && !s.empty() && s[0] == '-') { ParseSwitchString(p, s); continue; }
    p.nonSwitch.push_back(s);
  }
  o.nonSwitchStrings = p.nonSwitch;
