static std::string GetLocaleString() {
  const char *s = setlocale(LC_ALL, "");
  if (!s || strcmp(s, "C") == 0 || strcmp(s, "POSIX") == 0) {
    const char *s2 = setlocale(LC_ALL, "C.UTF-8");
    if (s2) s = s2;
  }
  return s ? s : "";
}

