void CensorNode::Add(const std::string &path, bool include, bool recursive, bool wildcardMatching) {
  CensorItem item;
  item.origPath = path;
  std::string p = path;
  item.recursive = recursive;
  item.wildcardMatching = wildcardMatching;
  if (!p.empty() && p.back() == '/') { item.forFile = false; item.isFromDirPath = true; p.pop_back(); }
  std::vector<std::string> parts = SplitPathToParts(p);
  std::string phyPrefix;
  bool isAbs = !p.empty() && p[0] == '/';
  bool hasDots = false;
  for (const auto &pp : parts) if (pp == "." || pp == "..") hasDots = true;
  if (include && (isAbs || hasDots)) {
    // prefix mode: all leading parts go to physical prefix; last part is the item
    std::string last = parts.back();
    if (last == "." || last == "..") {
      phyPrefix = p + "/";
      parts.clear(); parts.push_back("*");
      item.wildcardMatching = true;
    } else {
      // find first wildcard part; prefix = parts before the last part (and before any wildcard)
      size_t cut = parts.size() - 1;
      for (size_t i = 0; i < parts.size(); i++) if (wildcardMatching && DoesNameContainWildcard(parts[i])) { cut = std::min(cut, i); break; }
      for (size_t i = 0; i < cut; i++) phyPrefix += parts[i] + "/";
      parts.erase(parts.begin(), parts.begin() + cut);
    }
  }
  // anchored prefix: leading parts without wildcards (not the last part)
  while (parts.size() > 1 && !(item.wildcardMatching && DoesNameContainWildcard(parts[0]))) {
    item.prefixParts.push_back(parts[0]);
    parts.erase(parts.begin());
  }
  item.parts = parts;
  if (include) { includeItems.push_back(item); includePhyPrefix.push_back(phyPrefix); }
  else excludeItems.push_back(item);
}
