#include "fs.h"
#include <dirent.h>
#include <unistd.h>
#include <cerrno>
#include <map>

UInt32 StatToAttrib(const struct stat &st) {
  UInt32 a = FILE_ATTRIBUTE_UNIX_EXTENSION_ | ((UInt32)(st.st_mode & 0xFFFF) << 16);
  if (S_ISDIR(st.st_mode)) a |= FILE_ATTRIBUTE_DIRECTORY_; else a |= FILE_ATTRIBUTE_ARCHIVE_;
  if (!(st.st_mode & S_IWUSR)) a |= FILE_ATTRIBUTE_READONLY_;
  return a;
}

bool FillDirItem(const std::string &phyPath, const std::string &logPath, DirItem &di, bool followLinks, int &err) {
  struct stat st;
  int r = followLinks ? stat(phyPath.c_str(), &st) : lstat(phyPath.c_str(), &st);
  if (r != 0) { err = errno; return false; }
  di.phyPath = phyPath; di.logPath = logPath;
  di.isDir = S_ISDIR(st.st_mode);
  di.isLink = S_ISLNK(st.st_mode);
  di.size = di.isDir ? 0 : (UInt64)st.st_size;
  di.mtime = st.st_mtim; di.atime = st.st_atim; di.ctime = st.st_ctim;
  di.mode = st.st_mode; di.uid = st.st_uid; di.gid = st.st_gid;
  di.inode = st.st_ino; di.dev = st.st_dev; di.nlink = st.st_nlink;
  di.attrib = StatToAttrib(st);
  return true;
}

bool ReadDirEntries(const std::string &dir, std::vector<std::string> &names, int &err) {
  DIR *d = opendir(dir.empty() ? "." : dir.c_str());
  if (!d) { err = errno; return false; }
  struct dirent *e;
  while ((e = readdir(d)) != nullptr) {
    if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
    names.push_back(e->d_name);
  }
  closedir(d);
  return true;
}

bool FileExists(const std::string &path, bool *isDir) {
  struct stat st;
  if (stat(path.c_str(), &st) != 0) return false;
  if (isDir) *isDir = S_ISDIR(st.st_mode);
  return true;
}

bool CreateDirs(const std::string &path) {
  if (path.empty()) return true;
  std::string p = path;
  if (p.back() == '/') p.pop_back();
  if (p.empty()) return true;
  struct stat st;
  if (stat(p.c_str(), &st) == 0) return S_ISDIR(st.st_mode);
  size_t pos = p.find_last_of('/');
  if (pos != std::string::npos) { if (!CreateDirs(p.substr(0, pos))) return false; }
  if (mkdir(p.c_str(), 0777) != 0) { if (errno == EEXIST) return true; return false; }
  return true;
}

std::string GetCwd() { char buf[4096]; if (getcwd(buf, sizeof(buf))) return buf; return ""; }

// ---------------- Enumeration -----------------
namespace {

struct ActiveItem { const CensorItem *item; size_t offset; };

struct Node {
  std::string name;
  std::vector<Node> subNodes;
  std::vector<const CensorItem *> items;
  Node *FindSub(const std::string &n) { for (auto &s : subNodes) if (s.name == n) return &s; return nullptr; }
  Node &GetSub(const std::string &n) { Node *s = FindSub(n); if (s) return *s; subNodes.push_back(Node()); subNodes.back().name = n; return subNodes.back(); }
};

struct Enumerator {
  const CensorNode &censor;
  DirItems &out;
  bool followLinks;
  std::string excludeArc;

  Enumerator(const CensorNode &c, DirItems &o, bool f) : censor(c), out(o), followLinks(f) {}

  bool IsExcluded(const std::string &logPath, bool isFile) {
    std::vector<std::string> parts = SplitPathToParts(logPath);
    for (const auto &it : censor.excludeItems) {
      // reuse censor logic via CheckPathParts on a temp node
      CensorNode tmp; tmp.excludeItems.push_back(it);
      if (!tmp.CheckPathParts(parts, isFile)) return true;
    }
    return false;
  }

  void AddItem(const DirItem &di) {
    out.items.push_back(di);
    if (di.isDir) out.numDirs++; else { out.numFiles++; out.totalSize += di.size; }
  }

  void AddError(const std::string &path, int err) { out.errors.push_back({path, err}); }

  // add all content of directory
  void EnumerateAll(const std::string &phyPrefix, const std::string &logPrefix) {
    if (out.onScanProgress) out.onScanProgress(phyPrefix);
    std::vector<std::string> names; int err;
    if (!ReadDirEntries(phyPrefix, names, err)) { AddError(phyPrefix, err); return; }
    for (const auto &name : names) {
      std::string phy = phyPrefix + name, log = logPrefix + name;
      DirItem di;
      if (!FillDirItem(phy, log, di, followLinks, err)) { AddError(phy, err); continue; }
      if (!excludeArc.empty() && phy == excludeArc) continue;
      if (IsExcluded(log, !di.isDir)) continue;
      AddItem(di);
      if (di.isDir) EnumerateAll(phy + "/", log + "/");
    }
  }

  void EnumerateForItem(const std::string &phy, const std::string &log) {
    DirItem di; int err;
    if (!FillDirItem(phy, log, di, followLinks, err)) { AddError(phy, err); return; }
    if (!excludeArc.empty() && phy == excludeArc) return;
    if (IsExcluded(log, !di.isDir)) return;
    AddItem(di);
    if (di.isDir) EnumerateAll(phy + "/", log + "/");
  }

  static bool PartMatch(const CensorItem &it, const std::string &pat, const std::string &name) {
    if (it.wildcardMatching) return DoesWildcardMatchName(pat, name);
    return pat == name;
  }

  void EnumerateNode(Node *node, const std::string &phyPrefix, const std::string &logPrefix, std::vector<ActiveItem> inherited) {
    std::vector<ActiveItem> active = inherited;
    bool anyRecursive = false;
    for (const auto &a : inherited) if (a.item->recursive) anyRecursive = true;
    if (node) for (const CensorItem *it : node->items) { active.push_back({it, 0}); if (it->recursive) anyRecursive = true; }
    // direct case
    bool allDirect = inherited.empty();
    if (allDirect) {
      if (!node) allDirect = false;
      else for (const CensorItem *it : node->items) {
        if (it->recursive || it->parts.size() != 1 || it->parts[0].empty() || (it->wildcardMatching && DoesNameContainWildcard(it->parts[0]))) { allDirect = false; break; }
      }
    }
    if (allDirect) {
      if (out.onScanProgress) out.onScanProgress(phyPrefix);
      for (const CensorItem *it : node->items) EnumerateForItem(phyPrefix + it->parts[0], logPrefix + it->parts[0]);
      for (Node &sub : node->subNodes) EnumerateNode(&sub, phyPrefix + sub.name + "/", logPrefix + sub.name + "/", {});
      return;
    }
    if (out.onScanProgress) out.onScanProgress(phyPrefix);
    std::vector<std::string> names; int err;
    if (!ReadDirEntries(phyPrefix, names, err)) { AddError(phyPrefix.empty() ? "." : phyPrefix, err); return; }
    for (const auto &name : names) {
      std::string phy = phyPrefix + name, log = logPrefix + name;
      DirItem di;
      if (!FillDirItem(phy, log, di, followLinks, err)) {
        // only report error if name would match
        bool wouldMatch = false;
        for (const auto &a : active) if (PartMatch(*a.item, a.item->parts[a.offset], name)) { wouldMatch = true; break; }
        if (wouldMatch) AddError(phy, err);
        continue;
      }
      if (!excludeArc.empty() && phy == excludeArc) continue;
      bool isFile = !di.isDir;
      bool included = false;
      std::vector<ActiveItem> partial;
      for (const auto &a : active) {
        const CensorItem &it = *a.item;
        if (!PartMatch(it, it.parts[a.offset], name)) continue;
        if (a.offset + 1 == it.parts.size()) {
          if (isFile && !it.forFile) continue;
          if (!isFile && !it.forDir) continue;
          included = true;
        } else if (di.isDir) partial.push_back({a.item, a.offset + 1});
      }
      if (included && IsExcluded(log, isFile)) included = false;
      if (included) {
        AddItem(di);
        if (di.isDir) EnumerateAll(phy + "/", log + "/");
        continue;
      }
      if (di.isDir) {
        Node *sub = node ? node->FindSub(name) : nullptr;
        std::vector<ActiveItem> next = partial;
        if (anyRecursive) for (const auto &a : active) if (a.item->recursive) next.push_back({a.item, 0});
        if (sub || !next.empty()) {
          if (IsExcluded(log, false)) continue;
          EnumerateNode(sub, phy + "/", log + "/", next);
        }
      }
    }
  }
};

} // namespace

void EnumerateItems(const CensorNode &censor, DirItems &dirItems, bool followLinks, const std::string &excludeArchivePath) {
  Enumerator en(censor, dirItems, followLinks);
  en.excludeArc = excludeArchivePath;
  // group include items by physical prefix (pairs), preserving first-appearance order
  std::vector<std::string> prefixes;
  std::vector<Node> roots;
  for (size_t i = 0; i < censor.includeItems.size(); i++) {
    const CensorItem &it = censor.includeItems[i];
    const std::string &pre = censor.includePhyPrefix[i];
    size_t idx = 0;
    for (; idx < prefixes.size(); idx++) if (prefixes[idx] == pre) break;
    if (idx == prefixes.size()) { prefixes.push_back(pre); roots.push_back(Node()); }
    Node *n = &roots[idx];
    for (const auto &pp : it.prefixParts) n = &n->GetSub(pp);
    n->items.push_back(&it);
  }
  for (size_t i = 0; i < roots.size(); i++) en.EnumerateNode(&roots[i], prefixes[i], "", {});
}
