      for (const CensorItem *it : node->items) EnumerateForItem(phyPrefix + it->parts[0], logPrefix + it->parts[0]);
      for (Node &sub : node->subNodes) EnumerateNode(&sub, phyPrefix + sub.name + "/", logPrefix + sub.name + "/", {});
      return;
    }
    if (out.onScanProgress) out.onScanProgress(phyPrefix);
    std::vector<std::string> names; int err;
    if (!ReadDirEntries(phyPrefix, names, err)) { AddError(phyPrefix.empty() ? "." : phyPrefix, err); return; }
    for (const auto &name : names) {
      std::string phy = phyPrefix + name, log = logPrefix + name;
      DirItem di;
      if (!FillDirItem(phy, log, di, followLinks, err)) {
        // only report error if name would match
        bool wouldMatch = false;
        for (const auto &a : active) if (PartMatch(*a.item, a.item->parts[a.offset], name)) { wouldMatch = true; break; }
        if (wouldMatch) AddError(phy, err);
        continue;
      }
      if (!excludeArc.empty() && phy == excludeArc) continue;
      bool isFile = !di.isDir;
      bool included = false;
      std::vector<ActiveItem> partial;
      for (const auto &a : active) {
        const CensorItem &it = *a.item;
        if (!PartMatch(it, it.parts[a.offset], name)) continue;
        if (a.offset + 1 == it.parts.size()) {
          if (isFile && !it.forFile) continue;
          if (!isFile && !it.forDir) continue;
          included = true;
        } else if (di.isDir) partial.push_back({a.item, a.offset + 1});
      }
      if (included && IsExcluded(log, isFile)) included = false;
      if (included) {
        AddItem(di);
        if (di.isDir) EnumerateAll(phy + "/", log + "/");
        continue;
      }
      if (di.isDir) {
        Node *sub = node ? node->FindSub(name) : nullptr;
        std::vector<ActiveItem> next = partial;
        if (anyRecursive) for (const auto &a : active) if (a.item->recursive) next.push_back({a.item, 0});
        if (sub || !next.empty()) {
          if (IsExcluded(log, false)) continue;
          EnumerateNode(sub, phy + "/", log + "/", next);
        }
      }
    }
  }
};

} // namespace

void EnumerateItems(const CensorNode &censor, DirItems &dirItems, bool followLinks, const std::string &excludeArchivePath) {
  Enumerator en(censor, dirItems, followLinks);
  en.excludeArc = excludeArchivePath;
  // group include items by physical prefix (pairs), preserving first-appearance order
  std::vector<std::string> prefixes;
  std::vector<Node> roots;
  for (size_t i = 0; i < censor.includeItems.size(); i++) {
    const CensorItem &it = censor.includeItems[i];
    const std::string &pre = censor.includePhyPrefix[i];
    size_t idx = 0;
    for (; idx < prefixes.size(); idx++) if (prefixes[idx] == pre) break;
    if (idx == prefixes.size()) { prefixes.push_back(pre); roots.push_back(Node()); }
    Node *n = &roots[idx];
    for (const auto &pp : it.prefixParts) n = &n->GetSub(pp);
    n->items.push_back(&it);
  }
  for (size_t i = 0; i < roots.size(); i++) en.EnumerateNode(&roots[i], prefixes[i], "", {});
}
