#include "commands.h"
#include "console.h"
#include <fcntl.h>
#include <unistd.h>

static const char *kCanonicalHashers[] = { "CRC32", "CRC64", "SHA256", "SHA1", "XXH64" };

struct HashState {
  std::unique_ptr<IHasher> hasher;
  std::vector<Byte> cur;      // current digest
  std::vector<Byte> dataSum;  // digestSize + 8 extra
  std::vector<Byte> namesSum;
  UInt64 numDataSums = 0, numNamesSums = 0;
};

static void AddDigests(std::vector<Byte> &dest, const Byte *src, unsigned size) {
  unsigned next = 0;
  for (unsigned i = 0; i < size; i++) { next += dest[i] + src[i]; dest[i] = (Byte)next; next >>= 8; }
  for (unsigned i = 0; i < 8; i++) { next += dest[size + i]; dest[size + i] = (Byte)next; next >>= 8; }
}

static std::string DigestToString(const Byte *d, unsigned size, bool upper) { return HexBytes(d, size, upper); }

static std::string SumToString(const HashState &h, const std::vector<Byte> &sum, UInt64 count) {
  unsigned ds = h.hasher->DigestSize();
  bool upper = ds <= 8;
  std::string s = DigestToString(sum.data(), ds, upper);
  if (count != 1) { s += '-'; s += Hex8(GetUi32(sum.data() + ds)); }
  return s;
}

int CommandHash(const Options &o) {
  std::vector<std::string> methods;
  if (o.hashMethods.empty()) methods.push_back("CRC32");
  else {
    bool all = false;
    for (const auto &m : o.hashMethods) if (m == "*") all = true;
    if (all) for (const char *c : kCanonicalHashers) methods.push_back(c);
    else {
      // canonical order
      for (const char *c : kCanonicalHashers) {
        for (const auto &m : o.hashMethods) if (StrEqNoCase(m, c)) { methods.push_back(c); break; }
      }
      for (const auto &m : o.hashMethods) {
        bool known = false;
        for (const char *c : kCanonicalHashers) if (StrEqNoCase(m, c)) known = true;
        if (!known) methods.push_back(m);
      }
    }
  }
  std::vector<HashState> hs;
  for (const auto &m : methods) {
    HashState h; h.hasher = CreateHasher(m);
    if (!h.hasher) throw SystemException((int)E_NOTIMPL_, false);
    unsigned ds = h.hasher->DigestSize();
    h.cur.assign(ds, 0); h.dataSum.assign(ds + 8, 0); h.namesSum.assign(ds + 8, 0);
    hs.push_back(std::move(h));
  }

  DirItems dirItems;
  if (!o.stdInMode) {
    if (g_Out) { *g_Out << "Scanning" << endl; g_Out->Flush(); }
    PercentPrinter pp; pp.s = g_Percent;
    EnumerateItems(o.censor, dirItems, true, "");
    for (const auto &e : dirItems.errors) PrintScanWarningsImmediate(e.path, e.err);
    if (g_Out) *g_Out << FilesFoldersString(dirItems.numDirs, dirItems.numFiles, true, dirItems.totalSize) << endl << endl;
  }

  // header
  std::string header, sep;
  for (auto &h : hs) {
    unsigned w = h.hasher->DigestSize() * 2;
    std::string n = h.hasher->Name();
    while (n.size() < w) n += ' ';
    header += n + " ";
    sep += std::string(w, '-') + " ";
  }
  header += "         Size  Name";
  sep += "-------------  ------------";
  if (g_Out) *g_Out << header << endl << sep << endl;

  UInt64 numFiles = 0, numDirs = 0, totalSize = 0;
  int errorsCount = 0;
  std::vector<Byte> buf(1 << 20);

  auto finalizeItem = [&](bool isDir, const std::string &path, UInt64 size) {
    Byte pre[16]; memset(pre, 0, sizeof(pre)); if (isDir) pre[0] = 1;
    std::vector<uint16_t> w = Utf8ToUtf16(path);
    std::string line;
    for (auto &h : hs) {
      unsigned ds = h.hasher->DigestSize();
      if (!isDir) { h.hasher->Final(h.cur.data()); AddDigests(h.dataSum, h.cur.data(), ds); h.numDataSums++; }
      else std::fill(h.cur.begin(), h.cur.end(), 0);
      h.hasher->Init();
      h.hasher->Update(pre, 16);
      h.hasher->Update(h.cur.data(), ds);
      for (uint16_t c : w) { Byte t[2] = { (Byte)c, (Byte)(c >> 8) }; h.hasher->Update(t, 2); }
      std::vector<Byte> tmp(ds); h.hasher->Final(tmp.data());
      AddDigests(h.namesSum, tmp.data(), ds); h.numNamesSums++;
      h.hasher->Init();
      if (isDir) line += std::string(ds * 2, ' ') + " ";
      else line += DigestToString(h.cur.data(), ds, ds <= 8) + " ";
    }
    if (isDir) { numDirs++; line += std::string(13, ' '); }
    else { numFiles++; totalSize += size; std::string sz = UInt64ToStr(size); while (sz.size() < 13) sz = " " + sz; line += sz; }
    line += "  ";
    line += path;
    if (isDir) line += "/";
    if (g_Out) *g_Out << line << endl;
  };

  if (o.stdInMode) {
    UInt64 size = 0;
    for (;;) {
      ssize_t n = read(0, buf.data(), buf.size());
      if (n < 0) throw SystemException(errno);
      if (n == 0) break;
      for (auto &h : hs) h.hasher->Update(buf.data(), (size_t)n);
      size += (UInt64)n;
    }
    finalizeItem(false, "[Content]", size);
  } else {
    for (const DirItem &di : dirItems.items) {
      if (di.isDir) { finalizeItem(true, di.logPath, 0); continue; }
      int fd = open(di.phyPath.c_str(), O_RDONLY);
      UInt64 size = 0;
      if (fd < 0) {
        int err = errno;
        if (g_Err) *g_Err << "ERROR: " << ErrnoMessage(err) << " : " << di.phyPath << endl;
        errorsCount++;
        continue;
      }
      for (;;) {
        ssize_t n = read(fd, buf.data(), buf.size());
        if (n < 0) { int err = errno; close(fd); throw SystemException(err); }
        if (n == 0) break;
        for (auto &h : hs) h.hasher->Update(buf.data(), (size_t)n);
        size += (UInt64)n;
      }
      close(fd);
      finalizeItem(false, di.logPath, size);
    }
  }

  if (g_Out) {
    *g_Out << sep << endl;
    std::string line;
    for (auto &h : hs) line += SumToString(h, h.dataSum, h.numDataSums) + " ";
    std::string sz = UInt64ToStr(totalSize); while (sz.size() < 13) sz = " " + sz;
    line += sz + "  ";
    *g_Out << line << endl << endl;
    if (numDirs != 0) *g_Out << "Folders: " << numDirs << endl;
    if (numFiles != 1 || numDirs != 0) *g_Out << "Files: " << numFiles << endl;
    *g_Out << "Size: " << totalSize << endl << endl;
    for (auto &h : hs) {
      std::string name = h.hasher->Name();
      while (name.size() < 6) name += ' ';
      std::string l1 = name + " for data:";
      while (l1.size() < 30) l1 += ' ';
      *g_Out << l1 << SumToString(h, h.dataSum, h.numDataSums) << endl;
      if (numFiles != 1 || numDirs != 0) {
        std::string l2 = name + " for data and names:";
        while (l2.size() < 30) l2 += ' ';
        *g_Out << l2 << SumToString(h, h.namesSum, h.numNamesSums) << endl;
      }
      *g_Out << endl;
    }
  }
  int ret = 0;
  if (!dirItems.errors.empty()) {
    if (g_Out) *g_Out << endl;
    PrintScanErrors(dirItems);
    ret = 1;
  }
  if (errorsCount != 0) {
    if (g_Out) *g_Out << endl << "Errors: " << errorsCount << endl;
    ret = 2;
  }
  if (ret == 0 && g_Out) *g_Out << "Everything is Ok" << endl;
  return ret;
}
