    }
    if (r != 0) { g_bz.dend(&s); throw DataError(); }
    if (s.avail_in == 0 && s.avail_out != 0) { g_bz.dend(&s); throw DataError("Unexpected end of data"); }
  }
  g_bz.dend(&s);
  if (unpackSize != (UInt64)-1 && outPos != unpackSize) throw DataError();
  out.resize(outPos);
  return out;
}

Buf CopyBuf(const Buf &in) { return in; }

// ---------------- BCJ x86 ----------------
static inline bool Test86MSByte(Byte b) { return ((b + 1) & 0xFE) == 0; }
static size_t x86_Convert(Byte *data, size_t size, UInt32 ip, UInt32 *state, int encoding) {
  size_t pos = 0;
  UInt32 mask = *state & 7;
  if (size < 5) return 0;
  size -= 4;
  ip += 5;
  for (;;) {
    Byte *p = data + pos;
    const Byte *limit = data + size;
    for (; p < limit; p++) if ((*p & 0xFE) == 0xE8) break;
    {
      size_t d = (size_t)(p - data - pos);
      pos = (size_t)(p - data);
      if (p >= limit) { *state = (d > 2 ? 0 : mask >> (unsigned)d); return pos; }
      if (d > 2) mask = 0;
      else {
        mask >>= (unsigned)d;
        if (mask != 0 && (mask > 4 || mask == 3 || Test86MSByte(p[(size_t)(mask >> 1) + 1]))) { mask = (mask >> 1) | 4; pos++; continue; }
      }
    }
    if (Test86MSByte(p[4])) {
      UInt32 v = ((UInt32)p[4] << 24) | ((UInt32)p[3] << 16) | ((UInt32)p[2] << 8) | ((UInt32)p[1]);
      UInt32 cur = ip + (UInt32)pos;
      pos += 5;
      if (encoding) v += cur; else v -= cur;
      if (mask != 0) {
        unsigned sh = (mask & 6) << 2;
        if (Test86MSByte((Byte)(v >> sh))) {
          v ^= (((UInt32)0x100 << sh) - 1);
          if (encoding) v += cur; else v -= cur;
        }
        mask = 0;
      }
      p[1] = (Byte)v; p[2] = (Byte)(v >> 8); p[3] = (Byte)(v >> 16); p[4] = (Byte)(0 - ((v >> 24) & 1));
    } else { mask = (mask >> 1) | 4; pos++; }
  }
}
Buf BcjX86Encode(const Buf &in) { Buf out = in; UInt32 state = 0; x86_Convert(out.data(), out.size(), 0, &state, 1); return out; }
Buf BcjX86Decode(const Buf &in) { Buf out = in; UInt32 state = 0; x86_Convert(out.data(), out.size(), 0, &state, 0); return out; }

Buf DeltaEncode(const Buf &in, unsigned delta) {
  Buf out(in.size());
  for (size_t i = 0; i < in.size(); i++) out[i] = (Byte)(in[i] - (i >= delta ? in[i - delta] : 0));
  return out;
}
Buf DeltaDecode(const Buf &in, unsigned delta) {
  Buf out(in.size());
  for (size_t i = 0; i < in.size(); i++) out[i] = (Byte)(in[i] + (i >= delta ? out[i - delta] : 0));
  return out;
}

static void ArmConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3; ip += 8;
  for (size_t i = 0; i < size; i += 4) {
    if (data[i + 3] == 0xEB) {
      UInt32 src = ((UInt32)data[i + 2] << 16) | ((UInt32)data[i + 1] << 8) | data[i + 0];
      src <<= 2;
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      dest >>= 2;
      data[i + 2] = (Byte)(dest >> 16); data[i + 1] = (Byte)(dest >> 8); data[i + 0] = (Byte)dest;
    }
  }
}
static void ArmtConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  if (size < 4) return;
  size -= 4; ip += 4;
  for (size_t i = 0; i <= size; i += 2) {
    if ((data[i + 1] & 0xF8) == 0xF0 && (data[i + 3] & 0xF8) == 0xF8) {
      UInt32 src = (((UInt32)data[i + 1] & 0x7) << 19) | ((UInt32)data[i + 0] << 11) | (((UInt32)data[i + 3] & 0x7) << 8) | data[i + 2];
      src <<= 1;
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      dest >>= 1;
      data[i + 1] = (Byte)(0xF0 | ((dest >> 19) & 0x7)); data[i + 0] = (Byte)(dest >> 11);
      data[i + 3] = (Byte)(0xF8 | ((dest >> 8) & 0x7)); data[i + 2] = (Byte)dest;
      i += 2;
    }
  }
}
static void PpcConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3;
  for (size_t i = 0; i < size; i += 4) {
    if ((data[i] >> 2) == 0x12 && (data[i + 3] & 3) == 1) {
      UInt32 src = (((UInt32)data[i + 0] & 3) << 24) | ((UInt32)data[i + 1] << 16) | ((UInt32)data[i + 2] << 8) | ((UInt32)data[i + 3] & ~(UInt32)3);
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      data[i + 0] = (Byte)(0x48 | ((dest >> 24) & 0x3)); data[i + 1] = (Byte)(dest >> 16); data[i + 2] = (Byte)(dest >> 8);
      data[i + 3] &= 0x3; data[i + 3] |= (Byte)dest;
    }
  }
}
static void SparcConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3;
  for (size_t i = 0; i < size; i += 4) {
    if ((data[i] == 0x40 && (data[i + 1] & 0xC0) == 0x00) || (data[i] == 0x7F && (data[i + 1] & 0xC0) == 0xC0)) {
      UInt32 src = ((UInt32)data[i + 0] << 24) | ((UInt32)data[i + 1] << 16) | ((UInt32)data[i + 2] << 8) | ((UInt32)data[i + 3]);
      src <<= 2;
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      dest >>= 2;
      dest = (((0 - ((dest >> 22) & 1)) << 22) & 0x3FFFFFFF) | (dest & 0x3FFFFF) | 0x40000000;
      data[i + 0] = (Byte)(dest >> 24); data[i + 1] = (Byte)(dest >> 16); data[i + 2] = (Byte)(dest >> 8); data[i + 3] = (Byte)dest;
    }
  }
}
static Buf BranchConvert(UInt64 method, const Buf &in, int encoding) {
  Buf out = in;
  switch (method) {
    case k_BCJ: { UInt32 st = 0; x86_Convert(out.data(), out.size(), 0, &st, encoding); break; }
    case k_ARM: ArmConvert(out.data(), out.size(), 0, encoding); break;
    case k_ARMT: ArmtConvert(out.data(), out.size(), 0, encoding); break;
    case k_PPC: PpcConvert(out.data(), out.size(), 0, encoding); break;
    case k_SPARC: SparcConvert(out.data(), out.size(), 0, encoding); break;
    default: throw UnsupportedMethod();
  }
  return out;
}
Buf BranchDecode(UInt64 method, const Buf &in, const Byte *props, size_t propsSize) { (void)props; (void)propsSize; return BranchConvert(method, in, 0); }
Buf BranchEncode(UInt64 method, const Buf &in) { return BranchConvert(method, in, 1); }

Buf Swap2(const Buf &in) { Buf o = in; for (size_t i = 0; i + 1 < o.size(); i += 2) std::swap(o[i], o[i+1]); return o; }
Buf Swap4(const Buf &in) { Buf o = in; for (size_t i = 0; i + 3 < o.size(); i += 4) { std::swap(o[i], o[i+3]); std::swap(o[i+1], o[i+2]); } return o; }

// ---------------- BCJ2 decoder ----------------
Buf Bcj2Decode(const Buf &buf0, const Buf &buf1, const Buf &buf2, const Buf &buf3, UInt64 unpackSize) {
  Buf out; out.reserve((size_t)unpackSize);
  UInt16 probs[2 + 256];
  for (auto &p : probs) p = 1024;
  size_t in0 = 0, in1 = 0, in2 = 0, in3 = 0;
  if (buf3.size() < 5) throw DataError();
  UInt32 code = 0, range = 0xFFFFFFFF;
  for (int i = 0; i < 5; i++) code = (code << 8) | buf3[in3++];
  Byte prevByte = 0;
  auto IsJ = [](Byte b0, Byte b1) { return (b1 & 0xFE) == 0xE8 || (b0 == 0x0F && (b1 & 0xF0) == 0x80); };
  while (out.size() < unpackSize) {
    if (in0 >= buf0.size()) throw DataError();
    Byte b = buf0[in0++];
    out.push_back(b);
    if (!IsJ(prevByte, b)) { prevByte = b; continue; }
    if (out.size() >= unpackSize) break;
    UInt16 *prob = (b == 0xE8) ? &probs[prevByte] : (b == 0xE9 ? &probs[256] : &probs[257]);
    UInt32 bound = (range >> 11) * (*prob);
    unsigned bit;
    if (code < bound) { range = bound; *prob = (UInt16)(*prob + ((2048 - *prob) >> 5)); bit = 0; }
    else { range -= bound; code -= bound; *prob = (UInt16)(*prob - (*prob >> 5)); bit = 1; }
    if (range < (1u << 24)) { range <<= 8; if (in3 >= buf3.size()) throw DataError(); code = (code << 8) | buf3[in3++]; }
    if (bit == 0) { prevByte = b; continue; }
    UInt32 src;
    if (b == 0xE8) { if (in1 + 4 > buf1.size()) throw DataError(); src = GetBe32(buf1.data() + in1); in1 += 4; }
    else { if (in2 + 4 > buf2.size()) throw DataError(); src = GetBe32(buf2.data() + in2); in2 += 4; }
    UInt32 dest = src - (UInt32)(out.size() + 4);
    out.push_back((Byte)dest); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 8)); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 16)); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 24));
    prevByte = (Byte)(dest >> 24);
  }
  if (out.size() != unpackSize) throw DataError();
  return out;
}

