namespace {
Byte g_sbox[256], g_inv[256]; bool g_aesInit = false;
inline Byte xtime(Byte x) { return (Byte)((x << 1) ^ ((x & 0x80) ? 0x1B : 0)); }
Byte gmul(Byte a, Byte b) { Byte r = 0; while (b) { if (b & 1) r ^= a; a = xtime(a); b >>= 1; } return r; }
void InitAes() {
