  for (unsigned i = 0; i < nk; i++) w[i] = GetBe32(key + i * 4);
  UInt32 rcon = 1;
  for (unsigned i = nk; i < total; i++) {
    UInt32 t = w[i - 1];
    if (i % nk == 0) {
      t = (t << 8) | (t >> 24);
      t = ((UInt32)g_sbox[t >> 24] << 24) | ((UInt32)g_sbox[(t >> 16) & 0xFF] << 16) | ((UInt32)g_sbox[(t >> 8) & 0xFF] << 8) | g_sbox[t & 0xFF];
      t ^= rcon << 24; rcon = xtime((Byte)rcon);
    } else if (nk > 6 && i % nk == 4) {
      t = ((UInt32)g_sbox[t >> 24] << 24) | ((UInt32)g_sbox[(t >> 16) & 0xFF] << 16) | ((UInt32)g_sbox[(t >> 8) & 0xFF] << 8) | g_sbox[t & 0xFF];
