static void AddRoundKey(Byte *s, const UInt32 *w) { for (int c = 0; c < 4; c++) { UInt32 k = w[c]; s[c*4] ^= (Byte)(k >> 24); s[c*4+1] ^= (Byte)(k >> 16); s[c*4+2] ^= (Byte)(k >> 8); s[c*4+3] ^= (Byte)k; } }
