    Byte t[16];
    for (int c = 0; c < 4; c++) for (int rr = 0; rr < 4; rr++) t[((c + rr) % 4) * 4 + rr] = s[c*4 + rr];
    for (int i = 0; i < 16; i++) t[i] = g_inv[t[i]];
