static void Aes7zDeriveKey(const Byte *salt, unsigned saltSize, unsigned numCyclesPower, const std::string &password, Byte key[32]) {
  std::vector<uint16_t> w = Utf8ToUtf16(password);
  Buf pw; for (uint16_t c : w) { pw.push_back((Byte)c); pw.push_back((Byte)(c >> 8)); }
  if (numCyclesPower == 0x3F) {
    memset(key, 0, 32);
    unsigned pos = 0;
    for (unsigned i = 0; i < saltSize && pos < 32; i++) key[pos++] = salt[i];
    for (unsigned i = 0; i < pw.size() && pos < 32; i++) key[pos++] = pw[i];
    return;
  }
  Sha256 sha; sha.Init();
  Byte counter[8]; memset(counter, 0, 8);
  UInt64 numRounds = (UInt64)1 << numCyclesPower;
  Buf block; block.insert(block.end(), salt, salt + saltSize); block.insert(block.end(), pw.begin(), pw.end()); block.insert(block.end(), counter, counter + 8);
  size_t ctrPos = block.size() - 8;
  for (UInt64 r = 0; r < numRounds; r++) {
    sha.Update(block.data(), block.size());
    for (unsigned i = 0; i < 8; i++) if (++block[ctrPos + i] != 0) break;
  }
  sha.Final(key);
}

Buf Aes7zDecode(const Byte *props, size_t propsSize, const Buf &in, UInt64 unpackSize, const std::string &password) {
  if (propsSize < 1) throw UnsupportedMethod();
  Byte b0 = props[0];
  unsigned numCyclesPower = b0 & 0x3F;
  unsigned saltSize = 0, ivSize = 0;
  size_t pos = 1;
  if ((b0 & 0xC0) != 0) {
    if (propsSize < 2) throw UnsupportedMethod();
    Byte b1 = props[1]; pos = 2;
    saltSize = ((b0 >> 7) & 1) ? ((b1 >> 4) + 1) : 0;
    ivSize = ((b0 >> 6) & 1) ? ((b1 & 0x0F) + 1) : 0;
  }
  if (propsSize < pos + saltSize + ivSize) throw UnsupportedMethod();
  const Byte *salt = props + pos; const Byte *ivp = props + pos + saltSize;
  Byte iv[16]; memset(iv, 0, 16); memcpy(iv, ivp, ivSize > 16 ? 16 : ivSize);
  Byte key[32]; Aes7zDeriveKey(salt, saltSize, numCyclesPower, password, key);
  UInt32 w[60]; AesSetKey(key, 32, w, true);
  Buf out(in.size() & ~(size_t)15);
  Byte prev[16]; memcpy(prev, iv, 16);
  for (size_t i = 0; i + 16 <= in.size(); i += 16) {
    Byte blk[16]; memcpy(blk, in.data() + i, 16);
    Byte c[16]; memcpy(c, blk, 16);
    AesDecryptBlock(w, 14, blk);
    for (int k = 0; k < 16; k++) out[i + k] = blk[k] ^ prev[k];
    memcpy(prev, c, 16);
  }
  if (unpackSize != (UInt64)-1) { if (unpackSize > out.size()) throw DataError(); out.resize((size_t)unpackSize); }
  return out;
}

static void FillRandom(Byte *p, size_t n) {
  FILE *f = fopen("/dev/urandom", "rb");
  if (f) { size_t r = fread(p, 1, n, f); (void)r; fclose(f); }
  else for (size_t i = 0; i < n; i++) p[i] = (Byte)rand();
}

Buf Aes7zEncode(const Buf &in, const std::string &password, Buf &propsOut) {
  Byte iv[16]; memset(iv, 0, 16); FillRandom(iv, 8);
  unsigned numCyclesPower = 19;
  propsOut.clear();
  propsOut.push_back((Byte)(numCyclesPower | 0x40)); // has IV
  propsOut.push_back((Byte)(8 - 1));                 // IV size 8
  propsOut.insert(propsOut.end(), iv, iv + 8);
  Byte key[32]; Aes7zDeriveKey(nullptr, 0, numCyclesPower, password, key);
  UInt32 w[60]; AesSetKey(key, 32, w, false);
  size_t padded = (in.size() + 15) & ~(size_t)15;
  Buf out(padded);
  Byte prev[16]; memcpy(prev, iv, 16);
  for (size_t i = 0; i < padded; i += 16) {
    Byte blk[16];
    for (int k = 0; k < 16; k++) blk[k] = (Byte)(((i + k < in.size()) ? in[i + k] : 0) ^ prev[k]);
    AesEncryptBlock(w, 14, blk);
    memcpy(out.data() + i, blk, 16); memcpy(prev, blk, 16);
  }
  return out;
}

// ---------------- xz container ----------------
static void WriteVli(Buf &b, UInt64 v) { while (v >= 0x80) { b.push_back((Byte)(v | 0x80)); v >>= 7; } b.push_back((Byte)v); }
static bool ReadVli(const Byte *p, size_t size, size_t &pos, UInt64 &v) {
  v = 0; unsigned shift = 0;
  while (pos < size) { Byte b = p[pos++]; v |= (UInt64)(b & 0x7F) << shift; if (!(b & 0x80)) return true; shift += 7; if (shift > 63) return false; }
