static unsigned XzCheckSize(unsigned t) { if (t == 0) return 0; if (t <= 3) return 4; if (t <= 6) return 8; if (t <= 9) return 16; if (t <= 12) return 32; return 64; }

Buf XzEncode(const Buf &in, LzmaProps &props, unsigned checkType, UInt64 blockSize, unsigned numThreads) {
  props.Normalize();
