    size_t n = (size_t)std::min<UInt64>(blockSize, in.size() - pos);
    // block header
    Buf hdr; hdr.push_back(0); hdr.push_back(0x00); hdr.push_back(0x21); hdr.push_back(0x01); hdr.push_back(propByte);
