    out.insert(out.end(), data.begin(), data.end());
    while (out.size() % 4 != 0) out.push_back(0);
    if (checkType == 1) { Byte c[4]; SetUi32(c, Crc32Calc(in.data() + pos, n)); out.insert(out.end(), c, c + 4); }
