    // skip stream padding (zeros, multiple of 4)
    while (end >= 4 && GetUi32(in.data() + end - 4) == 0 && !(in[end-2] == 'Y' && in[end-1] == 'Z')) end -= 4;
    if (end < 12) break;
    const Byte *footer = in.data() + end - 12;
    if (footer[10] != 'Y' || footer[11] != 'Z') return info.numStreams > 0;
    UInt64 backSize = ((UInt64)GetUi32(footer + 4) + 1) * 4;
    if (backSize + 12 > end) return false;
    const Byte *idx = footer - backSize;
    size_t p = 0; UInt64 nrec;
    if (idx[0] != 0) return false; p = 1;
    if (!ReadVli(idx, (size_t)backSize, p, nrec)) return false;
    UInt64 blocksSize = 0;
    for (UInt64 i = 0; i < nrec; i++) {
      UInt64 unpadded, usize;
      if (!ReadVli(idx, (size_t)backSize, p, unpadded) || !ReadVli(idx, (size_t)backSize, p, usize)) return false;
      blocksSize += (unpadded + 3) & ~(UInt64)3;
      info.unpackSize += usize;
    }
    info.numBlocks += nrec;
    info.numStreams++;
    UInt64 streamStart = end - 12 - backSize - blocksSize - 12;
    if ((Int64)streamStart < 0) return false;
    // parse first block header for method
    if (nrec > 0 && method.empty()) {
      const Byte *bh = in.data() + streamStart + 12;
      unsigned hs = ((unsigned)bh[0] + 1) * 4;
      unsigned nf = (bh[1] & 3) + 1;
      size_t q = 2;
      if (bh[1] & 0x40) { UInt64 v; ReadVli(bh, hs, q, v); }
      if (bh[1] & 0x80) { UInt64 v; ReadVli(bh, hs, q, v); }
      for (unsigned f = 0; f < nf; f++) {
        UInt64 fid, psz; if (!ReadVli(bh, hs, q, fid) || !ReadVli(bh, hs, q, psz)) break;
        std::string m;
        if (fid == 0x21) { m = "LZMA2"; if (psz == 1) { Byte d = bh[q]; m += ":"; if ((d & 1) == 0) m += UInt64ToStr(d / 2 + 12); else m += DictSizeToString((UInt32)3 << (d / 2 + 11)); } }
        else if (fid == 4) m = "x86"; else if (fid == 5) m = "PowerPC"; else if (fid == 6) m = "IA64"; else if (fid == 7) m = "ARM"; else if (fid == 8) m = "ARMT"; else if (fid == 9) m = "SPARC"; else if (fid == 0xA) m = "ARM64"; else if (fid == 0xB) m = "RISCV"; else if (fid == 3) m = "Delta";
        else { char b[32]; snprintf(b, sizeof(b), "%llX", (unsigned long long)fid); m = b; }
        q += (size_t)psz;
        if (!method.empty()) method += " ";
        method += m;
      }
    }
    end = (size_t)streamStart;
  }
  static const char *checkNames[16] = { "None", "CRC32", "", "", "CRC64", "", "", "", "", "", "SHA256", "", "", "", "", "" };
  std::string cn = checkNames[info.checkType & 15];
  if (cn.empty()) { char b[32]; snprintf(b, sizeof(b), "Check-%u", info.checkType); cn = b; }
  info.methodString = method + (method.empty() ? "" : " ") + cn;
  info.ok = info.numStreams > 0;
  return info.ok;
}

bool XzDecode(const Buf &in, Buf &out, XzInfo &info) {
  XzParseInfo(in, info);
  lzma_stream strm = LZMA_STREAM_INIT;
  if (lzma_stream_decoder(&strm, UINT64_MAX, LZMA_CONCATENATED) != LZMA_OK) throw std::runtime_error("xz init");
  out.clear();
  if (info.ok) out.resize((size_t)info.unpackSize); else out.resize(in.size() * 4 + 65536);
  strm.next_in = in.data(); strm.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) out.resize(out.size() * 2 + 65536);
    strm.next_out = out.data() + outPos; strm.avail_out = out.size() - outPos;
    lzma_ret r = lzma_code(&strm, LZMA_FINISH);
    outPos = out.size() - strm.avail_out;
    if (r == LZMA_STREAM_END) break;
    if (r != LZMA_OK) { lzma_end(&strm); out.resize(outPos); if (r == LZMA_BUF_ERROR) throw DataError("Unexpected end of data"); throw DataError(); }
  }
  lzma_end(&strm);
  out.resize(outPos);
  return true;
}

Buf LzmaAloneDecode(const Buf &in, UInt64 &unpackSize, bool &sizeKnown) {
  if (in.size() < 13) throw DataError();
  UInt64 us = GetUi64(in.data() + 5);
  sizeKnown = us != (UInt64)-1; unpackSize = us;
  Buf body(in.begin() + 13, in.end());
  Buf r = LzmaDecode(in.data(), 5, body, sizeKnown ? us : (UInt64)-1);
  if (!sizeKnown) unpackSize = r.size();
  return r;
}
