std::string MethodIdToName(UInt64 id) {
  switch (id) {
    case k_Copy: return "Copy"; case k_Delta: return "Delta"; case k_BCJ: return "BCJ"; case k_PPC: return "PPC";
    case k_IA64: return "IA64"; case k_ARM: return "ARM"; case k_ARMT: return "ARMT"; case k_SPARC: return "SPARC";
    case k_ARM64: return "ARM64"; case k_RISCV: return "RISCV"; case k_BCJ2: return "BCJ2"; case k_Swap2: return "Swap2"; case k_Swap4: return "Swap4";
    case k_LZMA: return "LZMA"; case k_LZMA2: return "LZMA2"; case k_PPMD: return "PPMD"; case k_BZip2: return "BZip2";
    case k_Deflate: return "Deflate"; case k_Deflate64: return "Deflate64"; case k_AES: return "7zAES"; case k_ZSTD: return "ZSTD";
  }
  char b[32]; snprintf(b, sizeof(b), "%llX", (unsigned long long)id); return b;
}
bool MethodNameToId(const std::string &name0, UInt64 &id) {
  std::string n = ToLower(name0);
  struct { const char *n; UInt64 id; } tab[] = {
    {"copy", k_Copy}, {"delta", k_Delta}, {"bcj", k_BCJ}, {"x86", k_BCJ}, {"ppc", k_PPC}, {"ia64", k_IA64}, {"arm", k_ARM}, {"armt", k_ARMT},
    {"sparc", k_SPARC}, {"arm64", k_ARM64}, {"riscv", k_RISCV}, {"bcj2", k_BCJ2}, {"swap2", k_Swap2}, {"swap4", k_Swap4},
    {"lzma", k_LZMA}, {"lzma2", k_LZMA2}, {"ppmd", k_PPMD}, {"bzip2", k_BZip2}, {"deflate", k_Deflate}, {"deflate64", k_Deflate64}, {"7zaes", k_AES}, {"aes", k_AES}, {"zstd", k_ZSTD} };
  for (auto &t : tab) if (n == t.n) { id = t.id; return true; }
  // hex number
  if (!n.empty()) {
    UInt64 v = 0; bool ok = true;
    for (char c : n) { int d; if (c >= '0' && c <= '9') d = c - '0'; else if (c >= 'a' && c <= 'f') d = c - 'a' + 10; else { ok = false; break; } v = v * 16 + d; }
    if (ok) { id = v; return true; }
  }
  return false;
}

// ---------------- LZMA props ----------------
UInt32 Lzma2DictFromProp(unsigned p) { return ((UInt32)2 | (p & 1)) << (p / 2 + 11); }
unsigned Lzma2PropFromDict(UInt32 dict) {
  unsigned i;
  for (i = 0; i < 40; i++) if (dict <= Lzma2DictFromProp(i)) break;
  return i;
}
UInt32 LzmaWritePropDict(UInt32 dictSize) {
  UInt32 v;
  if (dictSize >= ((UInt32)1 << 21)) {
    const UInt32 kDictMask = ((UInt32)1 << 20) - 1;
    v = (dictSize + kDictMask) & ~kDictMask;
    if (v < dictSize) v = dictSize;
  } else {
    unsigned i = 11 * 2;
    do { v = (UInt32)(2 + (i & 1)) << (i >> 1); i++; } while (v < dictSize);
  }
  return v;
}
std::string DictSizeToString(UInt32 value) {
  for (int i = 0; i <= 31; i++) if (((UInt32)1 << i) == value) return UInt64ToStr((UInt64)i);
  char c = 'b';
  if ((value & ((1 << 20) - 1)) == 0) { value >>= 20; c = 'm'; }
  else if ((value & ((1 << 10) - 1)) == 0) { value >>= 10; c = 'k'; }
  return UInt64ToStr(value) + c;
}

void LzmaProps::Normalize() {
  if (level < 0) level = 5; if (level > 9) level = 9;
  if (dictSize == 0) {
    dictSize = (level <= 3 ? ((UInt32)1 << (level * 2 + 16)) : (level <= 6 ? ((UInt32)1 << (level + 20)) : (level <= 7 ? ((UInt32)1 << 27) : ((UInt32)1 << 28))));
  }
  if (lc < 0) lc = 3; if (lp < 0) lp = 0; if (pb < 0) pb = 2;
  if (algo < 0) algo = (level < 5 ? 0 : 1);
  if (fb == 0) fb = (level < 7 ? 32 : 64);
  if (mf.empty()) mf = algo == 0 ? "hc4" : "bt4";
  bool bt = mf[0] == 'b';
  if (mc == 0) mc = (16 + (fb >> 1)) >> (bt ? 0 : 1);
}
UInt32 LzmaProps::GetDictSizeReduced() const {
  UInt32 d = dictSize;
  if (reduceSize != (UInt64)-1 && (UInt64)d > reduceSize) {
    UInt32 v = (UInt32)reduceSize;
    const UInt32 kReduceMin = 1 << 12;
    if (v < kReduceMin) v = kReduceMin;
    if (d > v) d = v;
  }
  return d;
}

static void FillLzmaOptions(lzma_options_lzma &opt, const LzmaProps &p, UInt32 dict) {
  memset(&opt, 0, sizeof(opt));
  opt.dict_size = dict < 4096 ? 4096 : dict;
  opt.lc = p.lc; opt.lp = p.lp; opt.pb = p.pb;
  opt.mode = p.algo == 0 ? LZMA_MODE_FAST : LZMA_MODE_NORMAL;
  opt.nice_len = p.fb;
  if (p.mf == "bt2") opt.mf = LZMA_MF_BT2; else if (p.mf == "bt3") opt.mf = LZMA_MF_BT3; else if (p.mf == "hc3") opt.mf = LZMA_MF_HC3;
  else if (p.mf[0] == 'h') opt.mf = LZMA_MF_HC4; else opt.mf = LZMA_MF_BT4;
  opt.depth = p.mc;
}

static Buf RawEncode(lzma_filter *filters, const Byte *in, size_t inSize) {
  lzma_stream strm = LZMA_STREAM_INIT;
  if (lzma_raw_encoder(&strm, filters) != LZMA_OK) throw std::runtime_error("lzma encoder init failed");
  Buf out; out.resize(inSize / 2 + 65536);
  strm.next_in = in; strm.avail_in = inSize;
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) out.resize(out.size() * 2);
    strm.next_out = out.data() + outPos; strm.avail_out = out.size() - outPos;
    lzma_ret r = lzma_code(&strm, LZMA_FINISH);
    outPos = out.size() - strm.avail_out;
    if (r == LZMA_STREAM_END) break;
    if (r != LZMA_OK) { lzma_end(&strm); throw std::runtime_error("lzma encode failed"); }
  }
  lzma_end(&strm);
  out.resize(outPos);
  return out;
}

static Buf Lzma2EncodeOneBlock(const Byte *in, size_t inSize, const LzmaProps &p, UInt32 dict) {
  lzma_options_lzma opt; FillLzmaOptions(opt, p, dict);
  lzma_filter filters[2] = { { LZMA_FILTER_LZMA2, &opt }, { LZMA_VLI_UNKNOWN, nullptr } };
  return RawEncode(filters, in, inSize);
}

Buf Lzma2Encode(const Buf &in, LzmaProps &props, Byte &propByte, UInt64 blockSize, unsigned numBlockThreads) {
  props.Normalize();
  UInt32 dict = props.GetDictSizeReduced();
  propByte = (Byte)Lzma2PropFromDict(dict);
  UInt32 dictEnc = Lzma2DictFromProp(propByte);
  if (in.empty()) { Buf r; r.push_back(0); return r; }
  if (blockSize == 0 || numBlockThreads <= 1 || in.size() <= blockSize) return Lzma2EncodeOneBlock(in.data(), in.size(), props, dictEnc);
  Buf out;
  size_t pos = 0;
  while (pos < in.size()) {
    size_t n = std::min((size_t)blockSize, in.size() - pos);
    Buf b = Lzma2EncodeOneBlock(in.data() + pos, n, props, dictEnc);
    pos += n;
    if (pos < in.size() && !b.empty() && b.back() == 0) b.pop_back();
    out.insert(out.end(), b.begin(), b.end());
  }
  return out;
}

// Extract raw LZMA1 stream from a single-chunk LZMA2 stream; returns false if not possible
static bool ExtractLzma1FromLzma2(const Buf &l2, size_t unpackSize, Buf &out) {
  size_t pos = 0;
  if (l2.empty()) return false;
  Byte ctrl = l2[0];
  if (ctrl < 0xE0) return false; // must be first chunk with dict reset + props
  if (l2.size() < 6) return false;
  size_t u = (((size_t)(ctrl & 0x1F) << 16) | ((size_t)l2[1] << 8) | l2[2]) + 1;
  size_t c = (((size_t)l2[3] << 8) | l2[4]) + 1;
  pos = 6;
  if (u != unpackSize) return false;
  if (pos + c > l2.size()) return false;
  size_t after = pos + c;
  if (after != l2.size() && !(after + 1 == l2.size() && l2[after] == 0)) return false;
  out.assign(l2.begin() + pos, l2.begin() + pos + c);
  return true;
}

Buf LzmaEncode(const Buf &in, LzmaProps &props, Byte propsOut[5]) {
  props.Normalize();
  UInt32 dict = props.GetDictSizeReduced();
  UInt32 dictW = LzmaWritePropDict(dict);
  propsOut[0] = (Byte)((props.pb * 5 + props.lp) * 9 + props.lc);
  SetUi32(propsOut + 1, dictW);
  UInt32 dictEnc = Lzma2DictFromProp(Lzma2PropFromDict(dict));
  if (dictEnc < dictW) dictEnc = dictW;
  // Try via LZMA2 single chunk (gives stream without end marker)
  if (!in.empty() && in.size() < (1 << 21) - 4096) {
    Buf l2 = Lzma2EncodeOneBlock(in.data(), in.size(), props, dictEnc);
    Buf l1;
    if (ExtractLzma1FromLzma2(l2, in.size(), l1)) return l1;
  }
  // fallback: LZMA1 with end marker
  lzma_options_lzma opt; FillLzmaOptions(opt, props, dictEnc);
  lzma_filter filters[2] = { { LZMA_FILTER_LZMA1, &opt }, { LZMA_VLI_UNKNOWN, nullptr } };
  return RawEncode(filters, in.data(), in.size());
}

static Buf RawDecode(lzma_filter *filters, const Buf &in, UInt64 unpackSize, bool allowUnknown) {
  lzma_stream strm = LZMA_STREAM_INIT;
  if (lzma_raw_decoder(&strm, filters) != LZMA_OK) throw UnsupportedMethod();
  Buf out;
  if (unpackSize != (UInt64)-1) out.resize((size_t)unpackSize); else out.resize(in.size() * 4 + 65536);
  strm.next_in = in.data(); strm.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) {
      if (unpackSize != (UInt64)-1) break;
      out.resize(out.size() * 2);
    }
    strm.next_out = out.data() + outPos; strm.avail_out = out.size() - outPos;
    lzma_ret r = lzma_code(&strm, LZMA_FINISH);
    outPos = out.size() - strm.avail_out;
    if (r == LZMA_STREAM_END) break;
    if (r == LZMA_BUF_ERROR) { if (unpackSize != (UInt64)-1 && outPos == unpackSize) break; lzma_end(&strm); throw DataError(); }
    if (r == LZMA_OK) { if (strm.avail_in == 0 && strm.avail_out != 0) { /* input exhausted */ if (unpackSize != (UInt64)-1 && outPos == unpackSize) break; lzma_end(&strm); throw DataError("Unexpected end of data"); } continue; }
    lzma_end(&strm); throw DataError();
  }
  lzma_end(&strm);
  if (unpackSize != (UInt64)-1 && outPos != unpackSize) throw DataError();
  out.resize(outPos);
  return out;
}

Buf LzmaDecode(const Byte *props, size_t propsSize, const Buf &in, UInt64 unpackSize) {
  if (propsSize < 5) throw UnsupportedMethod();
  lzma_options_lzma opt; memset(&opt, 0, sizeof(opt));
  unsigned d = props[0];
  if (d >= 9 * 5 * 5) throw UnsupportedMethod();
  opt.lc = d % 9; d /= 9; opt.lp = d % 5; opt.pb = d / 5;
  opt.dict_size = GetUi32(props + 1);
  if (opt.dict_size < 4096) opt.dict_size = 4096;
  opt.preset_dict = nullptr;
  lzma_filter filters[2] = { { LZMA_FILTER_LZMA1, &opt }, { LZMA_VLI_UNKNOWN, nullptr } };
  return RawDecode(filters, in, unpackSize, false);
}

Buf Lzma2Decode(Byte prop, const Buf &in, UInt64 unpackSize) {
  if (prop > 40) throw UnsupportedMethod();
  lzma_options_lzma opt; memset(&opt, 0, sizeof(opt));
  opt.dict_size = prop == 40 ? 0xFFFFFFFF : Lzma2DictFromProp(prop);
  lzma_filter filters[2] = { { LZMA_FILTER_LZMA2, &opt }, { LZMA_VLI_UNKNOWN, nullptr } };
  return RawDecode(filters, in, unpackSize, true);
}

// ---------------- Deflate ----------------
Buf DeflateEncode(const Buf &in, int level, int numPasses, int fb) {
  z_stream z; memset(&z, 0, sizeof(z));
  int zl = level; if (zl < 1) zl = 1; if (zl > 9) zl = 9;
  if (deflateInit2(&z, zl, Z_DEFLATED, -15, 9, Z_DEFAULT_STRATEGY) != Z_OK) throw std::runtime_error("deflate init");
  Buf out(deflateBound(&z, in.size()) + 64);
  z.next_in = const_cast<Byte*>(in.data()); z.avail_in = in.size();
  z.next_out = out.data(); z.avail_out = out.size();
  int r = deflate(&z, Z_FINISH);
  if (r != Z_STREAM_END) { deflateEnd(&z); throw std::runtime_error("deflate failed"); }
  out.resize(z.total_out);
  deflateEnd(&z);
  return out;
}

Buf DeflateDecode(const Buf &in, UInt64 unpackSize, bool deflate64) {
  if (deflate64) throw UnsupportedMethod();
  z_stream z; memset(&z, 0, sizeof(z));
  if (inflateInit2(&z, -15) != Z_OK) throw std::runtime_error("inflate init");
  Buf out;
  if (unpackSize != (UInt64)-1) out.resize((size_t)unpackSize); else out.resize(in.size() * 4 + 65536);
  z.next_in = const_cast<Byte*>(in.data()); z.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) { if (unpackSize != (UInt64)-1) break; out.resize(out.size() * 2); }
    z.next_out = out.data() + outPos; z.avail_out = out.size() - outPos;
    int r = inflate(&z, Z_NO_FLUSH);
    outPos = out.size() - z.avail_out;
    if (r == Z_STREAM_END) break;
    if (r == Z_BUF_ERROR) { if (z.avail_in == 0) { inflateEnd(&z); throw DataError("Unexpected end of data"); } continue; }
    if (r != Z_OK) { inflateEnd(&z); throw DataError(); }
    if (z.avail_in == 0 && z.avail_out != 0) { inflateEnd(&z); throw DataError("Unexpected end of data"); }
  }
  inflateEnd(&z);
  if (unpackSize != (UInt64)-1 && outPos != unpackSize) throw DataError();
  out.resize(outPos);
  return out;
}

// ---------------- BZip2 via libbz2 (dynamic) ----------------
namespace {
struct bz_stream_ {
  char *next_in; unsigned int avail_in; unsigned int total_in_lo32; unsigned int total_in_hi32;
  char *next_out; unsigned int avail_out; unsigned int total_out_lo32; unsigned int total_out_hi32;
  void *state; void *(*bzalloc)(void *, int, int); void (*bzfree)(void *, void *); void *opaque;
};
typedef int (*bzCompressInit_t)(bz_stream_ *, int, int, int);
typedef int (*bzCompress_t)(bz_stream_ *, int);
typedef int (*bzCompressEnd_t)(bz_stream_ *);
typedef int (*bzDecompressInit_t)(bz_stream_ *, int, int);
typedef int (*bzDecompress_t)(bz_stream_ *);
typedef int (*bzDecompressEnd_t)(bz_stream_ *);
struct BzLib {
  void *h = nullptr; bool tried = false;
  bzCompressInit_t cinit; bzCompress_t comp; bzCompressEnd_t cend; bzDecompressInit_t dinit; bzDecompress_t dec; bzDecompressEnd_t dend;
  bool Load() {
    if (tried) return h != nullptr;
    tried = true;
    const char *names[] = { "libbz2.so.1.0", "libbz2.so.1", "libbz2.so" };
    for (const char *n : names) { h = dlopen(n, RTLD_NOW); if (h) break; }
    if (!h) return false;
    cinit = (bzCompressInit_t)dlsym(h, "BZ2_bzCompressInit"); comp = (bzCompress_t)dlsym(h, "BZ2_bzCompress"); cend = (bzCompressEnd_t)dlsym(h, "BZ2_bzCompressEnd");
    dinit = (bzDecompressInit_t)dlsym(h, "BZ2_bzDecompressInit"); dec = (bzDecompress_t)dlsym(h, "BZ2_bzDecompress"); dend = (bzDecompressEnd_t)dlsym(h, "BZ2_bzDecompressEnd");
    if (!cinit || !comp || !cend || !dinit || !dec || !dend) { h = nullptr; return false; }
    return true;
  }
};
BzLib g_bz;
}

Buf BZip2Encode(const Buf &in, int level) {
  if (!g_bz.Load()) throw UnsupportedMethod();
  int blockSize = level >= 5 ? 9 : (level >= 3 ? 5 : 1);
  bz_stream_ s; memset(&s, 0, sizeof(s));
  if (g_bz.cinit(&s, blockSize, 0, 0) != 0) throw std::runtime_error("bzip2 init");
  Buf out(in.size() + in.size() / 50 + 1024);
  s.next_in = (char*)in.data(); s.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) out.resize(out.size() * 2);
    s.next_out = (char*)out.data() + outPos; s.avail_out = out.size() - outPos;
    int r = g_bz.comp(&s, 2 /*BZ_FINISH*/);
    outPos = out.size() - s.avail_out;
    if (r == 4 /*BZ_STREAM_END*/) break;
    if (r != 3 /*BZ_FINISH_OK*/) { g_bz.cend(&s); throw std::runtime_error("bzip2 compress"); }
  }
  g_bz.cend(&s);
  out.resize(outPos);
  return out;
}

Buf BZip2Decode(const Buf &in, UInt64 unpackSize) {
  if (!g_bz.Load()) throw UnsupportedMethod();
  bz_stream_ s; memset(&s, 0, sizeof(s));
  if (g_bz.dinit(&s, 0, 0) != 0) throw std::runtime_error("bzip2 init");
  Buf out;
  if (unpackSize != (UInt64)-1) out.resize((size_t)unpackSize); else out.resize(in.size() * 4 + 65536);
  s.next_in = (char*)in.data(); s.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) { if (unpackSize != (UInt64)-1) break; out.resize(out.size() * 2); }
    s.next_out = (char*)out.data() + outPos; s.avail_out = out.size() - outPos;
    int r = g_bz.dec(&s);
    outPos = out.size() - s.avail_out;
    if (r == 4) {
      // multi-stream support: if more input remains and starts with "BZh", continue
      if (s.avail_in > 3 && s.next_in[0] == 'B' && s.next_in[1] == 'Z' && s.next_in[2] == 'h') {
        char *ni = s.next_in; unsigned ai = s.avail_in;
        g_bz.dend(&s); memset(&s, 0, sizeof(s)); g_bz.dinit(&s, 0, 0); s.next_in = ni; s.avail_in = ai; continue;
      }
      break;
    }
    if (r != 0) { g_bz.dend(&s); throw DataError(); }
    if (s.avail_in == 0 && s.avail_out != 0) { g_bz.dend(&s); throw DataError("Unexpected end of data"); }
  }
  g_bz.dend(&s);
  if (unpackSize != (UInt64)-1 && outPos != unpackSize) throw DataError();
  out.resize(outPos);
  return out;
}

Buf CopyBuf(const Buf &in) { return in; }

// ---------------- BCJ x86 ----------------
static inline bool Test86MSByte(Byte b) { return ((b + 1) & 0xFE) == 0; }
static size_t x86_Convert(Byte *data, size_t size, UInt32 ip, UInt32 *state, int encoding) {
  size_t pos = 0;
  UInt32 mask = *state & 7;
  if (size < 5) return 0;
  size -= 4;
  ip += 5;
  for (;;) {
    Byte *p = data + pos;
    const Byte *limit = data + size;
    for (; p < limit; p++) if ((*p & 0xFE) == 0xE8) break;
    {
      size_t d = (size_t)(p - data - pos);
      pos = (size_t)(p - data);
      if (p >= limit) { *state = (d > 2 ? 0 : mask >> (unsigned)d); return pos; }
      if (d > 2) mask = 0;
      else {
        mask >>= (unsigned)d;
        if (mask != 0 && (mask > 4 || mask == 3 || Test86MSByte(p[(size_t)(mask >> 1) + 1]))) { mask = (mask >> 1) | 4; pos++; continue; }
      }
    }
    if (Test86MSByte(p[4])) {
      UInt32 v = ((UInt32)p[4] << 24) | ((UInt32)p[3] << 16) | ((UInt32)p[2] << 8) | ((UInt32)p[1]);
      UInt32 cur = ip + (UInt32)pos;
      pos += 5;
      if (encoding) v += cur; else v -= cur;
      if (mask != 0) {
        unsigned sh = (mask & 6) << 2;
        if (Test86MSByte((Byte)(v >> sh))) {
          v ^= (((UInt32)0x100 << sh) - 1);
          if (encoding) v += cur; else v -= cur;
        }
        mask = 0;
      }
      p[1] = (Byte)v; p[2] = (Byte)(v >> 8); p[3] = (Byte)(v >> 16); p[4] = (Byte)(0 - ((v >> 24) & 1));
    } else { mask = (mask >> 1) | 4; pos++; }
  }
}
Buf BcjX86Encode(const Buf &in) { Buf out = in; UInt32 state = 0; x86_Convert(out.data(), out.size(), 0, &state, 1); return out; }
Buf BcjX86Decode(const Buf &in) { Buf out = in; UInt32 state = 0; x86_Convert(out.data(), out.size(), 0, &state, 0); return out; }

Buf DeltaEncode(const Buf &in, unsigned delta) {
  Buf out(in.size());
  for (size_t i = 0; i < in.size(); i++) out[i] = (Byte)(in[i] - (i >= delta ? in[i - delta] : 0));
  return out;
}
Buf DeltaDecode(const Buf &in, unsigned delta) {
  Buf out(in.size());
  for (size_t i = 0; i < in.size(); i++) out[i] = (Byte)(in[i] + (i >= delta ? out[i - delta] : 0));
  return out;
}

static void ArmConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3; ip += 8;
  for (size_t i = 0; i < size; i += 4) {
    if (data[i + 3] == 0xEB) {
      UInt32 src = ((UInt32)data[i + 2] << 16) | ((UInt32)data[i + 1] << 8) | data[i + 0];
      src <<= 2;
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      dest >>= 2;
      data[i + 2] = (Byte)(dest >> 16); data[i + 1] = (Byte)(dest >> 8); data[i + 0] = (Byte)dest;
    }
  }
}
static void ArmtConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  if (size < 4) return;
  size -= 4; ip += 4;
  for (size_t i = 0; i <= size; i += 2) {
    if ((data[i + 1] & 0xF8) == 0xF0 && (data[i + 3] & 0xF8) == 0xF8) {
      UInt32 src = (((UInt32)data[i + 1] & 0x7) << 19) | ((UInt32)data[i + 0] << 11) | (((UInt32)data[i + 3] & 0x7) << 8) | data[i + 2];
      src <<= 1;
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      dest >>= 1;
      data[i + 1] = (Byte)(0xF0 | ((dest >> 19) & 0x7)); data[i + 0] = (Byte)(dest >> 11);
      data[i + 3] = (Byte)(0xF8 | ((dest >> 8) & 0x7)); data[i + 2] = (Byte)dest;
      i += 2;
    }
  }
}
static void PpcConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3;
  for (size_t i = 0; i < size; i += 4) {
    if ((data[i] >> 2) == 0x12 && (data[i + 3] & 3) == 1) {
      UInt32 src = (((UInt32)data[i + 0] & 3) << 24) | ((UInt32)data[i + 1] << 16) | ((UInt32)data[i + 2] << 8) | ((UInt32)data[i + 3] & ~(UInt32)3);
      UInt32 dest = encoding ? ip + (UInt32)i + src : src - (ip + (UInt32)i);
      data[i + 0] = (Byte)(0x48 | ((dest >> 24) & 0x3)); data[i + 1] = (Byte)(dest >> 16); data[i + 2] = (Byte)(dest >> 8);
      data[i + 3] &= 0x3; data[i + 3] |= (Byte)dest;
    }
  }
}
static void SparcConvert(Byte *data, size_t size, UInt32 ip, int encoding) {
  size &= ~(size_t)3;
  for (size_t i = 0; i < size; i += 4) {
    if ((data[i] == 0x40 && (data[i + 1] & 0xC0) == 0x00) || (data[i] == 0x7F && (data[i + 1] & 0xC0) == 0xC0)) {
      UInt32 src = ((UInt32)data[i + 0] << 24) | ((UInt32)data[i + 1] << 16) | ((UInt32)data[i + 2] << 8) | ((UInt32)data[i + 3]);
