}
static Buf BranchConvert(UInt64 method, const Buf &in, int encoding) {
  Buf out = in;
  switch (method) {
    case k_BCJ: { UInt32 st = 0; x86_Convert(out.data(), out.size(), 0, &st, encoding); break; }
    case k_ARM: ArmConvert(out.data(), out.size(), 0, encoding); break;
    case k_ARMT: ArmtConvert(out.data(), out.size(), 0, encoding); break;
    case k_PPC: PpcConvert(out.data(), out.size(), 0, encoding); break;
    case k_SPARC: SparcConvert(out.data(), out.size(), 0, encoding); break;
    default: throw UnsupportedMethod();
  }
  return out;
}
Buf BranchDecode(UInt64 method, const Buf &in, const Byte *props, size_t propsSize) { (void)props; (void)propsSize; return BranchConvert(method, in, 0); }
Buf BranchEncode(UInt64 method, const Buf &in) { return BranchConvert(method, in, 1); }

Buf Swap2(const Buf &in) { Buf o = in; for (size_t i = 0; i + 1 < o.size(); i += 2) std::swap(o[i], o[i+1]); return o; }
Buf Swap4(const Buf &in) { Buf o = in; for (size_t i = 0; i + 3 < o.size(); i += 4) { std::swap(o[i], o[i+3]); std::swap(o[i+1], o[i+2]); } return o; }

// ---------------- BCJ2 decoder ----------------
Buf Bcj2Decode(const Buf &buf0, const Buf &buf1, const Buf &buf2, const Buf &buf3, UInt64 unpackSize) {
  Buf out; out.reserve((size_t)unpackSize);
  UInt16 probs[2 + 256];
  for (auto &p : probs) p = 1024;
  size_t in0 = 0, in1 = 0, in2 = 0, in3 = 0;
  if (buf3.size() < 5) throw DataError();
  UInt32 code = 0, range = 0xFFFFFFFF;
  for (int i = 0; i < 5; i++) code = (code << 8) | buf3[in3++];
  Byte prevByte = 0;
  auto IsJ = [](Byte b0, Byte b1) { return (b1 & 0xFE) == 0xE8 || (b0 == 0x0F && (b1 & 0xF0) == 0x80); };
  while (out.size() < unpackSize) {
    if (in0 >= buf0.size()) throw DataError();
    Byte b = buf0[in0++];
    out.push_back(b);
    if (!IsJ(prevByte, b)) { prevByte = b; continue; }
    if (out.size() >= unpackSize) break;
    UInt16 *prob = (b == 0xE8) ? &probs[prevByte] : (b == 0xE9 ? &probs[256] : &probs[257]);
    UInt32 bound = (range >> 11) * (*prob);
    unsigned bit;
    if (code < bound) { range = bound; *prob = (UInt16)(*prob + ((2048 - *prob) >> 5)); bit = 0; }
    else { range -= bound; code -= bound; *prob = (UInt16)(*prob - (*prob >> 5)); bit = 1; }
    if (range < (1u << 24)) { range <<= 8; if (in3 >= buf3.size()) throw DataError(); code = (code << 8) | buf3[in3++]; }
    if (bit == 0) { prevByte = b; continue; }
    UInt32 src;
    if (b == 0xE8) { if (in1 + 4 > buf1.size()) throw DataError(); src = GetBe32(buf1.data() + in1); in1 += 4; }
    else { if (in2 + 4 > buf2.size()) throw DataError(); src = GetBe32(buf2.data() + in2); in2 += 4; }
    UInt32 dest = src - (UInt32)(out.size() + 4);
    out.push_back((Byte)dest); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 8)); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 16)); if (out.size() >= unpackSize) break;
    out.push_back((Byte)(dest >> 24));
    prevByte = (Byte)(dest >> 24);
  }
  if (out.size() != unpackSize) throw DataError();
  return out;
}

// ---------------- zstd (dynamic) ----------------
namespace {
typedef size_t (*ZSTD_decompress_t)(void *, size_t, const void *, size_t);
typedef unsigned long long (*ZSTD_getFrameContentSize_t)(const void *, size_t);
typedef unsigned (*ZSTD_isError_t)(size_t);
void *g_zstd = nullptr; bool g_zstdTried = false;
ZSTD_decompress_t g_zstdDec; ZSTD_getFrameContentSize_t g_zstdSize; ZSTD_isError_t g_zstdIsErr;
bool LoadZstd() {
  if (g_zstdTried) return g_zstd != nullptr;
  g_zstdTried = true;
  const char *names[] = { "libzstd.so.1", "libzstd.so" };
  for (const char *n : names) { g_zstd = dlopen(n, RTLD_NOW); if (g_zstd) break; }
  if (!g_zstd) return false;
  g_zstdDec = (ZSTD_decompress_t)dlsym(g_zstd, "ZSTD_decompress");
  g_zstdSize = (ZSTD_getFrameContentSize_t)dlsym(g_zstd, "ZSTD_getFrameContentSize");
  g_zstdIsErr = (ZSTD_isError_t)dlsym(g_zstd, "ZSTD_isError");
  if (!g_zstdDec || !g_zstdSize || !g_zstdIsErr) { g_zstd = nullptr; return false; }
  return true;
}
}
bool ZstdAvailable() { return LoadZstd(); }
Buf ZstdDecode(const Buf &in, UInt64 unpackSize) {
  if (!LoadZstd()) throw UnsupportedMethod();
  size_t cap = unpackSize != (UInt64)-1 ? (size_t)unpackSize : 0;
  if (cap == 0) {
    unsigned long long s = g_zstdSize(in.data(), in.size());
    if (s == (unsigned long long)-1 || s == (unsigned long long)-2) cap = in.size() * 8 + (1 << 20); else cap = (size_t)s;
  }
  Buf out(cap);
  for (;;) {
    size_t r = g_zstdDec(out.data(), out.size(), in.data(), in.size());
    if (g_zstdIsErr(r)) {
      if (unpackSize == (UInt64)-1 && out.size() < ((size_t)1 << 32)) { out.resize(out.size() * 2); continue; }
      throw DataError();
    }
    out.resize(r); break;
  }
  return out;
}

// ---------------- AES ----------------
namespace {
Byte g_sbox[256], g_inv[256]; bool g_aesInit = false;
inline Byte xtime(Byte x) { return (Byte)((x << 1) ^ ((x & 0x80) ? 0x1B : 0)); }
Byte gmul(Byte a, Byte b) { Byte r = 0; while (b) { if (b & 1) r ^= a; a = xtime(a); b >>= 1; } return r; }
void InitAes() {
  if (g_aesInit) return;
  Byte p = 1, q = 1;
  do {
    p = p ^ (Byte)(p << 1) ^ ((p & 0x80) ? 0x1B : 0);
    q ^= q << 1; q ^= q << 2; q ^= q << 4; if (q & 0x80) q ^= 0x09;
    Byte x = q ^ (Byte)((q << 1) | (q >> 7)) ^ (Byte)((q << 2) | (q >> 6)) ^ (Byte)((q << 3) | (q >> 5)) ^ (Byte)((q << 4) | (q >> 4));
    g_sbox[p] = x ^ 0x63;
  } while (p != 1);
  g_sbox[0] = 0x63;
  for (int i = 0; i < 256; i++) g_inv[g_sbox[i]] = (Byte)i;
  g_aesInit = true;
}
}
void AesSetKey(const Byte *key, unsigned keyBytes, UInt32 *w, bool decrypt) {
  InitAes();
  unsigned nk = keyBytes / 4, rounds = nk + 6, total = 4 * (rounds + 1);
  for (unsigned i = 0; i < nk; i++) w[i] = GetBe32(key + i * 4);
  UInt32 rcon = 1;
  for (unsigned i = nk; i < total; i++) {
    UInt32 t = w[i - 1];
    if (i % nk == 0) {
      t = (t << 8) | (t >> 24);
      t = ((UInt32)g_sbox[t >> 24] << 24) | ((UInt32)g_sbox[(t >> 16) & 0xFF] << 16) | ((UInt32)g_sbox[(t >> 8) & 0xFF] << 8) | g_sbox[t & 0xFF];
      t ^= rcon << 24; rcon = xtime((Byte)rcon);
    } else if (nk > 6 && i % nk == 4) {
      t = ((UInt32)g_sbox[t >> 24] << 24) | ((UInt32)g_sbox[(t >> 16) & 0xFF] << 16) | ((UInt32)g_sbox[(t >> 8) & 0xFF] << 8) | g_sbox[t & 0xFF];
    }
    w[i] = w[i - nk] ^ t;
  }
  (void)decrypt;
}
static void AddRoundKey(Byte *s, const UInt32 *w) { for (int c = 0; c < 4; c++) { UInt32 k = w[c]; s[c*4] ^= (Byte)(k >> 24); s[c*4+1] ^= (Byte)(k >> 16); s[c*4+2] ^= (Byte)(k >> 8); s[c*4+3] ^= (Byte)k; } }
void AesEncryptBlock(const UInt32 *w, unsigned rounds, Byte *s) {
  InitAes();
  AddRoundKey(s, w);
  for (unsigned r = 1; r <= rounds; r++) {
    for (int i = 0; i < 16; i++) s[i] = g_sbox[s[i]];
    // shift rows: state is column-major s[c*4 + r]
    Byte t[16];
    for (int c = 0; c < 4; c++) for (int rr = 0; rr < 4; rr++) t[c*4 + rr] = s[((c + rr) % 4) * 4 + rr];
    if (r != rounds) {
      for (int c = 0; c < 4; c++) {
        Byte a0 = t[c*4], a1 = t[c*4+1], a2 = t[c*4+2], a3 = t[c*4+3];
        s[c*4]   = (Byte)(xtime(a0) ^ (xtime(a1) ^ a1) ^ a2 ^ a3);
        s[c*4+1] = (Byte)(a0 ^ xtime(a1) ^ (xtime(a2) ^ a2) ^ a3);
        s[c*4+2] = (Byte)(a0 ^ a1 ^ xtime(a2) ^ (xtime(a3) ^ a3));
        s[c*4+3] = (Byte)((xtime(a0) ^ a0) ^ a1 ^ a2 ^ xtime(a3));
      }
    } else memcpy(s, t, 16);
    AddRoundKey(s, w + r * 4);
  }
}
void AesDecryptBlock(const UInt32 *w, unsigned rounds, Byte *s) {
  InitAes();
  AddRoundKey(s, w + rounds * 4);
  for (unsigned r = rounds; r >= 1; r--) {
    // inv shift rows
    Byte t[16];
    for (int c = 0; c < 4; c++) for (int rr = 0; rr < 4; rr++) t[((c + rr) % 4) * 4 + rr] = s[c*4 + rr];
    for (int i = 0; i < 16; i++) t[i] = g_inv[t[i]];
    AddRoundKey(t, w + (r - 1) * 4);
    if (r != 1) {
      for (int c = 0; c < 4; c++) {
        Byte a0 = t[c*4], a1 = t[c*4+1], a2 = t[c*4+2], a3 = t[c*4+3];
        s[c*4]   = (Byte)(gmul(a0,14) ^ gmul(a1,11) ^ gmul(a2,13) ^ gmul(a3,9));
        s[c*4+1] = (Byte)(gmul(a0,9) ^ gmul(a1,14) ^ gmul(a2,11) ^ gmul(a3,13));
        s[c*4+2] = (Byte)(gmul(a0,13) ^ gmul(a1,9) ^ gmul(a2,14) ^ gmul(a3,11));
        s[c*4+3] = (Byte)(gmul(a0,11) ^ gmul(a1,13) ^ gmul(a2,9) ^ gmul(a3,14));
      }
    } else memcpy(s, t, 16);
  }
}

// SHA256 wrapper reusing common.cpp's implementation would need exposure; implement small version here
namespace {
struct Sha256Impl {
  UInt32 h[8]; UInt64 count; Byte buf[64]; unsigned bufLen;
  static UInt32 rotr(UInt32 x, int n) { return (x >> n) | (x << (32 - n)); }
  void Init() { static const UInt32 iv[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}; memcpy(h, iv, 32); count = 0; bufLen = 0; }
  void Block(const Byte *p) {
    static const UInt32 K[64] = {
      0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
      0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
      0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
      0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2 };
    UInt32 w[64];
    for (int i = 0; i < 16; i++) w[i] = GetBe32(p + i * 4);
    for (int i = 16; i < 64; i++) { UInt32 s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >> 3); UInt32 s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >> 10); w[i] = w[i-16] + s0 + w[i-7] + s1; }
    UInt32 a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
    for (int i = 0; i < 64; i++) {
      UInt32 S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25); UInt32 ch = (e & f) ^ (~e & g); UInt32 t1 = hh + S1 + ch + K[i] + w[i];
      UInt32 S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22); UInt32 maj = (a & b) ^ (a & c) ^ (b & c); UInt32 t2 = S0 + maj;
      hh = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=hh;
  }
  void Update(const Byte *p, size_t n) {
    count += n;
    while (n > 0) {
      if (bufLen == 0 && n >= 64) { Block(p); p += 64; n -= 64; continue; }
      size_t take = std::min(n, (size_t)(64 - bufLen));
      memcpy(buf + bufLen, p, take); bufLen += take; p += take; n -= take;
      if (bufLen == 64) { Block(buf); bufLen = 0; }
    }
  }
  void Final(Byte *digest) {
    UInt64 bits = count * 8; Byte pad = 0x80; Update(&pad, 1); Byte z = 0; while (bufLen != 56) Update(&z, 1);
    Byte lenb[8]; SetBe64(lenb, bits); Update(lenb, 8);
    for (int i = 0; i < 8; i++) SetBe32(digest + i * 4, h[i]);
  }
};
}
void Sha256::Init() { ((Sha256Impl*)st)->Init(); }
void Sha256::Update(const Byte *d, size_t n) { ((Sha256Impl*)st)->Update(d, n); }
void Sha256::Final(Byte *digest) { ((Sha256Impl*)st)->Final(digest); }

static void Aes7zDeriveKey(const Byte *salt, unsigned saltSize, unsigned numCyclesPower, const std::string &password, Byte key[32]) {
  std::vector<uint16_t> w = Utf8ToUtf16(password);
  Buf pw; for (uint16_t c : w) { pw.push_back((Byte)c); pw.push_back((Byte)(c >> 8)); }
  if (numCyclesPower == 0x3F) {
    memset(key, 0, 32);
    unsigned pos = 0;
    for (unsigned i = 0; i < saltSize && pos < 32; i++) key[pos++] = salt[i];
    for (unsigned i = 0; i < pw.size() && pos < 32; i++) key[pos++] = pw[i];
    return;
  }
  Sha256 sha; sha.Init();
  Byte counter[8]; memset(counter, 0, 8);
  UInt64 numRounds = (UInt64)1 << numCyclesPower;
  Buf block; block.insert(block.end(), salt, salt + saltSize); block.insert(block.end(), pw.begin(), pw.end()); block.insert(block.end(), counter, counter + 8);
  size_t ctrPos = block.size() - 8;
  for (UInt64 r = 0; r < numRounds; r++) {
    sha.Update(block.data(), block.size());
    for (unsigned i = 0; i < 8; i++) if (++block[ctrPos + i] != 0) break;
  }
  sha.Final(key);
}

Buf Aes7zDecode(const Byte *props, size_t propsSize, const Buf &in, UInt64 unpackSize, const std::string &password) {
  if (propsSize < 1) throw UnsupportedMethod();
  Byte b0 = props[0];
  unsigned numCyclesPower = b0 & 0x3F;
  unsigned saltSize = 0, ivSize = 0;
  size_t pos = 1;
  if ((b0 & 0xC0) != 0) {
    if (propsSize < 2) throw UnsupportedMethod();
    Byte b1 = props[1]; pos = 2;
    saltSize = ((b0 >> 7) & 1) ? ((b1 >> 4) + 1) : 0;
    ivSize = ((b0 >> 6) & 1) ? ((b1 & 0x0F) + 1) : 0;
  }
  if (propsSize < pos + saltSize + ivSize) throw UnsupportedMethod();
  const Byte *salt = props + pos; const Byte *ivp = props + pos + saltSize;
  Byte iv[16]; memset(iv, 0, 16); memcpy(iv, ivp, ivSize > 16 ? 16 : ivSize);
  Byte key[32]; Aes7zDeriveKey(salt, saltSize, numCyclesPower, password, key);
  UInt32 w[60]; AesSetKey(key, 32, w, true);
  Buf out(in.size() & ~(size_t)15);
  Byte prev[16]; memcpy(prev, iv, 16);
  for (size_t i = 0; i + 16 <= in.size(); i += 16) {
    Byte blk[16]; memcpy(blk, in.data() + i, 16);
    Byte c[16]; memcpy(c, blk, 16);
    AesDecryptBlock(w, 14, blk);
    for (int k = 0; k < 16; k++) out[i + k] = blk[k] ^ prev[k];
    memcpy(prev, c, 16);
  }
  if (unpackSize != (UInt64)-1) { if (unpackSize > out.size()) throw DataError(); out.resize((size_t)unpackSize); }
  return out;
}

static void FillRandom(Byte *p, size_t n) {
  FILE *f = fopen("/dev/urandom", "rb");
  if (f) { size_t r = fread(p, 1, n, f); (void)r; fclose(f); }
  else for (size_t i = 0; i < n; i++) p[i] = (Byte)rand();
}

Buf Aes7zEncode(const Buf &in, const std::string &password, Buf &propsOut) {
  Byte iv[16]; memset(iv, 0, 16); FillRandom(iv, 8);
  unsigned numCyclesPower = 19;
  propsOut.clear();
  propsOut.push_back((Byte)(numCyclesPower | 0x40)); // has IV
  propsOut.push_back((Byte)(8 - 1));                 // IV size 8
  propsOut.insert(propsOut.end(), iv, iv + 8);
  Byte key[32]; Aes7zDeriveKey(nullptr, 0, numCyclesPower, password, key);
  UInt32 w[60]; AesSetKey(key, 32, w, false);
  size_t padded = (in.size() + 15) & ~(size_t)15;
  Buf out(padded);
  Byte prev[16]; memcpy(prev, iv, 16);
  for (size_t i = 0; i < padded; i += 16) {
    Byte blk[16];
    for (int k = 0; k < 16; k++) blk[k] = (Byte)(((i + k < in.size()) ? in[i + k] : 0) ^ prev[k]);
    AesEncryptBlock(w, 14, blk);
    memcpy(out.data() + i, blk, 16); memcpy(prev, blk, 16);
  }
  return out;
}

// ---------------- xz container ----------------
static void WriteVli(Buf &b, UInt64 v) { while (v >= 0x80) { b.push_back((Byte)(v | 0x80)); v >>= 7; } b.push_back((Byte)v); }
static bool ReadVli(const Byte *p, size_t size, size_t &pos, UInt64 &v) {
  v = 0; unsigned shift = 0;
  while (pos < size) { Byte b = p[pos++]; v |= (UInt64)(b & 0x7F) << shift; if (!(b & 0x80)) return true; shift += 7; if (shift > 63) return false; }
  return false;
}
static unsigned XzCheckSize(unsigned t) { if (t == 0) return 0; if (t <= 3) return 4; if (t <= 6) return 8; if (t <= 9) return 16; if (t <= 12) return 32; return 64; }

Buf XzEncode(const Buf &in, LzmaProps &props, unsigned checkType, UInt64 blockSize, unsigned numThreads) {
  props.Normalize();
  UInt32 dict = props.GetDictSizeReduced();
  Byte propByte = (Byte)Lzma2PropFromDict(dict);
  UInt32 dictEnc = Lzma2DictFromProp(propByte);
  Buf out;
  // stream header
  const Byte magic[6] = { 0xFD, '7', 'z', 'X', 'Z', 0x00 };
  out.insert(out.end(), magic, magic + 6);
  Byte flags[2] = { 0, (Byte)checkType };
  out.insert(out.end(), flags, flags + 2);
  { Byte c[4]; SetUi32(c, Crc32Calc(flags, 2)); out.insert(out.end(), c, c + 4); }
  std::vector<std::pair<UInt64,UInt64>> records; // unpadded size, uncompressed size
  size_t pos = 0;
  if (blockSize == 0 || numThreads <= 1) blockSize = (UInt64)-1;
  do {
    size_t n = (size_t)std::min<UInt64>(blockSize, in.size() - pos);
    // block header
    Buf hdr; hdr.push_back(0); hdr.push_back(0x00); hdr.push_back(0x21); hdr.push_back(0x01); hdr.push_back(propByte);
    while ((hdr.size() + 4) % 4 != 0) hdr.push_back(0);
    hdr[0] = (Byte)((hdr.size() + 4) / 4 - 1);
    { Byte c[4]; SetUi32(c, Crc32Calc(hdr.data(), hdr.size())); hdr.insert(hdr.end(), c, c + 4); }
    Buf data = Lzma2EncodeOneBlock(in.data() + pos, n, props, dictEnc);
    UInt64 unpadded = hdr.size() + data.size() + XzCheckSize(checkType);
    out.insert(out.end(), hdr.begin(), hdr.end());
    out.insert(out.end(), data.begin(), data.end());
    while (out.size() % 4 != 0) out.push_back(0);
    if (checkType == 1) { Byte c[4]; SetUi32(c, Crc32Calc(in.data() + pos, n)); out.insert(out.end(), c, c + 4); }
    else if (checkType == 4) { Byte c[8]; SetUi64(c, Crc64Update(0, in.data() + pos, n)); out.insert(out.end(), c, c + 8); }
    else if (checkType == 10) { Byte d[32]; Sha256Calc(in.data() + pos, n, d); out.insert(out.end(), d, d + 32); }
    records.push_back({unpadded, n});
    pos += n;
  } while (pos < in.size());
  // index
  Buf idx; idx.push_back(0); WriteVli(idx, records.size());
  for (auto &r : records) { WriteVli(idx, r.first); WriteVli(idx, r.second); }
  while (idx.size() % 4 != 0) idx.push_back(0);
  { Byte c[4]; SetUi32(c, Crc32Calc(idx.data(), idx.size())); idx.insert(idx.end(), c, c + 4); }
  out.insert(out.end(), idx.begin(), idx.end());
  // footer
  Byte footer[12];
  SetUi32(footer + 4, (UInt32)(idx.size() / 4 - 1));
  footer[8] = 0; footer[9] = (Byte)checkType;
  SetUi32(footer, Crc32Calc(footer + 4, 6));
  footer[10] = 'Y'; footer[11] = 'Z';
  out.insert(out.end(), footer, footer + 12);
  return out;
}

bool XzParseInfo(const Buf &in, XzInfo &info) {
  info = XzInfo(); info.ok = false;
  if (in.size() < 32) return false;
  if (memcmp(in.data(), "\xFD" "7zXZ\0", 6) != 0) return false;
  info.checkType = in[7] & 0x0F;
  info.numStreams = 0; info.numBlocks = 0; info.unpackSize = 0; info.packSize = in.size();
  // parse streams backward
  size_t end = in.size();
  std::string method;
  while (end >= 32) {
    // skip stream padding (zeros, multiple of 4)
    while (end >= 4 && GetUi32(in.data() + end - 4) == 0 && !(in[end-2] == 'Y' && in[end-1] == 'Z')) end -= 4;
    if (end < 12) break;
    const Byte *footer = in.data() + end - 12;
    if (footer[10] != 'Y' || footer[11] != 'Z') return info.numStreams > 0;
    UInt64 backSize = ((UInt64)GetUi32(footer + 4) + 1) * 4;
    if (backSize + 12 > end) return false;
    const Byte *idx = footer - backSize;
    size_t p = 0; UInt64 nrec;
    if (idx[0] != 0) return false; p = 1;
    if (!ReadVli(idx, (size_t)backSize, p, nrec)) return false;
    UInt64 blocksSize = 0;
    for (UInt64 i = 0; i < nrec; i++) {
      UInt64 unpadded, usize;
      if (!ReadVli(idx, (size_t)backSize, p, unpadded) || !ReadVli(idx, (size_t)backSize, p, usize)) return false;
      blocksSize += (unpadded + 3) & ~(UInt64)3;
      info.unpackSize += usize;
    }
    info.numBlocks += nrec;
    info.numStreams++;
    UInt64 streamStart = end - 12 - backSize - blocksSize - 12;
    if ((Int64)streamStart < 0) return false;
    // parse first block header for method
    if (nrec > 0 && method.empty()) {
      const Byte *bh = in.data() + streamStart + 12;
      unsigned hs = ((unsigned)bh[0] + 1) * 4;
      unsigned nf = (bh[1] & 3) + 1;
      size_t q = 2;
      if (bh[1] & 0x40) { UInt64 v; ReadVli(bh, hs, q, v); }
      if (bh[1] & 0x80) { UInt64 v; ReadVli(bh, hs, q, v); }
      for (unsigned f = 0; f < nf; f++) {
        UInt64 fid, psz; if (!ReadVli(bh, hs, q, fid) || !ReadVli(bh, hs, q, psz)) break;
        std::string m;
        if (fid == 0x21) { m = "LZMA2"; if (psz == 1) { Byte d = bh[q]; m += ":"; if ((d & 1) == 0) m += UInt64ToStr(d / 2 + 12); else m += DictSizeToString((UInt32)3 << (d / 2 + 11)); } }
        else if (fid == 4) m = "x86"; else if (fid == 5) m = "PowerPC"; else if (fid == 6) m = "IA64"; else if (fid == 7) m = "ARM"; else if (fid == 8) m = "ARMT"; else if (fid == 9) m = "SPARC"; else if (fid == 0xA) m = "ARM64"; else if (fid == 0xB) m = "RISCV"; else if (fid == 3) m = "Delta";
        else { char b[32]; snprintf(b, sizeof(b), "%llX", (unsigned long long)fid); m = b; }
        q += (size_t)psz;
        if (!method.empty()) method += " ";
        method += m;
      }
    }
    end = (size_t)streamStart;
  }
  static const char *checkNames[16] = { "None", "CRC32", "", "", "CRC64", "", "", "", "", "", "SHA256", "", "", "", "", "" };
  std::string cn = checkNames[info.checkType & 15];
  if (cn.empty()) { char b[32]; snprintf(b, sizeof(b), "Check-%u", info.checkType); cn = b; }
  info.methodString = method + (method.empty() ? "" : " ") + cn;
  info.ok = info.numStreams > 0;
  return info.ok;
}

bool XzDecode(const Buf &in, Buf &out, XzInfo &info) {
  XzParseInfo(in, info);
  lzma_stream strm = LZMA_STREAM_INIT;
  if (lzma_stream_decoder(&strm, UINT64_MAX, LZMA_CONCATENATED) != LZMA_OK) throw std::runtime_error("xz init");
  out.clear();
  if (info.ok) out.resize((size_t)info.unpackSize); else out.resize(in.size() * 4 + 65536);
  strm.next_in = in.data(); strm.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) out.resize(out.size() * 2 + 65536);
    strm.next_out = out.data() + outPos; strm.avail_out = out.size() - outPos;
    lzma_ret r = lzma_code(&strm, LZMA_FINISH);
    outPos = out.size() - strm.avail_out;
    if (r == LZMA_STREAM_END) break;
    if (r != LZMA_OK) { lzma_end(&strm); out.resize(outPos); if (r == LZMA_BUF_ERROR) throw DataError("Unexpected end of data"); throw DataError(); }
  }
  lzma_end(&strm);
  out.resize(outPos);
  return true;
}

Buf LzmaAloneDecode(const Buf &in, UInt64 &unpackSize, bool &sizeKnown) {
  if (in.size() < 13) throw DataError();
  UInt64 us = GetUi64(in.data() + 5);
  sizeKnown = us != (UInt64)-1; unpackSize = us;
  Buf body(in.begin() + 13, in.end());
  Buf r = LzmaDecode(in.data(), 5, body, sizeKnown ? us : (UInt64)-1);
  if (!sizeKnown) unpackSize = r.size();
  return r;
}
