static const Byte kSignature[6] = { '7', 'z', 0xBC, 0xAF, 0x27, 0x1C };

struct HeadersError : std::runtime_error { HeadersError() : std::runtime_error("Headers Error") {} };
struct UnexpectedEnd : std::runtime_error { UnexpectedEnd() : std::runtime_error("Unexpected end of archive") {} };

UInt64 SzFolder::GetUnpackSize() const {
  int m = MainOutStream();
  if (m < 0) return 0;
  return unpackSizes[m];
}
int SzFolder::FindBindPairForInStream(UInt32 inIndex) const { for (size_t i = 0; i < bindPairs.size(); i++) if (bindPairs[i].first == inIndex) return (int)i; return -1; }
int SzFolder::FindBindPairForOutStream(UInt32 outIndex) const { for (size_t i = 0; i < bindPairs.size(); i++) if (bindPairs[i].second == outIndex) return (int)i; return -1; }
int SzFolder::MainOutStream() const {
  UInt32 n = GetNumOutStreamsTotal();
  for (UInt32 i = 0; i < n; i++) if (FindBindPairForOutStream(i) < 0) return (int)i;
  return -1;
}

// ---------------- Reader ----------------
struct InByte {
  const Byte *p; size_t size, pos = 0;
  InByte(const Byte *d, size_t s) : p(d), size(s) {}
  Byte ReadByte() { if (pos >= size) throw UnexpectedEnd(); return p[pos++]; }
  void ReadBytes(Byte *d, size_t n) { if (pos + n > size) throw UnexpectedEnd(); memcpy(d, p + pos, n); pos += n; }
  void Skip(size_t n) { if (pos + n > size) throw UnexpectedEnd(); pos += n; }
  UInt64 ReadNumber() {
    Byte first = ReadByte();
    Byte mask = 0x80; UInt64 value = 0;
    for (int i = 0; i < 8; i++) {
      if ((first & mask) == 0) { UInt64 high = first & (mask - 1); value |= (high << (8 * i)); return value; }
      value |= ((UInt64)ReadByte() << (8 * i));
      mask >>= 1;
    }
    return value;
  }
  UInt32 ReadNum() { UInt64 v = ReadNumber(); if (v > 0x7FFFFFFF) throw HeadersError(); return (UInt32)v; }
  UInt32 ReadUInt32() { Byte b[4]; ReadBytes(b, 4); return GetUi32(b); }
  UInt64 ReadUInt64() { Byte b[8]; ReadBytes(b, 8); return GetUi64(b); }
  void ReadBoolVector(unsigned n, std::vector<bool> &v) {
    v.assign(n, false); Byte b = 0, mask = 0;
    for (unsigned i = 0; i < n; i++) { if (mask == 0) { b = ReadByte(); mask = 0x80; } v[i] = (b & mask) != 0; mask >>= 1; }
  }
  void ReadBoolVector2(unsigned n, std::vector<bool> &v) {
    Byte allDefined = ReadByte();
    if (allDefined == 0) { ReadBoolVector(n, v); return; }
    v.assign(n, true);
  }
  void SkipData() { UInt64 size = ReadNumber(); Skip((size_t)size); }
  void WaitId(UInt64 id) { for (;;) { UInt64 t = ReadNumber(); if (t == id) return; if (t == NID::kEnd) throw HeadersError(); SkipData(); } }
};

static void ReadHashDigests(InByte &in, unsigned n, std::vector<bool> &defs, std::vector<UInt32> &vals) {
  in.ReadBoolVector2(n, defs);
  vals.assign(n, 0);
  for (unsigned i = 0; i < n; i++) if (defs[i]) vals[i] = in.ReadUInt32();
}

static void ReadPackInfo(InByte &in, SzDb &db) {
  db.packPos = in.ReadNumber();
  UInt32 numPackStreams = in.ReadNum();
  in.WaitId(NID::kSize);
  db.packSizes.resize(numPackStreams);
  for (UInt32 i = 0; i < numPackStreams; i++) db.packSizes[i] = in.ReadNumber();
  db.packCrcDefined.assign(numPackStreams, false); db.packCrcs.assign(numPackStreams, 0);
  for (;;) {
    UInt64 type = in.ReadNumber();
    if (type == NID::kEnd) return;
    if (type == NID::kCRC) { ReadHashDigests(in, numPackStreams, db.packCrcDefined, db.packCrcs); continue; }
    in.SkipData();
  }
}

static void ReadFolder(InByte &in, SzFolder &f) {
  UInt32 numCoders = in.ReadNum();
  if (numCoders == 0 || numCoders > 64) throw HeadersError();
  f.coders.resize(numCoders);
  UInt32 numInTotal = 0, numOutTotal = 0;
  for (UInt32 i = 0; i < numCoders; i++) {
    SzCoder &c = f.coders[i];
    Byte mainByte = in.ReadByte();
    if (mainByte & 0xC0) throw HeadersError();
    unsigned idSize = mainByte & 0xF;
    if (idSize > 8) throw HeadersError();
    Byte idb[8]; in.ReadBytes(idb, idSize);
    UInt64 id = 0; for (unsigned k = 0; k < idSize; k++) id = (id << 8) | idb[k];
    c.id = id;
    if (mainByte & 0x10) { c.numInStreams = in.ReadNum(); c.numOutStreams = in.ReadNum(); if (c.numOutStreams != 1 && c.numOutStreams > 64) throw HeadersError(); }
    else { c.numInStreams = 1; c.numOutStreams = 1; }
    if (mainByte & 0x20) { UInt32 ps = in.ReadNum(); c.props.resize(ps); in.ReadBytes(c.props.data(), ps); }
    numInTotal += c.numInStreams; numOutTotal += c.numOutStreams;
  }
  if (numOutTotal == 0) throw HeadersError();
  UInt32 numBindPairs = numOutTotal - 1;
  f.bindPairs.resize(numBindPairs);
  for (UInt32 i = 0; i < numBindPairs; i++) { f.bindPairs[i].first = in.ReadNum(); f.bindPairs[i].second = in.ReadNum(); if (f.bindPairs[i].first >= numInTotal || f.bindPairs[i].second >= numOutTotal) throw HeadersError(); }
  if (numInTotal < numBindPairs) throw HeadersError();
  UInt32 numPackStreams = numInTotal - numBindPairs;
  if (numPackStreams == 1) {
    for (UInt32 i = 0; i < numInTotal; i++) if (f.FindBindPairForInStream(i) < 0) { f.packStreams.push_back(i); break; }
    if (f.packStreams.size() != 1) throw HeadersError();
  } else {
    for (UInt32 i = 0; i < numPackStreams; i++) f.packStreams.push_back(in.ReadNum());
  }
}

static void ReadUnpackInfo(InByte &in, SzDb &db) {
  in.WaitId(NID::kFolder);
  UInt32 numFolders = in.ReadNum();
  if (in.ReadByte() != 0) throw HeadersError(); // external not supported
  db.folders.resize(numFolders);
  for (UInt32 i = 0; i < numFolders; i++) ReadFolder(in, db.folders[i]);
  in.WaitId(NID::kCodersUnpackSize);
  for (UInt32 i = 0; i < numFolders; i++) {
    SzFolder &f = db.folders[i];
    UInt32 n = f.GetNumOutStreamsTotal();
    f.unpackSizes.resize(n);
    for (UInt32 j = 0; j < n; j++) f.unpackSizes[j] = in.ReadNumber();
  }
  for (;;) {
    UInt64 type = in.ReadNumber();
    if (type == NID::kEnd) return;
    if (type == NID::kCRC) {
      std::vector<bool> defs; std::vector<UInt32> vals;
      ReadHashDigests(in, numFolders, defs, vals);
      for (UInt32 i = 0; i < numFolders; i++) { db.folders[i].crcDefined = defs[i]; db.folders[i].crc = vals[i]; }
      continue;
    }
    in.SkipData();
  }
}

static void ReadSubStreamsInfo(InByte &in, SzDb &db, std::vector<UInt64> &unpackSizes, std::vector<bool> &digestsDefined, std::vector<UInt32> &digests) {
  for (auto &f : db.folders) f.numUnpackStreams = 1;
  UInt64 type;
  for (;;) {
    type = in.ReadNumber();
    if (type == NID::kNumUnpackStream) { for (auto &f : db.folders) f.numUnpackStreams = in.ReadNum(); continue; }
    if (type == NID::kCRC || type == NID::kSize || type == NID::kEnd) break;
    in.SkipData();
  }
  if (type == NID::kSize) {
    for (auto &f : db.folders) {
      UInt32 n = f.numUnpackStreams;
      if (n == 0) continue;
      UInt64 sum = 0;
      for (UInt32 j = 1; j < n; j++) { UInt64 s = in.ReadNumber(); unpackSizes.push_back(s); sum += s; }
      UInt64 folderSize = f.GetUnpackSize();
      if (folderSize < sum) throw HeadersError();
      unpackSizes.push_back(folderSize - sum);
    }
    type = in.ReadNumber();
  } else {
    for (auto &f : db.folders) {
      UInt32 n = f.numUnpackStreams;
      if (n > 1) throw HeadersError();
      if (n == 1) unpackSizes.push_back(f.GetUnpackSize());
    }
  }
  unsigned numDigests = 0;
  for (auto &f : db.folders) { UInt32 n = f.numUnpackStreams; if (n != 1 || !f.crcDefined) numDigests += n; }
  for (;;) {
    if (type == NID::kEnd) break;
    if (type == NID::kCRC) {
      std::vector<bool> defs; std::vector<UInt32> vals;
      ReadHashDigests(in, numDigests, defs, vals);
      unsigned di = 0;
      for (auto &f : db.folders) {
        UInt32 n = f.numUnpackStreams;
        if (n == 1 && f.crcDefined) { digestsDefined.push_back(true); digests.push_back(f.crc); }
        else for (UInt32 j = 0; j < n; j++, di++) { digestsDefined.push_back(defs[di]); digests.push_back(vals[di]); }
      }
    } else in.SkipData();
    type = in.ReadNumber();
  }
  if (digestsDefined.empty()) {
    for (auto &f : db.folders) {
      UInt32 n = f.numUnpackStreams;
      if (n == 1 && f.crcDefined) { digestsDefined.push_back(true); digests.push_back(f.crc); }
      else for (UInt32 j = 0; j < n; j++) { digestsDefined.push_back(false); digests.push_back(0); }
    }
  }
}

static void ReadStreamsInfo(InByte &in, SzDb &db, std::vector<UInt64> &unpackSizes, std::vector<bool> &digestsDefined, std::vector<UInt32> &digests) {
  UInt64 type = in.ReadNumber();
  if (type == NID::kPackInfo) { ReadPackInfo(in, db); type = in.ReadNumber(); }
  if (type == NID::kUnpackInfo) { ReadUnpackInfo(in, db); type = in.ReadNumber(); }
  bool haveSub = false;
  if (type == NID::kSubStreamsInfo) { ReadSubStreamsInfo(in, db, unpackSizes, digestsDefined, digests); haveSub = true; type = in.ReadNumber(); }
  if (!haveSub) {
    for (auto &f : db.folders) { f.numUnpackStreams = 1; unpackSizes.push_back(f.GetUnpackSize()); digestsDefined.push_back(f.crcDefined); digests.push_back(f.crc); }
  }
  if (type != NID::kEnd) throw HeadersError();
}

static Buf DecodeFolderData(const SzDb &db, unsigned folderIndex, const Buf &data, const std::string &password, ExtractResult &res, bool &needPassword);

static void ReadHeader(InByte &in, SzDb &db) {
  UInt64 type = in.ReadNumber();
  if (type == NID::kArchiveProperties) {
    for (;;) { UInt64 t = in.ReadNumber(); if (t == NID::kEnd) break; in.SkipData(); }
    type = in.ReadNumber();
  }
  if (type == NID::kAdditionalStreamsInfo) {
    SzDb tmp; std::vector<UInt64> us; std::vector<bool> dd; std::vector<UInt32> dg;
    ReadStreamsInfo(in, tmp, us, dd, dg);
    type = in.ReadNumber();
  }
  std::vector<UInt64> unpackSizes; std::vector<bool> digestsDefined; std::vector<UInt32> digests;
  if (type == NID::kMainStreamsInfo) {
    ReadStreamsInfo(in, db, unpackSizes, digestsDefined, digests);
    type = in.ReadNumber();
  }
  if (type == NID::kEnd) return;
  if (type != NID::kFilesInfo) throw HeadersError();
  UInt32 numFiles = in.ReadNum();
  db.files.resize(numFiles);
  std::vector<bool> emptyStreamVector(numFiles, false), emptyFileVector, antiVector;
  UInt32 numEmptyStreams = 0;
  for (;;) {
    UInt64 t = in.ReadNumber();
    if (t == NID::kEnd) break;
    UInt64 size = in.ReadNumber();
    size_t ppos = in.pos;
    if (size > in.size - in.pos) throw UnexpectedEnd();
    bool addPropIdToList = true; (void)addPropIdToList;
    switch (t) {
      case NID::kName: {
        if (in.ReadByte() != 0) throw HeadersError();
        size_t namesSize = (size_t)size - 1;
        const Byte *np = in.p + in.pos;
        size_t p = 0;
        for (UInt32 i = 0; i < numFiles; i++) {
          size_t start = p;
          while (true) { if (p + 2 > namesSize) throw HeadersError(); if (np[p] == 0 && np[p+1] == 0) break; p += 2; }
          db.files[i].name = Utf16LEBytesToUtf8(np + start, (p - start) / 2);
          p += 2;
        }
        if (p != namesSize) throw HeadersError();
        in.pos += namesSize;
        break;
      }
      case NID::kWinAttrib: {
        std::vector<bool> defs; in.ReadBoolVector2(numFiles, defs);
        if (in.ReadByte() != 0) throw HeadersError();
        for (UInt32 i = 0; i < numFiles; i++) if (defs[i]) { db.files[i].attribDefined = true; db.files[i].attrib = in.ReadUInt32(); }
        break;
      }
      case NID::kEmptyStream: {
        in.ReadBoolVector(numFiles, emptyStreamVector);
        numEmptyStreams = 0; for (bool b : emptyStreamVector) if (b) numEmptyStreams++;
        emptyFileVector.assign(numEmptyStreams, false); antiVector.assign(numEmptyStreams, false);
        break;
      }
      case NID::kEmptyFile: in.ReadBoolVector(numEmptyStreams, emptyFileVector); break;
      case NID::kAnti: in.ReadBoolVector(numEmptyStreams, antiVector); break;
      case NID::kStartPos: {
        std::vector<bool> defs; in.ReadBoolVector2(numFiles, defs);
        if (in.ReadByte() != 0) throw HeadersError();
        for (UInt32 i = 0; i < numFiles; i++) if (defs[i]) { db.files[i].startPosDefined = true; db.files[i].startPos = in.ReadUInt64(); }
        break;
      }
      case NID::kCTime: case NID::kATime: case NID::kMTime: {
        std::vector<bool> defs; in.ReadBoolVector2(numFiles, defs);
        if (in.ReadByte() != 0) throw HeadersError();
        for (UInt32 i = 0; i < numFiles; i++) if (defs[i]) {
          UInt64 v = in.ReadUInt64();
          SzFile &f = db.files[i];
          if (t == NID::kCTime) { f.ctimeDefined = true; f.ctime = v; } else if (t == NID::kATime) { f.atimeDefined = true; f.atime = v; } else { f.mtimeDefined = true; f.mtime = v; }
        }
        break;
      }
      case NID::kDummy: default:
        in.pos = ppos + (size_t)size; break;
    }
    if (in.pos != ppos + (size_t)size) {
      // tolerate? 7-zip is strict for known props
      in.pos = ppos + (size_t)size;
    }
  }
  // assign streams
  UInt32 emptyIndex = 0, sizeIndex = 0; int folderIndex = 0; UInt32 indexInFolder = 0;
  db.folderStartFileIndex.assign(db.folders.size(), 0);
  for (UInt32 i = 0; i < numFiles; i++) {
    SzFile &f = db.files[i];
    f.hasStream = !emptyStreamVector[i];
    if (f.hasStream) {
      f.isDir = false; f.isAnti = false;
      if (sizeIndex >= unpackSizes.size()) throw HeadersError();
      f.size = unpackSizes[sizeIndex]; f.crcDefined = digestsDefined[sizeIndex]; f.crc = digests[sizeIndex]; sizeIndex++;
      // find folder
      while (folderIndex < (int)db.folders.size() && indexInFolder >= db.folders[folderIndex].numUnpackStreams) { folderIndex++; indexInFolder = 0; }
      if (folderIndex >= (int)db.folders.size()) throw HeadersError();
      if (indexInFolder == 0) db.folderStartFileIndex[folderIndex] = i;
      f.folderIndex = folderIndex; f.indexInFolder = indexInFolder; indexInFolder++;
    } else {
      f.isDir = !emptyFileVector[emptyIndex]; f.isAnti = antiVector[emptyIndex]; emptyIndex++;
      f.size = 0; f.crcDefined = false; f.folderIndex = -1;
    }
  }
}

static Buf ReadPackStreamData(const SzDb &db, const Buf &data, UInt32 packIndex) {
  if (packIndex >= db.packSizes.size()) throw HeadersError();
  UInt64 start = db.packStreamStart[packIndex], size = db.packSizes[packIndex];
  if (start + size > data.size()) throw UnexpectedEnd();
  return Buf(data.begin() + (size_t)start, data.begin() + (size_t)(start + size));
}

struct FolderDecoder {
  const SzDb &db; const SzFolder &f; const Buf &data; const std::string &password; ExtractResult res = kOK; bool needPassword = false;
  FolderDecoder(const SzDb &d, const SzFolder &ff, const Buf &dt, const std::string &pw) : db(d), f(ff), data(dt), password(pw) {}
  unsigned CoderOfOut(UInt32 outIndex, UInt32 &outSub) const { UInt32 n = 0; for (unsigned i = 0; i < f.coders.size(); i++) { if (outIndex < n + f.coders[i].numOutStreams) { outSub = outIndex - n; return i; } n += f.coders[i].numOutStreams; } throw HeadersError(); }
  UInt32 FirstInOfCoder(unsigned ci) const { UInt32 n = 0; for (unsigned i = 0; i < ci; i++) n += f.coders[i].numInStreams; return n; }
  Buf GetInStream(UInt32 inIndex) {
    int bp = f.FindBindPairForInStream(inIndex);
    if (bp >= 0) return DecodeOut(f.bindPairs[bp].second);
    for (size_t i = 0; i < f.packStreams.size(); i++) if (f.packStreams[i] == inIndex) return ReadPackStreamData(db, data, f.firstPackStreamIndex + (UInt32)i);
    throw HeadersError();
  }
  Buf DecodeOut(UInt32 outIndex) {
    UInt32 sub; unsigned ci = CoderOfOut(outIndex, sub);
    const SzCoder &c = f.coders[ci];
    UInt64 unpackSize = f.unpackSizes[outIndex];
    UInt32 firstIn = FirstInOfCoder(ci);
    std::vector<Buf> ins;
    for (UInt32 k = 0; k < c.numInStreams; k++) ins.push_back(GetInStream(firstIn + k));
    const Buf &in = ins[0];
    switch (c.id) {
      case k_Copy: if (in.size() < unpackSize) throw DataError("Unexpected end of data"); return Buf(in.begin(), in.begin() + (size_t)unpackSize);
      case k_LZMA: return LzmaDecode(c.props.data(), c.props.size(), in, unpackSize);
      case k_LZMA2: if (c.props.size() < 1) throw UnsupportedMethod(); return Lzma2Decode(c.props[0], in, unpackSize);
      case k_Deflate: return DeflateDecode(in, unpackSize, false);
      case k_Deflate64: return DeflateDecode(in, unpackSize, true);
      case k_BZip2: return BZip2Decode(in, unpackSize);
      case k_BCJ: case k_ARM: case k_ARMT: case k_PPC: case k_SPARC: return BranchDecode(c.id, in, c.props.data(), c.props.size());
      case k_Delta: { unsigned d = c.props.empty() ? 1 : c.props[0] + 1; return DeltaDecode(in, d); }
      case k_Swap2: return ::Swap2(in);
      case k_Swap4: return ::Swap4(in);
      case k_BCJ2: if (ins.size() != 4) throw HeadersError(); return Bcj2Decode(ins[0], ins[1], ins[2], ins[3], unpackSize);
      case k_AES: if (password.empty()) { needPassword = true; throw DataError("password"); } return Aes7zDecode(c.props.data(), c.props.size(), in, unpackSize, password);
      case k_ZSTD: return ZstdDecode(in, unpackSize);
      default: throw UnsupportedMethod();
    }
  }
};

static Buf DecodeFolderData(const SzDb &db, unsigned folderIndex, const Buf &data, const std::string &password, ExtractResult &res, bool &needPassword) {
  const SzFolder &f = db.folders[folderIndex];
  FolderDecoder fd(db, f, data, password);
  int m = f.MainOutStream();
  if (m < 0) throw HeadersError();
  Buf out = fd.DecodeOut((UInt32)m);
  res = kOK; needPassword = fd.needPassword;
  if (f.crcDefined && Crc32Calc(out.data(), out.size()) != f.crc) res = kCRCError;
  return out;
}

static void ComputePackStarts(SzDb &db) {
  db.packStreamStart.resize(db.packSizes.size());
  UInt64 pos = 32 + db.packPos;
  for (size_t i = 0; i < db.packSizes.size(); i++) { db.packStreamStart[i] = pos; pos += db.packSizes[i]; }
  UInt32 pi = 0;
  for (auto &f : db.folders) { f.firstPackStreamIndex = pi; pi += (UInt32)f.packStreams.size(); }
}

bool Sz7zArchive::Open(const Buf &d, const std::string &p, const std::string &pw, std::string &err, bool &needPassword) {
  data = d; path = p; password = pw; needPassword = false;
  try {
    if (data.size() < 32 || memcmp(data.data(), kSignature, 6) != 0) { err = "Is not archive"; return false; }
    if (data[6] != 0) { err = "Unsupported feature"; return false; }
    UInt32 startCrc = GetUi32(data.data() + 8);
    UInt64 nextHeaderOffset = GetUi64(data.data() + 12), nextHeaderSize = GetUi64(data.data() + 20);
    UInt32 nextHeaderCrc = GetUi32(data.data() + 28);
    if (Crc32Calc(data.data() + 12, 20) != startCrc) { err = "Headers Error"; return false; }
    if (nextHeaderSize == 0) { db.physSize = 32; db.headersSize = 32; items.clear(); return true; }
    if (nextHeaderOffset + nextHeaderSize + 32 > data.size() || nextHeaderOffset + 32 < 32) { err = "Unexpected end of archive"; return false; }
    db.physSize = 32 + nextHeaderOffset + nextHeaderSize;
    const Byte *hp = data.data() + 32 + nextHeaderOffset;
    if (Crc32Calc(hp, (size_t)nextHeaderSize) != nextHeaderCrc) { err = "Headers Error"; return false; }
    Buf header(hp, hp + nextHeaderSize);
    UInt64 packedHeadersTotal = 0;
    for (int iter = 0; iter < 8; iter++) {
      InByte in(header.data(), header.size());
      UInt64 type = in.ReadNumber();
      if (type == NID::kHeader) { ReadHeader(in, db); break; }
      if (type != NID::kEncodedHeader) { err = "Headers Error"; return false; }
      SzDb tmp; std::vector<UInt64> us; std::vector<bool> dd; std::vector<UInt32> dg;
      ReadStreamsInfo(in, tmp, us, dd, dg);
      if (tmp.folders.empty()) { err = "Headers Error"; return false; }
      ComputePackStarts(tmp);
      for (auto s : tmp.packSizes) packedHeadersTotal += s;
      for (auto &f : tmp.folders) for (auto &c : f.coders) if (c.id == k_AES) { headerIsEncrypted = true; db.isEncrypted = true; }
      ExtractResult res; bool np = false;
      try {
        header = DecodeFolderData(tmp, 0, data, password, res, np);
      } catch (DataError &) {
        if (np) { needPassword = true; err = "Can not open encrypted archive. Wrong password?"; return false; }
        err = headerIsEncrypted ? "Can not open encrypted archive. Wrong password?" : "Headers Error"; return false;
      } catch (UnsupportedMethod &) { err = "Unsupported method"; return false; }
      if (res == kCRCError) { err = headerIsEncrypted ? "Can not open encrypted archive. Wrong password?" : "Headers Error"; return false; }
    }
    ComputePackStarts(db);
    // sizes check
    UInt64 packTotal = 0; for (auto s : db.packSizes) packTotal += s;
    if (32 + db.packPos + packTotal > db.physSize) { err = "Unexpected end of archive"; return false; }
    db.headersSize = db.physSize - packTotal;
    // folders' number of unpack streams: ensure files mapping
    // build items
    items.clear();
    for (size_t i = 0; i < db.files.size(); i++) {
      const SzFile &f = db.files[i];
      ArcItem it;
      it.path = f.name; it.isDir = f.isDir; it.isAnti = f.isAnti; it.hasStream = f.hasStream;
      it.size = f.size; it.hasSize = true;
      it.folderIndex = f.folderIndex;
      if (!f.hasStream) { it.hasPackSize = true; it.packSize = 0; }
      else if (f.indexInFolder == 0) {
        const SzFolder &fo = db.folders[f.folderIndex];
        UInt64 ps = 0; for (size_t k = 0; k < fo.packStreams.size(); k++) ps += db.packSizes[fo.firstPackStreamIndex + k];
        it.hasPackSize = true; it.packSize = ps;
      } else it.hasPackSize = false;
      if (f.mtimeDefined) { it.mtime.defined = true; it.mtime.ft = f.mtime; it.mtime.prec = 7; }
      if (f.ctimeDefined) { it.ctime.defined = true; it.ctime.ft = f.ctime; it.ctime.prec = 7; }
      if (f.atimeDefined) { it.atime.defined = true; it.atime.ft = f.atime; it.atime.prec = 7; }
      it.hasAttrib = f.attribDefined; it.attrib = f.attrib;
      if (f.attribDefined && (f.attrib & FILE_ATTRIBUTE_UNIX_EXTENSION_)) { it.hasPosixMode = true; it.posixMode = f.attrib >> 16; }
      it.hasCRC = f.crcDefined; it.crc = f.crc;
      if (f.folderIndex >= 0) {
        const SzFolder &fo = db.folders[f.folderIndex];
        for (auto &c : fo.coders) if (c.id == k_AES) { it.encrypted = true; db.isEncrypted = true; }
        it.method = FolderMethodString(fo);
      }
      items.push_back(it);
    }
    return true;
  } catch (UnexpectedEnd &) { err = "Unexpected end of archive"; return false; }
  catch (HeadersError &) { err = "Headers Error"; return false; }
  catch (DataError &) { err = "Headers Error"; return false; }
  catch (UnsupportedMethod &) { err = "Unsupported method"; return false; }
}

static std::string CoderPropsString(const SzCoder &c) {
  std::string s = MethodIdToName(c.id);
  switch (c.id) {
    case k_LZMA2: if (c.props.size() == 1) { Byte d = c.props[0]; s += ':'; if (d > 40) s += "unsupported"; else if ((d & 1) == 0) s += UInt64ToStr(d / 2 + 12); else s += DictSizeToString((UInt32)3 << (d / 2 + 11)); } break;
    case k_LZMA: if (c.props.size() == 5) { s += ':'; s += DictSizeToString(GetUi32(c.props.data() + 1)); } break;
    case k_PPMD: if (c.props.size() == 5) { s += ":o"; s += UInt64ToStr(c.props[0]); s += ":mem"; s += DictSizeToString(GetUi32(c.props.data() + 1)); } break;
    case k_Delta: if (c.props.size() == 1) { s += ':'; s += UInt64ToStr((UInt64)c.props[0] + 1); } break;
    case k_AES: if (c.props.size() >= 1) { s += ':'; s += UInt64ToStr((UInt64)(c.props[0] & 0x3F)); } break;
    default:
      if (!c.props.empty() && c.id != k_BCJ2) { s += ":["; s += HexBytes(c.props.data(), c.props.size(), true); s += "]"; }
  }
  return s;
}

std::string Sz7zArchive::FolderMethodString(const SzFolder &f) const {
  std::string s;
  for (size_t i = f.coders.size(); i != 0;) {
    i--;
    if (!s.empty()) s += ' ';
    s += CoderPropsString(f.coders[i]);
  }
  return s;
}

std::vector<PropVal> Sz7zArchive::ArchiveProps() const {
  std::vector<PropVal> r;
  r.push_back({"Physical Size", UInt64ToStr(db.physSize)});
  r.push_back({"Headers Size", UInt64ToStr(db.headersSize)});
  // Method: unique ids sorted; LZMA/LZMA2 max dict
  struct M { UInt64 id; UInt32 dict; bool hasDict; };
  std::vector<M> ms;
  for (const auto &f : db.folders) for (const auto &c : f.coders) {
    UInt32 dict = 0; bool hasDict = false;
    if (c.id == k_LZMA2 && c.props.size() == 1 && c.props[0] <= 40) { dict = c.props[0] == 40 ? 0xFFFFFFFF : Lzma2DictFromProp(c.props[0]); hasDict = true; }
    else if (c.id == k_LZMA && c.props.size() == 5) { dict = GetUi32(c.props.data() + 1); hasDict = true; }
    bool found = false;
    for (auto &m : ms) if (m.id == c.id) { found = true; if (hasDict && dict > m.dict) m.dict = dict; }
    if (!found) ms.push_back({c.id, dict, hasDict});
  }
  std::sort(ms.begin(), ms.end(), [](const M &a, const M &b) { return a.id < b.id; });
  std::string s;
  for (auto &m : ms) {
    if (!s.empty()) s += ' ';
    s += MethodIdToName(m.id);
    if (m.hasDict) { s += ':'; s += DictSizeToString(m.dict); }
  }
  if (!db.folders.empty()) r.push_back({"Method", s});
  bool solid = false; for (const auto &f : db.folders) if (f.numUnpackStreams > 1) solid = true;
  if (!db.folders.empty()) {
    r.push_back({"Solid", solid ? "+" : "-"});
    r.push_back({"Blocks", UInt64ToStr((UInt64)db.folders.size())});
  }
  return r;
}

Buf Sz7zArchive::DecodeFolder(unsigned folderIndex, const std::string &pw, ExtractResult &res) {
  if (cachedFolder == (int)folderIndex) { res = kOK; return cachedFolderData; }
  bool np = false;
  Buf out = DecodeFolderData(db, folderIndex, data, pw, res, np);
  cachedFolder = (int)folderIndex; cachedFolderData = out;
  return out;
}

ExtractResult Sz7zArchive::ExtractItem(size_t index, const std::string &pw, std::function<void(const Byte *, size_t)> out, bool &crcChecked) {
  const SzFile &f = db.files[index];
  crcChecked = false;
  if (!f.hasStream) return kOK;
  ExtractResult res;
  Buf folderData;
  try { folderData = DecodeFolder((unsigned)f.folderIndex, pw, res); }
  catch (UnsupportedMethod &) { return kUnsupportedMethod; }
  catch (DataError &e) {
    const SzFolder &fo = db.folders[f.folderIndex];
    for (auto &c : fo.coders) if (c.id == k_AES) return kWrongPassword;
    if (std::string(e.what()).find("Unexpected end") != std::string::npos) return kUnexpectedEnd;
    return kDataError;
  }
  // position within folder
  UInt64 start = 0;
  UInt32 first = db.folderStartFileIndex[f.folderIndex];
  for (size_t i = first; i < index; i++) if (db.files[i].hasStream && db.files[i].folderIndex == f.folderIndex) start += db.files[i].size;
  if (start + f.size > folderData.size()) return kDataError;
  out(folderData.data() + start, (size_t)f.size);
  if (f.crcDefined) {
    crcChecked = true;
    if (Crc32Calc(folderData.data() + start, (size_t)f.size) != f.crc) {
      const SzFolder &fo = db.folders[f.folderIndex];
      for (auto &c : fo.coders) if (c.id == k_AES) return kWrongPassword;
      return kCRCError;
    }
  }
  return kOK;
}

// ---------------- Writer ----------------
struct OutByte {
  Buf b;
  void WriteByte(Byte v) { b.push_back(v); }
  void WriteBytes(const void *p, size_t n) { b.insert(b.end(), (const Byte*)p, (const Byte*)p + n); }
  void WriteUInt32(UInt32 v) { Byte t[4]; SetUi32(t, v); WriteBytes(t, 4); }
  void WriteUInt64(UInt64 v) { Byte t[8]; SetUi64(t, v); WriteBytes(t, 8); }
  void WriteNumber(UInt64 value) {
    Byte firstByte = 0; Byte mask = 0x80; int i;
    for (i = 0; i < 8; i++) {
      if (value < ((UInt64)1 << (7 * (i + 1)))) { firstByte |= (Byte)(value >> (8 * i)); break; }
      firstByte |= mask; mask >>= 1;
    }
    WriteByte(firstByte);
    for (; i > 0; i--) { WriteByte((Byte)value); value >>= 8; }
  }
  size_t GetPos() const { return b.size(); }
  void WriteBoolVector(const std::vector<bool> &v) {
    Byte bb = 0, mask = 0x80;
    for (bool x : v) { if (x) bb |= mask; mask >>= 1; if (mask == 0) { WriteByte(bb); mask = 0x80; bb = 0; } }
    if (mask != 0x80) WriteByte(bb);
  }
  void SkipToAligned(unsigned pos, unsigned alignShifts) {
    const unsigned alignSize = 1u << alignShifts;
    pos += (unsigned)GetPos();
    pos &= (alignSize - 1);
    if (pos == 0) return;
    unsigned skip = alignSize - pos;
    if (skip < 2) skip += alignSize;
    skip -= 2;
    WriteByte(NID::kDummy); WriteByte((Byte)skip);
    for (unsigned i = 0; i < skip; i++) WriteByte(0);
  }
  static unsigned GetBigNumberSize(UInt64 v) { unsigned i; for (i = 1; i < 9; i++) if (v < ((UInt64)1 << (i * 7))) break; return i; }
  void WriteAlignedBools(const std::vector<bool> &v, unsigned numDefined, Byte type, unsigned itemSizeShifts) {
    unsigned bvSize = (numDefined == v.size()) ? 0 : (unsigned)((v.size() + 7) / 8);
    UInt64 dataSize = (UInt64)numDefined * (1u << itemSizeShifts) + bvSize + 2;
    SkipToAligned(3 + bvSize + GetBigNumberSize(dataSize), itemSizeShifts);
    WriteByte(type); WriteNumber(dataSize);
    if (numDefined == v.size()) WriteByte(1); else { WriteByte(0); WriteBoolVector(v); }
    WriteByte(0);
  }
  void WritePropBoolVector(Byte id, const std::vector<bool> &v) { WriteByte(id); WriteNumber((v.size() + 7) / 8); WriteBoolVector(v); }
};

static void WritePackInfo(OutByte &o, UInt64 dataOffset, const std::vector<UInt64> &packSizes) {
  if (packSizes.empty()) return;
  o.WriteByte(NID::kPackInfo); o.WriteNumber(dataOffset); o.WriteNumber(packSizes.size());
  o.WriteByte(NID::kSize);
  for (auto s : packSizes) o.WriteNumber(s);
  o.WriteByte(NID::kEnd);
}

static void WriteFolder(OutByte &o, const SzFolder &f) {
  o.WriteNumber(f.coders.size());
  for (const auto &c : f.coders) {
    Byte idb[8]; unsigned idSize = 0;
    { UInt64 id = c.id; do { idb[idSize++] = (Byte)id; id >>= 8; } while (id != 0 && idSize < 8); }
    // reverse to big-endian
    Byte mainByte = (Byte)idSize;
    bool isComplex = !(c.numInStreams == 1 && c.numOutStreams == 1);
    if (isComplex) mainByte |= 0x10;
    if (!c.props.empty()) mainByte |= 0x20;
    o.WriteByte(mainByte);
    for (unsigned i = idSize; i != 0;) { i--; o.WriteByte(idb[i]); }
    if (isComplex) { o.WriteNumber(c.numInStreams); o.WriteNumber(c.numOutStreams); }
    if (!c.props.empty()) { o.WriteNumber(c.props.size()); o.WriteBytes(c.props.data(), c.props.size()); }
  }
  for (const auto &bp : f.bindPairs) { o.WriteNumber(bp.first); o.WriteNumber(bp.second); }
  if (f.packStreams.size() > 1) for (auto ps : f.packStreams) o.WriteNumber(ps);
}

static void WriteUnpackInfo(OutByte &o, const std::vector<SzFolder> &folders) {
  if (folders.empty()) return;
  o.WriteByte(NID::kUnpackInfo);
  o.WriteByte(NID::kFolder); o.WriteNumber(folders.size()); o.WriteByte(0);
  for (const auto &f : folders) WriteFolder(o, f);
  o.WriteByte(NID::kCodersUnpackSize);
  for (const auto &f : folders) for (auto s : f.unpackSizes) o.WriteNumber(s);
  // folder CRCs
  bool anyCrc = false; for (const auto &f : folders) if (f.crcDefined) anyCrc = true;
  if (anyCrc) {
    std::vector<bool> defs; for (const auto &f : folders) defs.push_back(f.crcDefined);
    o.WriteByte(NID::kCRC);
    unsigned nd = 0; for (bool b : defs) if (b) nd++;
    if (nd == defs.size()) o.WriteByte(1); else { o.WriteByte(0); o.WriteBoolVector(defs); }
    for (const auto &f : folders) if (f.crcDefined) o.WriteUInt32(f.crc);
  }
  o.WriteByte(NID::kEnd);
}

static void WriteSubStreamsInfo(OutByte &o, const std::vector<SzFolder> &folders, const std::vector<UInt32> &numUnpackStreams, const std::vector<UInt64> &unpackSizes, const std::vector<bool> &digestDefs, const std::vector<UInt32> &digests) {
  o.WriteByte(NID::kSubStreamsInfo);
  size_t i;
  for (i = 0; i < folders.size(); i++) if (numUnpackStreams[i] != 1) { o.WriteByte(NID::kNumUnpackStream); for (auto n : numUnpackStreams) o.WriteNumber(n); break; }
  bool needSizes = false;
  for (i = 0; i < folders.size(); i++) if (numUnpackStreams[i] > 1) needSizes = true;
  if (needSizes) {
    o.WriteByte(NID::kSize);
    size_t idx = 0;
    for (i = 0; i < folders.size(); i++) { UInt32 n = numUnpackStreams[i]; for (UInt32 j = 0; j < n; j++, idx++) if (j + 1 < n) o.WriteNumber(unpackSizes[idx]); }
  }
  std::vector<bool> defs; std::vector<UInt32> vals;
  size_t idx = 0;
  for (i = 0; i < folders.size(); i++) {
    UInt32 n = numUnpackStreams[i];
    if (n == 1 && folders[i].crcDefined) { idx++; continue; }
    for (UInt32 j = 0; j < n; j++, idx++) { defs.push_back(digestDefs[idx]); vals.push_back(digests[idx]); }
  }
  unsigned nd = 0; for (bool b : defs) if (b) nd++;
  if (nd != 0) {
    o.WriteByte(NID::kCRC);
    if (nd == defs.size()) o.WriteByte(1); else { o.WriteByte(0); o.WriteBoolVector(defs); }
    for (size_t k = 0; k < defs.size(); k++) if (defs[k]) o.WriteUInt32(vals[k]);
  }
  o.WriteByte(NID::kEnd);
}

static Buf WriteHeaderBytes(const SzOutDb &db) {
  OutByte o;
  o.WriteByte(NID::kHeader);
  if (!db.folders.empty()) {
    o.WriteByte(NID::kMainStreamsInfo);
    WritePackInfo(o, 0, db.packSizes);
    WriteUnpackInfo(o, db.folders);
    std::vector<UInt64> unpackSizes; std::vector<bool> digestDefs; std::vector<UInt32> digests;
    for (const auto &f : db.files) if (f.hasStream) { unpackSizes.push_back(f.size); digestDefs.push_back(f.crcDefined); digests.push_back(f.crc); }
    WriteSubStreamsInfo(o, db.folders, db.numUnpackStreams, unpackSizes, digestDefs, digests);
    o.WriteByte(NID::kEnd);
  }
  if (db.files.empty()) { o.WriteByte(NID::kEnd); return o.b; }
  o.WriteByte(NID::kFilesInfo); o.WriteNumber(db.files.size());
  {
    std::vector<bool> emptyStream(db.files.size(), false); unsigned numEmpty = 0;
    for (size_t i = 0; i < db.files.size(); i++) if (!db.files[i].hasStream) { emptyStream[i] = true; numEmpty++; }
    if (numEmpty != 0) {
      o.WritePropBoolVector(NID::kEmptyStream, emptyStream);
      std::vector<bool> emptyFile, anti; bool thereAreEmptyFiles = false, thereAreAnti = false;
      for (const auto &f : db.files) { if (f.hasStream) continue; emptyFile.push_back(!f.isDir); if (!f.isDir) thereAreEmptyFiles = true; anti.push_back(f.isAnti); if (f.isAnti) thereAreAnti = true; }
      if (thereAreEmptyFiles) o.WritePropBoolVector(NID::kEmptyFile, emptyFile);
      if (thereAreAnti) o.WritePropBoolVector(NID::kAnti, anti);
    }
  }
  {
    unsigned numDefined = 0; size_t namesDataSize = 0;
    std::vector<std::vector<uint16_t>> names;
    for (const auto &f : db.files) { names.push_back(Utf8ToUtf16(f.name)); if (!f.name.empty()) numDefined++; namesDataSize += (names.back().size() + 1) * 2; }
    if (numDefined > 0) {
      namesDataSize++;
      o.SkipToAligned(2 + OutByte::GetBigNumberSize(namesDataSize), 4);
      o.WriteByte(NID::kName); o.WriteNumber(namesDataSize); o.WriteByte(0);
      for (const auto &n : names) { for (uint16_t c : n) { o.WriteByte((Byte)c); o.WriteByte((Byte)(c >> 8)); } o.WriteByte(0); o.WriteByte(0); }
    }
  }
  auto writeTimes = [&](Byte type, int which) {
    std::vector<bool> defs; unsigned nd = 0;
    for (const auto &f : db.files) { bool d = which == 0 ? f.ctimeDefined : which == 1 ? f.atimeDefined : f.mtimeDefined; defs.push_back(d); if (d) nd++; }
    if (nd == 0) return;
    o.WriteAlignedBools(defs, nd, type, 3);
    for (const auto &f : db.files) { bool d = which == 0 ? f.ctimeDefined : which == 1 ? f.atimeDefined : f.mtimeDefined; if (d) o.WriteUInt64(which == 0 ? f.ctime : which == 1 ? f.atime : f.mtime); }
  };
  writeTimes(NID::kCTime, 0); writeTimes(NID::kATime, 1); writeTimes(NID::kMTime, 2);
  {
    std::vector<bool> defs; unsigned nd = 0;
    for (const auto &f : db.files) { defs.push_back(f.attribDefined); if (f.attribDefined) nd++; }
    if (nd != 0) {
      o.WriteAlignedBools(defs, nd, NID::kWinAttrib, 2);
      for (const auto &f : db.files) if (f.attribDefined) o.WriteUInt32(f.attrib);
    }
  }
  o.WriteByte(NID::kEnd);
  o.WriteByte(NID::kEnd);
  return o.b;
}

Buf Sz7zWriteArchiveToStream(const SzOutDb &db, std::function<void(const Byte*, size_t)> write, const std::vector<Buf> &packStreams, const SzHeaderOptions &opts) {
  Buf header = WriteHeaderBytes(db);
  UInt64 packTotal = 0; for (auto &p : packStreams) packTotal += p.size();
  Buf extraPacked; // encoded header packed data
  Buf finalHeader;
  bool compress = opts.compressHeader && db.files.size() > 1;
  if (opts.encryptHeader) compress = true;
  if (compress) {
    // encode header with LZMA (dict 1MB, fb 273? use defaults from 7-zip header options)
    LzmaProps p; p.level = 5; p.dictSize = 1 << 20; p.fb = 273; p.algo = 1; p.mf = "bt4";
    Byte lzProps[5];
    Buf packed = LzmaEncode(header, p, lzProps);
    SetUi32(lzProps + 1, 1 << 20);
    SzFolder f; SzCoder c; c.id = k_LZMA; c.props.assign(lzProps, lzProps + 5); f.coders.push_back(c);
    std::vector<Buf> hdrPack; hdrPack.push_back(packed);
    if (opts.encryptHeader) {
      Buf aesProps; Buf enc = Aes7zEncode(packed, opts.password, aesProps);
      SzCoder a; a.id = k_AES; a.props = aesProps;
      // storage: coder0 = AES (reads pack), coder1 = LZMA
      f.coders.clear(); f.coders.push_back(a); f.coders.push_back(c);
      f.bindPairs.push_back({1, 0});
      f.unpackSizes = { (UInt64)packed.size(), (UInt64)header.size() };
      hdrPack[0] = enc;
    } else {
      f.unpackSizes = { (UInt64)header.size() };
    }
    f.packStreams = {0};
    f.crcDefined = true; f.crc = Crc32Calc(header.data(), header.size());
    OutByte o;
    o.WriteByte(NID::kEncodedHeader);
    std::vector<UInt64> ps; ps.push_back(hdrPack[0].size());
    WritePackInfo(o, packTotal, ps);
    WriteUnpackInfo(o, std::vector<SzFolder>{f});
    o.WriteByte(NID::kEnd);
    extraPacked = hdrPack[0];
    finalHeader = o.b;
  } else finalHeader = header;
  // signature header
  Byte sh[32];
  memcpy(sh, kSignature, 6); sh[6] = 0; sh[7] = 4;
  UInt64 nextHeaderOffset = packTotal + extraPacked.size();
  SetUi64(sh + 12, nextHeaderOffset); SetUi64(sh + 20, finalHeader.size()); SetUi32(sh + 28, Crc32Calc(finalHeader.data(), finalHeader.size()));
  SetUi32(sh + 8, Crc32Calc(sh + 12, 20));
  write(sh, 32);
  for (auto &p : packStreams) write(p.data(), p.size());
  write(extraPacked.data(), extraPacked.size());
  write(finalHeader.data(), finalHeader.size());
  return Buf();
}

Buf Sz7zWriteArchive(const SzOutDb &db, const std::vector<Buf> &packStreams, const SzHeaderOptions &opts) {
  Buf out;
  Sz7zWriteArchiveToStream(db, [&](const Byte *p, size_t n) { out.insert(out.end(), p, p + n); }, packStreams, opts);
  return out;
}
