#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

bool ReadWholeFile(const std::string &path, Buf &data, int &err) {
  int fd = open(path.c_str(), O_RDONLY);
  if (fd < 0) { err = errno; return false; }
  struct stat st;
  if (fstat(fd, &st) != 0) { err = errno; close(fd); return false; }
  if (S_ISDIR(st.st_mode)) { err = EISDIR; close(fd); return false; }
  data.clear();
  if (S_ISREG(st.st_mode)) data.reserve((size_t)st.st_size);
  Byte buf[1 << 16];
  for (;;) {
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n < 0) { err = errno; close(fd); return false; }
    if (n == 0) break;
    data.insert(data.end(), buf, buf + n);
  }
  close(fd);
  return true;
}

