#include "arcopen.h"
#include "console.h"
#include <algorithm>

ArcScanResult ScanArchives(const Options &o, bool printStat) {
  ArcScanResult r;
  if (g_Out) { *g_Out << "Scanning the drive for archives:" << endl; g_Out->Flush(); }
  DirItems di;
  EnumerateItems(o.arcCensor, di, true, "");
  if (!di.errors.empty()) {
    const ScanError &e = di.errors[0];
    if (g_Err) { *g_Err << endl << "ERROR: " << ErrnoMessage(e.err) << endl << e.path << endl << endl; }
    throw SystemException(e.err);
  }
  for (const auto &it : di.items) if (!it.isDir) { r.paths.push_back(it.phyPath); r.numFiles++; r.totalSize += it.size; }
  std::sort(r.paths.begin(), r.paths.end(), [](const std::string &a, const std::string &b) { return CompareFileNames(a, b) < 0; });
  if (r.paths.empty()) throw CmdLineException("Cannot find archive");
  if (printStat && g_Out) *g_Out << FilesFoldersString(0, r.numFiles, true, r.totalSize) << endl << endl;
  return r;
}

void OpenArcFile(const Options &o, const std::string &path, OpenedArc &res, bool allowNested) {
  res.path = path;
  int err;
  if (!ReadWholeFile(path, res.data, err)) { res.sysErr = err; res.openOk = false; return; }
  std::string typeHint = o.arcTypeSet ? o.arcType : "";
  OpenResult orr = OpenArchive(res.data, path, typeHint, o.excludedArcTypes, o.password);
  if (!orr.arc) { res.openOk = false; res.errorMessage = orr.errorMessage; res.formatTried = orr.formatTried; res.needPassword = orr.needPassword; return; }
  res.arc.reset(orr.arc); res.format = orr.format; res.openOk = true;
  // nested: if single-file container (gzip/bzip2/xz/lzma/zstd) containing a tar
  if (allowNested && !o.arcTypeSet) {
    for (int depth = 0; depth < 4; depth++) {
      if (!res.format->keepName || res.arc->NumItems() != 1) break;
      // decode inner
      Buf inner;
      bool crcChecked;
      ExtractResult er;
      try { er = res.arc->ExtractItem(0, o.password, [&](const Byte *p, size_t n) { inner.insert(inner.end(), p, p + n); }, crcChecked); }
      catch (...) { break; }
      if (er != kOK) break;
      const ArcItem &it = res.arc->Item(0);
      OpenResult inr = OpenArchive(inner, it.path, "", o.excludedArcTypes, o.password);
      if (!inr.arc) break;
      // only treat as nested if inner is tar (7-zip opens any, but mainly tar)
      res.parents.push_back(std::move(res.arc)); res.parentFormats.push_back(res.format);
      res.arc.reset(inr.arc); res.format = inr.format; res.data = inner; res.path = it.path;
      if (!res.format->keepName) break;
    }
  }
}

void PrintArcProps(OutStream &so, const OpenedArc &oa) {
  // parents first (outer), then inner
  std::vector<std::pair<IArchive*, const FormatInfo*>> chain;
  for (size_t i = 0; i < oa.parents.size(); i++) chain.push_back({oa.parents[i].get(), oa.parentFormats[i]});
  chain.push_back({oa.arc.get(), oa.format});
  std::string path = oa.parents.empty() ? oa.path : "";
  for (size_t i = 0; i < chain.size(); i++) {
    so << "--" << endl;
    std::string p;
    if (i == 0) p = oa.parents.empty() ? oa.path : "";
    if (i == 0 && !oa.parents.empty()) {
      // outer path is the file path; compute from the chain: the original file path isn't stored; use oa.path for inner
    }
    so << "Path = " << (i == 0 ? (oa.parents.empty() ? oa.path : oa.parentsPath0) : (i == chain.size() - 1 ? oa.path : oa.parentsPath0)) << endl;
    so << "Type = " << chain[i].second->name << endl;
    for (const auto &pv : chain[i].first->ArchiveProps()) so << pv.name << " = " << pv.value << endl;
    so << endl;
  }
}

void PrintOpenArchiveError(OutStream &se, const OpenedArc &oa) {
  if (oa.needPassword) { se << "Cannot open encrypted archive. Wrong password?"; se << endl << endl; return; }
  if (!oa.formatTried.empty()) {
    se << oa.path << endl;
    se << "Open ERROR: Cannot open the file as [" << oa.formatTried << "] archive" << endl;
    se << endl << endl;
    if (!oa.errorMessage.empty()) se << "ERRORS:" << endl << oa.errorMessage << endl;
  } else {
    se << "Cannot open the file as archive" << endl << endl;
  }
}

std::string ExtractResultMessage(ExtractResult r) {
  switch (r) {
    case kOK: return "";
    case kUnsupportedMethod: return "Unsupported Method";
    case kDataError: return "Data Error";
    case kCRCError: return "CRC Failed";
    case kUnavailable: return "Unavailable data";
    case kUnexpectedEnd: return "Unexpected end of data";
    case kDataAfterEnd: return "There are some data after the end of the payload data";
    case kIsNotArc: return "Is not archive";
    case kHeadersError: return "Headers Error";
    case kWrongPassword: return "Wrong password";
  }
  return "";
}
