  for (size_t i = 0; i < oa.parents.size(); i++) chain.push_back({oa.parents[i].get(), oa.parentFormats[i]});
  chain.push_back({oa.arc.get(), oa.format});
  std::string path = oa.parents.empty() ? oa.path : "";
  for (size_t i = 0; i < chain.size(); i++) {
    so << "--" << endl;
    std::string p;
    if (i == 0) p = oa.parents.empty() ? oa.path : "";
    if (i == 0 && !oa.parents.empty()) {
      // outer path is the file path; compute from the chain: the original file path isn't stored; use oa.path for inner
    }
    so << "Path = " << (i == 0 ? (oa.parents.empty() ? oa.path : oa.parentsPath0) : (i == chain.size() - 1 ? oa.path : oa.parentsPath0)) << endl;
    so << "Type = " << chain[i].second->name << endl;
    for (const auto &pv : chain[i].first->ArchiveProps()) so << pv.name << " = " << pv.value << endl;
    so << endl;
  }
}

void PrintOpenArchiveError(OutStream &se, const OpenedArc &oa) {
  if (oa.needPassword) { se << "Cannot open encrypted archive. Wrong password?"; se << endl << endl; return; }
  if (!oa.formatTried.empty()) {
    se << oa.path << endl;
    se << "Open ERROR: Cannot open the file as [" << oa.formatTried << "] archive" << endl;
    se << endl << endl;
    if (!oa.errorMessage.empty()) se << "ERRORS:" << endl << oa.errorMessage << endl;
  } else {
    se << "Cannot open the file as archive" << endl << endl;
  }
}

std::string ExtractResultMessage(ExtractResult r) {
  switch (r) {
    case kOK: return "";
    case kUnsupportedMethod: return "Unsupported Method";
    case kDataError: return "Data Error";
    case kCRCError: return "CRC Failed";
    case kUnavailable: return "Unavailable data";
    case kUnexpectedEnd: return "Unexpected end of data";
    case kDataAfterEnd: return "There are some data after the end of the payload data";
    case kIsNotArc: return "Is not archive";
    case kHeadersError: return "Headers Error";
    case kWrongPassword: return "Wrong password";
  }
  return "";
}
