int CommandList(const Options &o) {
  ArcScanResult scan = ScanArchives(o, true);
  OutStream &so = g_Out ? *g_Out : g_StdOut; bool haveOut = g_Out != nullptr;
  unsigned numErrors = 0;
  ListStat total; UInt64 numArcs = 0, numVolumes = 0, totalArcSize = 0;
  bool techMode = o.techMode;
  for (const std::string &arcPath : scan.paths) {
    if (o.enableHeaders && haveOut) so << endl << "Listing archive: " << arcPath << endl << endl;
    OpenedArc oa;
    OpenArcFile(o, arcPath, oa, false);
    if (!oa.openOk) {
      so.Flush();
      if (g_Err) {
        *g_Err << endl << "ERROR: " << arcPath << " : ";
        if (oa.sysErr) *g_Err << ErrnoMessage(oa.sysErr) << endl;
        else PrintOpenArchiveError(*g_Err, oa);
        *g_Err << endl;
      }
      numErrors++;
      continue;
    }
    numArcs++; numVolumes++; totalArcSize += oa.data.size();
    if (o.enableHeaders && haveOut) PrintArcProps(so, oa);
    IArchive &arc = *oa.arc;
    if (o.enableHeaders && !techMode && haveOut) { PrintTitle(so); PrintTitleLines(so); }
    if (techMode && haveOut) so << "----------" << endl;
    ListStat st;
    for (size_t i = 0; i < arc.NumItems(); i++) {
      const ArcItem &it = arc.Item(i);
      std::string name = GetItemDisplayName(it, arcPath, oa.format);
      if (!o.censor.includeItems.empty() || !o.censor.excludeItems.empty()) {
        if (!o.censor.CheckPath(name, !it.isDir)) continue;
      }
      if (it.isDir) st.numDirs++; else st.numFiles++;
      if (it.hasSize) { st.size += it.size; st.sizeDef = true; }
      if (it.hasPackSize) { st.packSize += it.packSize; st.packDef = true; }
      if (it.mtime.defined && (!st.maxTime.defined || it.mtime.ft > st.maxTime.ft)) st.maxTime = it.mtime;
      if (!haveOut) continue;
      if (techMode) {
        for (const auto &pv : it.props) so << pv.name << " = " << pv.value << endl;
        so << endl;
      } else {
        std::string line;
        if (it.mtime.defined) line += FileTimeToString(it.mtime.ft, true, 0); else line += std::string(19, ' ');
        line += ' ';
        if (it.hasAttrib || it.isDir) line += AttribToString5(it.hasAttrib ? it.attrib : 0, it.isDir); else line += (it.isDir ? "D...." : ".....");
        line += ' ';
        line += PadLeft(it.hasSize ? UInt64ToStr(it.size) : "", 12);
        line += ' ';
        line += PadLeft(it.hasPackSize ? UInt64ToStr(it.packSize) : "", 12);
        line += "  ";
        line += name;
        so << line << endl;
      }
    }
    if (o.enableHeaders && !techMode && haveOut) { PrintTitleLines(so); PrintSum(so, st); }
    total.numFiles += st.numFiles; total.numDirs += st.numDirs; total.size += st.size; total.packSize += st.packSize;
    if (st.maxTime.defined && (!total.maxTime.defined || st.maxTime.ft > total.maxTime.ft)) total.maxTime = st.maxTime;
  }
  if (haveOut) {
    if (o.enableHeaders && !techMode && numArcs > 1) { so << endl; PrintTitleLines(so); PrintSum(so, total); }
    if (numArcs > 1) { so << endl << "Archives: " << numArcs << endl << "Volumes: " << numVolumes << endl << "Total archives size: " << totalArcSize << endl; }
    if (numErrors > 0) so << endl << "Errors: " << numErrors << endl;
  }
  return numErrors > 0 ? 2 : 0;
}

std::string GetItemDisplayName(const ArcItem &it, const std::string &arcPath, const FormatInfo *fmt) {
  if (!it.path.empty() || !fmt->keepName) return it.path;
  // derive from archive name: strip extension
  std::string base = GetBaseName(arcPath);
  size_t p = base.find_last_of('.');
  std::string name = (p == std::string::npos || p == 0) ? base : base.substr(0, p);
  if (p != std::string::npos) {
    std::string ext = ToLower(base.substr(p + 1));
    if (ext == "tgz" || ext == "tpz" || ext == "tbz" || ext == "tbz2" || ext == "txz" || ext == "tzst") name += ".tar";
    else if (ext == "apk") name += ".tar";
  }
  if (name.empty()) name = base;
  return name;
}
