#include "arczip.h"
#include <algorithm>

static const char *HostOsName(unsigned h) {
  static const char *names[] = { "FAT", "AMIGA", "VMS", "Unix", "VM/CMS", "Atari", "HPFS", "Mac", "Z-System", "CP/M", "TOPS-20", "NTFS", "SMS/QDOS", "Acorn", "VFAT", "MVS", "BeOS", "Tandem", "OS/400", "OS/X" };
  if (h < sizeof(names) / sizeof(names[0])) return names[h];
  return nullptr;
}

std::string ZipMethodName(UInt16 m) {
  switch (m) {
    case 0: return "Store"; case 1: return "Shrink"; case 2: return "Reduce1"; case 3: return "Reduce2"; case 4: return "Reduce3"; case 5: return "Reduce4";
    case 6: return "Implode"; case 7: return "Tokenize"; case 8: return "Deflate"; case 9: return "Deflate64"; case 10: return "PKImploding";
    case 12: return "BZip2"; case 14: return "LZMA"; case 16: return "CMPSC"; case 18: return "Terse"; case 19: return "Lz77"; case 20: return "ZstdPk";
    case 93: return "Zstd"; case 94: return "MP3"; case 95: return "xz"; case 96: return "Jpeg"; case 97: return "WavPack"; case 98: return "PPMd"; case 99: return "AES";
  }
  return UInt64ToStr(m);
}

static bool FindEcd(const Buf &d, size_t &ecdPos) {
  if (d.size() < 22) return false;
  size_t limit = d.size() > (22 + 65535 + 1024) ? d.size() - (22 + 65535 + 1024) : 0;
  for (size_t i = d.size() - 22; ; i--) {
    if (d[i] == 'P' && d[i+1] == 'K' && d[i+2] == 5 && d[i+3] == 6) {
      UInt32 cl = GetUi16(d.data() + i + 20);
      if (i + 22 + cl <= d.size()) { ecdPos = i; return true; }
    }
    if (i == limit) break;
  }
  return false;
}

static void ParseExtra(const Byte *p, size_t n, std::vector<ZipExtra> &out) {
  size_t pos = 0;
  while (pos + 4 <= n) {
    UInt16 id = (UInt16)GetUi16(p + pos); UInt32 sz = GetUi16(p + pos + 2);
    pos += 4;
    if (pos + sz > n) { ZipExtra e; e.id = id; e.data.assign(p + pos, p + n); out.push_back(e); break; }
    ZipExtra e; e.id = id; e.data.assign(p + pos, p + pos + sz); out.push_back(e);
    pos += sz;
  }
}

static std::string ExtraName(UInt16 id) {
  switch (id) {
    case 0x0001: return "Zip64"; case 0x000A: return "NTFS"; case 0x0017: return "StrongCrypto"; case 0x5455: return "UT"; case 0x5855: return "UX"; case 0x7855: return "Ux"; case 0x7875: return "ux";
    case 0x9901: return "WzAES"; case 0x5A4C? 0x5A4C : 0: return "";
  }
  char b[16]; snprintf(b, sizeof(b), "0x%X", id); return b;
}

bool ZipArchive::Open(const Buf &d, const std::string &p, std::string &err) {
  data = d; path = p;
  size_t ecdPos;
  if (!FindEcd(data, ecdPos)) { err = "Is not archive"; return false; }
  const Byte *ecd = data.data() + ecdPos;
  UInt64 numEntries = GetUi16(ecd + 10);
  UInt64 cdSz = GetUi32(ecd + 12), cdOff = GetUi32(ecd + 16);
  UInt32 commentLen = GetUi16(ecd + 20);
  arcComment.assign((const char*)ecd + 22, commentLen);
  // zip64 locator
  if (ecdPos >= 20 && memcmp(data.data() + ecdPos - 20, "PK\x06\x07", 4) == 0) {
    UInt64 z64Off = GetUi64(data.data() + ecdPos - 20 + 8);
    if (z64Off + 56 <= data.size() && memcmp(data.data() + z64Off, "PK\x06\x06", 4) == 0) {
      const Byte *z = data.data() + z64Off;
      numEntries = GetUi64(z + 32); cdSz = GetUi64(z + 40); cdOff = GetUi64(z + 48); isZip64 = true;
    }
  }
  // find actual cd start (handle prefix stub): cd should end at ecdPos (or z64 record)
  UInt64 cdEnd = isZip64 ? (ecdPos - 20) : ecdPos;
  // verify
  if (cdOff + cdSz > cdEnd) { err = "Is not archive"; return false; }
  startOffset = cdEnd - cdSz - cdOff; // stub size if any
  cdOffset = cdOff + startOffset; cdSize = cdSz;
  size_t pos = (size_t)cdOffset;
  for (UInt64 i = 0; i < numEntries; i++) {
    if (pos + 46 > data.size() || memcmp(data.data() + pos, "PK\x01\x02", 4) != 0) { err = "Headers Error"; return false; }
    const Byte *h = data.data() + pos;
    ZipItem it;
    it.madeByVersion = h[4]; it.madeByHost = h[5]; it.extractVersion = h[6]; it.extractHost = h[7];
    it.flags = (UInt16)GetUi16(h + 8); it.method = (UInt16)GetUi16(h + 10); it.dosTime = GetUi32(h + 12); it.crc = GetUi32(h + 16);
    it.packSize = GetUi32(h + 20); it.unpackSize = GetUi32(h + 24);
    UInt32 nameLen = GetUi16(h + 28), extraLen = GetUi16(h + 30), cmtLen = GetUi16(h + 32);
    it.diskNumber = GetUi16(h + 34); it.internalAttrib = (UInt16)GetUi16(h + 36); it.externalAttrib = GetUi32(h + 38); it.localHeaderOffset = GetUi32(h + 42);
    pos += 46;
    if (pos + nameLen + extraLen + cmtLen > data.size()) { err = "Headers Error"; return false; }
    it.rawName.assign(data.data() + pos, data.data() + pos + nameLen); pos += nameLen;
