        if (it.packSize == 0xFFFFFFFF && q + 8 <= e.data.size()) { it.packSize = GetUi64(e.data.data() + q); q += 8; }
        if (it.localHeaderOffset == 0xFFFFFFFF && q + 8 <= e.data.size()) { it.localHeaderOffset = GetUi64(e.data.data() + q); q += 8; }
        if (it.diskNumber == 0xFFFF && q + 4 <= e.data.size()) { it.diskNumber = GetUi32(e.data.data() + q); q += 4; }
