          if (tag == 1 && sz >= 24 && q + 24 <= e.data.size()) { it.hasNtfsTime = true; it.ntfsMTime = GetUi64(e.data.data() + q); it.ntfsATime = GetUi64(e.data.data() + q + 8); it.ntfsCTime = GetUi64(e.data.data() + q + 16); }
