    while (!it.path.empty() && it.path.back() == '/') it.path.pop_back();
    it.isDir = z.isDir;
    it.size = z.unpackSize; it.packSize = z.packSize;
    if (z.hasNtfsTime && z.ntfsMTime != 0) { it.mtime.defined = true; it.mtime.ft = z.ntfsMTime; it.mtime.prec = 7; }
    else if (z.hasUnixMTime) { it.mtime.defined = true; it.mtime.ft = UnixToFileTime(z.unixMTime); it.mtime.prec = 0; }
    else if (z.dosTime != 0) { it.mtime.defined = true; it.mtime.ft = DosTimeToFileTime(z.dosTime); it.mtime.prec = 0; }
    if (z.hasNtfsTime && z.ntfsCTime != 0) { it.ctime.defined = true; it.ctime.ft = z.ntfsCTime; it.ctime.prec = 7; }
    if (z.hasNtfsTime && z.ntfsATime != 0) { it.atime.defined = true; it.atime.ft = z.ntfsATime; it.atime.prec = 7; }
    UInt32 wa = 0;
    if (z.madeByHost == 0 || z.madeByHost == 11 || z.madeByHost == 14) wa = z.externalAttrib;
    else if (z.madeByHost == 3) { wa = (z.externalAttrib & 0xFFFF0000) | FILE_ATTRIBUTE_UNIX_EXTENSION_; it.hasPosixMode = true; it.posixMode = z.externalAttrib >> 16; }
    if (z.isDir) wa |= FILE_ATTRIBUTE_DIRECTORY_;
    it.hasAttrib = true; it.attrib = wa;
    it.hasCRC = !z.isDir; it.crc = z.crc;
    it.encrypted = (z.flags & 1) != 0;
    std::string m;
    if (it.encrypted) {
      if (z.isAes) { m = z.aesStrength == 1 ? "AES-128" : z.aesStrength == 2 ? "AES-192" : "AES-256"; m += " "; m += ZipMethodName(z.aesMethod); }
      else if (z.flags & 0x40) m = "StrongCrypto " + ZipMethodName(z.method);
      else m = "ZipCrypto " + ZipMethodName(z.method);
    } else m = ZipMethodName(z.method);
    it.method = m;
    it.comment = z.comment;
    // characteristics
    std::string ch;
    auto add = [&](const std::string &s) { if (s.empty()) return; if (!ch.empty()) ch += ' '; ch += s; };
    for (const auto &e : z.centralExtra) add(ExtraName(e.id));
    if (z.flags & (1 << 3)) add("Descriptor");
    if (z.flags & (1 << 11)) add("UTF8");
    if (z.flags & (1 << 6)) add("Strong");
    if (z.flags & (1 << 0) && false) add("Encrypt");
    it.props.push_back({"Path", it.path});
    it.props.push_back({"Folder", it.isDir ? "+" : "-"});
    it.props.push_back({"Size", UInt64ToStr(it.size)});
    it.props.push_back({"Packed Size", UInt64ToStr(it.packSize)});
    it.props.push_back({"Modified", it.mtime.defined ? FileTimeToString(it.mtime.ft, true, it.mtime.prec) : ""});
    it.props.push_back({"Created", it.ctime.defined ? FileTimeToString(it.ctime.ft, true, it.ctime.prec) : ""});
    it.props.push_back({"Accessed", it.atime.defined ? FileTimeToString(it.atime.ft, true, it.atime.prec) : ""});
    it.props.push_back({"Attributes", AttribToStringFull(wa)});
    it.props.push_back({"Encrypted", it.encrypted ? "+" : "-"});
    it.props.push_back({"Comment", z.comment});
    it.props.push_back({"CRC", it.hasCRC ? Hex8(z.crc) : ""});
    it.props.push_back({"Method", m});
    it.props.push_back({"Characteristics", ch});
    { const char *hn = HostOsName(z.madeByHost); it.props.push_back({"Host OS", hn ? hn : UInt64ToStr(z.madeByHost)}); }
    it.props.push_back({"Version", UInt64ToStr(z.extractVersion)});
    it.props.push_back({"Volume Index", UInt64ToStr(z.diskNumber)});
    it.props.push_back({"Offset", UInt64ToStr(z.localHeaderOffset)});
    items.push_back(it);
  }
  if (startOffset != 0) { /* embedded stub */ }
  if (data.size() > physSize + startOffset) warnings.push_back("There are data after the end of archive");
  return true;
}

std::vector<PropVal> ZipArchive::ArchiveProps() const {
  std::vector<PropVal> r;
  if (isZip64) r.push_back({"64-bit", "+"});
  if (!arcComment.empty()) r.push_back({"Comment", arcComment});
  r.push_back({"Physical Size", UInt64ToStr(physSize)});
  if (startOffset != 0) { r.push_back({"Offset", UInt64ToStr(startOffset)}); r.push_back({"Embedded Stub Size", UInt64ToStr(startOffset)}); }
  if (data.size() > physSize + startOffset) r.push_back({"Tail Size", UInt64ToStr(data.size() - physSize - startOffset)});
  return r;
}

// ZipCrypto
struct ZipCrypto {
  UInt32 k0, k1, k2;
  void UpdateKeys(Byte b) { k0 = Crc32Update(~k0 ^ 0 , &b, 1); }
};
static void ZcUpdate(UInt32 *k, Byte b) {
  // crc32 single byte without the ~ handling: use table
  k[0] = (~Crc32Update(~k[0], &b, 1));
  k[1] = (k[1] + (k[0] & 0xFF)) * 134775813 + 1;
  Byte t = (Byte)(k[1] >> 24);
  k[2] = (~Crc32Update(~k[2], &t, 1));
}
static Byte ZcDecryptByte(UInt32 *k) { UInt32 temp = k[2] | 2; return (Byte)((temp * (temp ^ 1)) >> 8); }

ExtractResult ZipArchive::ExtractItem(size_t index, const std::string &password, std::function<void(const Byte *, size_t)> out, bool &crcChecked) {
  const ZipItem &z = zitems[index];
  crcChecked = false;
  if (z.isDir) return kOK;
  UInt64 lh = z.localHeaderOffset + startOffset;
  if (lh + 30 > data.size() || memcmp(data.data() + lh, "PK\x03\x04", 4) != 0) return kHeadersError;
  const Byte *h = data.data() + lh;
  UInt32 nameLen = GetUi16(h + 26), extraLen = GetUi16(h + 28);
  UInt64 dataStart = lh + 30 + nameLen + extraLen;
  if (dataStart + z.packSize > data.size()) return kUnexpectedEnd;
  Buf packed(data.begin() + dataStart, data.begin() + dataStart + z.packSize);
  UInt16 method = z.method;
  if (z.flags & 1) {
    if (z.isAes) return kUnsupportedMethod;
    if (password.empty()) return kWrongPassword;
    if (packed.size() < 12) return kDataError;
    UInt32 k[3] = { 305419896, 591751049, 878082192 };
    for (char c : password) ZcUpdate(k, (Byte)c);
    Buf dec(packed.size());
    for (size_t i = 0; i < packed.size(); i++) { Byte c = packed[i] ^ ZcDecryptByte(k); ZcUpdate(k, c); dec[i] = c; }
    Byte check = (z.flags & 8) ? (Byte)(z.dosTime >> 8) : (Byte)(z.crc >> 24);
    if (dec[11] != check) return kWrongPassword;
    packed.assign(dec.begin() + 12, dec.end());
  }
  Buf res;
  try {
    switch (method) {
      case 0: res = packed; if (res.size() != z.unpackSize) return kDataError; break;
      case 8: res = DeflateDecode(packed, z.unpackSize, false); break;
      case 9: res = DeflateDecode(packed, z.unpackSize, true); break;
      case 12: res = BZip2Decode(packed, z.unpackSize); break;
      case 14: {
        if (packed.size() < 9) return kDataError;
        UInt32 ps = GetUi16(packed.data() + 2);
        if (ps != 5 || packed.size() < 4 + ps) return kUnsupportedMethod;
        Buf body(packed.begin() + 4 + ps, packed.end());
        res = LzmaDecode(packed.data() + 4, 5, body, z.unpackSize);
        break;
      }
      case 95: { XzInfo info; XzDecode(packed, res, info); break; }
      case 93: res = ZstdDecode(packed, z.unpackSize); break;
      default: return kUnsupportedMethod;
    }
  } catch (UnsupportedMethod &) { return kUnsupportedMethod; }
  catch (DataError &e) { if (std::string(e.what()).find("Unexpected end") != std::string::npos) return kUnexpectedEnd; return kDataError; }
  if (res.size() != z.unpackSize) return kDataError;
  out(res.data(), res.size());
  crcChecked = true;
  if (Crc32Calc(res.data(), res.size()) != z.crc) return (z.flags & 1) ? kWrongPassword : kCRCError;
  return kOK;
}

IArchive *OpenZip(const Buf &data, const std::string &path, const std::string &pw, bool &needPassword, std::string &err) {
  (void)pw; needPassword = false;
  ZipArchive *a = new ZipArchive();
  if (!a->Open(data, path, err)) { delete a; return nullptr; }
  return a;
}

// ---------------- Writer ----------------
static void Put16(Buf &b, UInt32 v) { Byte t[2]; SetUi16(t, v); b.insert(b.end(), t, t + 2); }
static void Put32(Buf &b, UInt32 v) { Byte t[4]; SetUi32(t, v); b.insert(b.end(), t, t + 4); }
static void Put64(Buf &b, UInt64 v) { Byte t[8]; SetUi64(t, v); b.insert(b.end(), t, t + 8); }

void ZipWriteLocalHeader(std::function<void(const Byte*, size_t)> write, ZipOutItem &it, UInt64 curOffset) {
  it.localHeaderOffset = curOffset;
  Buf b;
  b.insert(b.end(), {'P','K',3,4});
  bool z64 = it.unpackSize >= 0xFFFFFFFF || it.packSize >= 0xFFFFFFFF;
  UInt16 ver = it.extractVersion; if (z64 && ver < 45) ver = 45;
  Put16(b, ver); Put16(b, it.flags); Put16(b, it.method); Put32(b, it.dosTime); Put32(b, it.crc);
  Put32(b, z64 ? 0xFFFFFFFF : (UInt32)it.packSize); Put32(b, z64 ? 0xFFFFFFFF : (UInt32)it.unpackSize);
  Put16(b, (UInt32)it.name.size());
  Buf extra;
  if (z64) { Put16(extra, 1); Put16(extra, 16); Put64(extra, it.unpackSize); Put64(extra, it.packSize); }
  Put16(b, (UInt32)extra.size());
  b.insert(b.end(), it.name.begin(), it.name.end());
  b.insert(b.end(), extra.begin(), extra.end());
  write(b.data(), b.size());
}

void ZipWriteCentralDir(std::function<void(const Byte*, size_t)> write, const std::vector<ZipOutItem> &items, UInt64 cdStart, const std::string &comment) {
  Buf b;
  bool needZ64 = false;
  for (const auto &it : items) {
    b.insert(b.end(), {'P','K',1,2});
    bool z64 = it.unpackSize >= 0xFFFFFFFF || it.packSize >= 0xFFFFFFFF || it.localHeaderOffset >= 0xFFFFFFFF;
    if (z64) needZ64 = true;
    UInt16 ver = it.extractVersion; if (z64 && ver < 45) ver = 45;
    b.push_back(63); b.push_back(3); // made by: 6.3, Unix
    Put16(b, ver); Put16(b, it.flags); Put16(b, it.method); Put32(b, it.dosTime); Put32(b, it.crc);
    Put32(b, z64 ? 0xFFFFFFFF : (UInt32)it.packSize); Put32(b, z64 ? 0xFFFFFFFF : (UInt32)it.unpackSize);
    Put16(b, (UInt32)it.name.size());
    Buf extra;
    if (z64) {
      Buf z; if (it.unpackSize >= 0xFFFFFFFF) Put64(z, it.unpackSize); if (it.packSize >= 0xFFFFFFFF) Put64(z, it.packSize); if (it.localHeaderOffset >= 0xFFFFFFFF) Put64(z, it.localHeaderOffset);
      Put16(extra, 1); Put16(extra, (UInt32)z.size()); extra.insert(extra.end(), z.begin(), z.end());
    }
    if (it.writeNtfs) {
      Put16(extra, 0x000A); Put16(extra, 32); Put32(extra, 0); Put16(extra, 1); Put16(extra, 24);
      Put64(extra, it.ntfsMTime); Put64(extra, it.ntfsATime); Put64(extra, it.ntfsCTime);
    }
    Put16(b, (UInt32)extra.size());
    Put16(b, (UInt32)it.comment.size());
    Put16(b, 0); Put16(b, 0); Put32(b, it.externalAttrib);
    Put32(b, it.localHeaderOffset >= 0xFFFFFFFF ? 0xFFFFFFFF : (UInt32)it.localHeaderOffset);
    b.insert(b.end(), it.name.begin(), it.name.end());
    b.insert(b.end(), extra.begin(), extra.end());
    b.insert(b.end(), it.comment.begin(), it.comment.end());
  }
  UInt64 cdSize = b.size();
  UInt64 cdEnd = cdStart + cdSize;
  bool z64 = needZ64 || items.size() >= 0xFFFF || cdStart >= 0xFFFFFFFF || cdSize >= 0xFFFFFFFF;
  if (z64) {
    b.insert(b.end(), {'P','K',6,6}); Put64(b, 44); b.push_back(63); b.push_back(3); Put16(b, 45); Put32(b, 0); Put32(b, 0);
    Put64(b, items.size()); Put64(b, items.size()); Put64(b, cdSize); Put64(b, cdStart);
    b.insert(b.end(), {'P','K',6,7}); Put32(b, 0); Put64(b, cdEnd); Put32(b, 1);
  }
  b.insert(b.end(), {'P','K',5,6}); Put16(b, 0); Put16(b, 0);
  Put16(b, items.size() >= 0xFFFF ? 0xFFFF : (UInt32)items.size()); Put16(b, items.size() >= 0xFFFF ? 0xFFFF : (UInt32)items.size());
  Put32(b, cdSize >= 0xFFFFFFFF ? 0xFFFFFFFF : (UInt32)cdSize); Put32(b, cdStart >= 0xFFFFFFFF ? 0xFFFFFFFF : (UInt32)cdStart);
  Put16(b, (UInt32)comment.size());
  b.insert(b.end(), comment.begin(), comment.end());
  write(b.data(), b.size());
}
