static bool FindEcd(const Buf &d, size_t &ecdPos) {
  if (d.size() < 22) return false;
  size_t limit = d.size() > (22 + 65535 + 1024) ? d.size() - (22 + 65535 + 1024) : 0;
  for (size_t i = d.size() - 22; ; i--) {
    if (d[i] == 'P' && d[i+1] == 'K' && d[i+2] == 5 && d[i+3] == 6) {
      UInt32 cl = GetUi16(d.data() + i + 20);
      if (i + 22 + cl <= d.size()) { ecdPos = i; return true; }
    }
    if (i == limit) break;
  }
  return false;
}

static void ParseExtra(const Byte *p, size_t n, std::vector<ZipExtra> &out) {
  size_t pos = 0;
  while (pos + 4 <= n) {
    UInt16 id = (UInt16)GetUi16(p + pos); UInt32 sz = GetUi16(p + pos + 2);
    pos += 4;
    if (pos + sz > n) { ZipExtra e; e.id = id; e.data.assign(p + pos, p + n); out.push_back(e); break; }
    ZipExtra e; e.id = id; e.data.assign(p + pos, p + pos + sz); out.push_back(e);
    pos += sz;
  }
}

static std::string ExtraName(UInt16 id) {
  switch (id) {
