struct ZipCrypto {
  UInt32 k0, k1, k2;
  void UpdateKeys(Byte b) { k0 = Crc32Update(~k0 ^ 0 , &b, 1); }
};
static void ZcUpdate(UInt32 *k, Byte b) {
  // crc32 single byte without the ~ handling: use table
  k[0] = (~Crc32Update(~k[0], &b, 1));
  k[1] = (k[1] + (k[0] & 0xFF)) * 134775813 + 1;
  Byte t = (Byte)(k[1] >> 24);
  k[2] = (~Crc32Update(~k[2], &t, 1));
}
static Byte ZcDecryptByte(UInt32 *k) { UInt32 temp = k[2] | 2; return (Byte)((temp * (temp ^ 1)) >> 8); }

ExtractResult ZipArchive::ExtractItem(size_t index, const std::string &password, std::function<void(const Byte *, size_t)> out, bool &crcChecked) {
  const ZipItem &z = zitems[index];
  crcChecked = false;
  if (z.isDir) return kOK;
  UInt64 lh = z.localHeaderOffset + startOffset;
  if (lh + 30 > data.size() || memcmp(data.data() + lh, "PK\x03\x04", 4) != 0) return kHeadersError;
  const Byte *h = data.data() + lh;
  UInt32 nameLen = GetUi16(h + 26), extraLen = GetUi16(h + 28);
  UInt64 dataStart = lh + 30 + nameLen + extraLen;
  if (dataStart + z.packSize > data.size()) return kUnexpectedEnd;
  Buf packed(data.begin() + dataStart, data.begin() + dataStart + z.packSize);
  UInt16 method = z.method;
  if (z.flags & 1) {
    if (z.isAes) return kUnsupportedMethod;
    if (password.empty()) return kWrongPassword;
    if (packed.size() < 12) return kDataError;
    UInt32 k[3] = { 305419896, 591751049, 878082192 };
    for (char c : password) ZcUpdate(k, (Byte)c);
    Buf dec(packed.size());
    for (size_t i = 0; i < packed.size(); i++) { Byte c = packed[i] ^ ZcDecryptByte(k); ZcUpdate(k, c); dec[i] = c; }
    Byte check = (z.flags & 8) ? (Byte)(z.dosTime >> 8) : (Byte)(z.crc >> 24);
    if (dec[11] != check) return kWrongPassword;
    packed.assign(dec.begin() + 12, dec.end());
  }
  Buf res;
  try {
    switch (method) {
      case 0: res = packed; if (res.size() != z.unpackSize) return kDataError; break;
      case 8: res = DeflateDecode(packed, z.unpackSize, false); break;
      case 9: res = DeflateDecode(packed, z.unpackSize, true); break;
      case 12: res = BZip2Decode(packed, z.unpackSize); break;
      case 14: {
        if (packed.size() < 9) return kDataError;
        UInt32 ps = GetUi16(packed.data() + 2);
        if (ps != 5 || packed.size() < 4 + ps) return kUnsupportedMethod;
        Buf body(packed.begin() + 4 + ps, packed.end());
        res = LzmaDecode(packed.data() + 4, 5, body, z.unpackSize);
        break;
      }
      case 95: { XzInfo info; XzDecode(packed, res, info); break; }
      case 93: res = ZstdDecode(packed, z.unpackSize); break;
      default: return kUnsupportedMethod;
    }
  } catch (UnsupportedMethod &) { return kUnsupportedMethod; }
  catch (DataError &e) { if (std::string(e.what()).find("Unexpected end") != std::string::npos) return kUnexpectedEnd; return kDataError; }
  if (res.size() != z.unpackSize) return kDataError;
  out(res.data(), res.size());
  crcChecked = true;
  if (Crc32Calc(res.data(), res.size()) != z.crc) return (z.flags & 1) ? kWrongPassword : kCRCError;
  return kOK;
}

