    if (t.hasCTime) { it.ctime.defined = true; it.ctime.ft = UnixToFileTime(t.ctime); it.ctime.prec = 0; }
    UInt32 mode = t.mode & 07777;
    if (t.isDir) mode |= 0040000; else if (t.typeFlag == '2') mode |= 0120000; else if (t.typeFlag == '3') mode |= 0020000; else if (t.typeFlag == '4') mode |= 0060000; else if (t.typeFlag == '6') mode |= 0010000; else mode |= 0100000;
