    it.props.push_back({"Mode", PosixModeToString(mode)});
    it.props.push_back({"User", t.user});
    it.props.push_back({"Group", t.group});
    it.props.push_back({"User ID", Int64ToStr(t.uid)});
    it.props.push_back({"Group ID", Int64ToStr(t.gid)});
