}

std::vector<PropVal> TarArchive::ArchiveProps() const {
  std::vector<PropVal> r;
  r.push_back({"Physical Size", UInt64ToStr(physSize)});
  if (data.size() > physSize) r.push_back({"Tail Size", UInt64ToStr(data.size() - physSize)});
  r.push_back({"Headers Size", UInt64ToStr(headersSize)});
  r.push_back({"Code Page", "UTF-8"});
  std::string ch;
  if (isGnu) ch = "GNU"; else if (isPax) ch = "pax"; else if (isPosix) ch = "POSIX";
  bool ascii = true; for (const auto &t : titems) for (unsigned char c : t.name) if (c >= 0x80) ascii = false;
  if (ascii) { if (!ch.empty()) ch += " "; ch += "ASCII"; }
  r.push_back({"Characteristics", ch});
  return r;
}

ExtractResult TarArchive::ExtractItem(size_t index, const std::string &, std::function<void(const Byte *, size_t)> out, bool &crcChecked) {
  const TarItem &t = titems[index];
  crcChecked = false;
  if (t.isDir) return kOK;
  if (t.dataPos + t.size > data.size()) { if (t.dataPos < data.size()) out(data.data() + t.dataPos, data.size() - (size_t)t.dataPos); return kUnexpectedEnd; }
  out(data.data() + t.dataPos, (size_t)t.size);
  return kOK;
}

IArchive *OpenTar(const Buf &data, const std::string &path, const std::string &pw, bool &needPassword, std::string &err) {
  (void)pw; needPassword = false;
  bool hasSig = data.size() >= 262 && memcmp(data.data() + 257, "ustar", 5) == 0;
  TarArchive *a = new TarArchive();
  if (!a->Open(data, path, err, !hasSig)) { delete a; return nullptr; }
  return a;
}

static void PutOctal(Byte *p, size_t n, UInt64 v) {
  // n-1 digits + NUL (7-zip style: zero-padded)
  for (size_t i = n - 1; i != (size_t)-1; i--) { if (i == n - 1) { p[i] = 0; continue; } p[i] = (Byte)('0' + (v & 7)); v >>= 3; }
}
Buf TarMakeHeader(const std::string &name, UInt32 mode, UInt64 size, Int64 mtime, char typeFlag, const std::string &linkName, Int64 uid, Int64 gid, const std::string &uname, const std::string &gname) {
  Buf b(512, 0);
  Byte *h = b.data();
  memcpy(h, name.data(), std::min<size_t>(name.size(), 100));
  PutOctal(h + 100, 8, mode & 07777);
  PutOctal(h + 108, 8, (UInt64)uid);
  PutOctal(h + 116, 8, (UInt64)gid);
  if (size < ((UInt64)1 << 33)) PutOctal(h + 124, 12, size);
  else { h[124] = 0x80; for (int i = 0; i < 8; i++) h[128 + i] = (Byte)(size >> (8 * (7 - i))); }
  if (mtime >= 0 && mtime < ((Int64)1 << 33)) PutOctal(h + 136, 12, (UInt64)mtime);
  else { h[136] = (mtime < 0) ? 0xFF : 0x80; UInt64 u = (UInt64)mtime; for (int i = 0; i < 8; i++) h[140 + i] = (Byte)(u >> (8 * (7 - i))); if (mtime < 0) for (int i = 1; i < 4; i++) h[136 + i] = 0xFF; }
  h[156] = (Byte)typeFlag;
  memcpy(h + 157, linkName.data(), std::min<size_t>(linkName.size(), 100));
  memcpy(h + 257, "ustar  ", 8); // GNU magic "ustar  \0"
  memcpy(h + 265, uname.data(), std::min<size_t>(uname.size(), 32));
  memcpy(h + 297, gname.data(), std::min<size_t>(gname.size(), 32));
  // checksum
  memset(h + 148, ' ', 8);
  UInt32 sum = 0; for (int i = 0; i < 512; i++) sum += h[i];
  // 6 octal digits, NUL, space
  for (int i = 5; i >= 0; i--) { h[148 + i] = (Byte)('0' + (sum & 7)); sum >>= 3; }
  h[154] = 0; h[155] = ' ';
  return b;
}
