// ---------------- gzip ----------------
class GzipArchive : public IArchive {
public:
  Buf data; std::vector<ArcItem> items; UInt64 headerSize = 0; size_t dataStart = 0; bool hasName = false; std::vector<std::string> warnings;
  bool Open(const Buf &d, std::string &err) {
    data = d;
    if (data.size() < 18 || data[0] != 0x1F || data[1] != 0x8B) { err = "Is not archive"; return false; }
    if (data[2] != 8) { err = "Unsupported method"; return false; }
    Byte flg = data[3];
    UInt32 mtime = GetUi32(data.data() + 4);
    Byte os = data[9];
    size_t pos = 10;
    if (flg & 4) { if (pos + 2 > data.size()) { err = "Unexpected end of archive"; return false; } UInt32 xl = GetUi16(data.data() + pos); pos += 2 + xl; }
    std::string name;
    if (flg & 8) { size_t s = pos; while (pos < data.size() && data[pos] != 0) pos++; if (pos >= data.size()) { err = "Unexpected end of archive"; return false; } name.assign((const char*)data.data() + s, pos - s); pos++; hasName = true; }
    if (flg & 16) { while (pos < data.size() && data[pos] != 0) pos++; if (pos >= data.size()) { err = "Unexpected end of archive"; return false; } pos++; }
    if (flg & 2) pos += 2;
    if (pos > data.size()) { err = "Unexpected end of archive"; return false; }
    headerSize = pos; dataStart = pos;
    ArcItem it;
    it.path = name;
    it.hasSize = true; it.size = GetUi32(data.data() + data.size() - 4);
    it.hasPackSize = true; it.packSize = data.size();
    if (mtime != 0) { it.mtime.defined = true; it.mtime.ft = UnixToFileTime((Int64)mtime); it.mtime.prec = 0; }
    it.hasCRC = true; it.crc = GetUi32(data.data() + data.size() - 8);
    it.hasAttrib = false;
    it.props.push_back({"Path", name});
    it.props.push_back({"Size", UInt64ToStr(it.size)});
    it.props.push_back({"Packed Size", UInt64ToStr(it.packSize)});
    it.props.push_back({"Modified", it.mtime.defined ? FileTimeToString(it.mtime.ft, true, 0) : ""});
    { const char *hn = GzHostName(os); it.props.push_back({"Host OS", hn ? hn : UInt64ToStr(os)}); }
    it.props.push_back({"CRC", Hex8(it.crc)});
    items.push_back(it);
    return true;
  }
  std::string TypeName() const override { return "gzip"; }
  std::vector<PropVal> ArchiveProps() const override { std::vector<PropVal> r; r.push_back({"Headers Size", UInt64ToStr(headerSize)}); return r; }
  size_t NumItems() const override { return 1; }
  const ArcItem &Item(size_t i) const override { return items[i]; }
  UInt64 PhysSize() const override { return data.size(); }
  std::vector<std::string> Warnings() const override { return warnings; }
  ExtractResult ExtractItem(size_t, const std::string &, std::function<void(const Byte *, size_t)> out, bool &crcChecked) override {
    crcChecked = true;
    Buf all;
    size_t pos = dataStart;
    // decode members
    for (;;) {
      Buf in(data.begin() + pos, data.end());
      // decode with zlib raw, need consumed count: use inflate manually
      Buf res;
      size_t consumed = 0;
      try {
        extern bool InflateRawConsume(const Buf &in, Buf &out, size_t &consumed);
        if (!InflateRawConsume(in, res, consumed)) return kDataError;
      } catch (DataError &e) { out(all.data(), all.size()); if (std::string(e.what()).find("Unexpected") != std::string::npos) return kUnexpectedEnd; return kDataError; }
      pos += consumed;
      if (pos + 8 > data.size()) { all.insert(all.end(), res.begin(), res.end()); out(all.data(), all.size()); return kUnexpectedEnd; }
      UInt32 crc = GetUi32(data.data() + pos), isize = GetUi32(data.data() + pos + 4);
      pos += 8;
      if (Crc32Calc(res.data(), res.size()) != crc || (UInt32)res.size() != isize) { all.insert(all.end(), res.begin(), res.end()); out(all.data(), all.size()); return kCRCError; }
      all.insert(all.end(), res.begin(), res.end());
      // next member?
      if (pos + 10 <= data.size() && data[pos] == 0x1F && data[pos+1] == 0x8B && data[pos+2] == 8) {
        Byte flg = data[pos + 3]; size_t p = pos + 10;
        if (flg & 4) { UInt32 xl = GetUi16(data.data() + p); p += 2 + xl; }
        if (flg & 8) { while (p < data.size() && data[p]) p++; p++; }
        if (flg & 16) { while (p < data.size() && data[p]) p++; p++; }
        if (flg & 2) p += 2;
        if (p > data.size()) break;
        pos = p; continue;
      }
      break;
    }
    out(all.data(), all.size());
    return pos < data.size() ? kDataAfterEnd : kOK;
  }
};

#include <zlib.h>
bool InflateRawConsume(const Buf &in, Buf &out, size_t &consumed) {
  z_stream z; memset(&z, 0, sizeof(z));
  if (inflateInit2(&z, -15) != Z_OK) throw std::runtime_error("inflate init");
  out.clear(); out.resize(in.size() * 4 + 65536);
  z.next_in = const_cast<Byte*>(in.data()); z.avail_in = in.size();
  size_t outPos = 0;
  for (;;) {
    if (outPos == out.size()) out.resize(out.size() * 2);
    z.next_out = out.data() + outPos; z.avail_out = out.size() - outPos;
    int r = inflate(&z, Z_NO_FLUSH);
    outPos = out.size() - z.avail_out;
    if (r == Z_STREAM_END) break;
    if (r == Z_BUF_ERROR || (r == Z_OK && z.avail_in == 0 && z.avail_out != 0)) { inflateEnd(&z); out.resize(outPos); throw DataError("Unexpected end of data"); }
    if (r != Z_OK) { inflateEnd(&z); out.resize(outPos); throw DataError(); }
  }
  consumed = in.size() - z.avail_in;
  inflateEnd(&z);
  out.resize(outPos);
  return true;
}

