class LzmaArchive : public IArchive {
public:
  Buf data; std::vector<ArcItem> items; bool is86 = false; std::string method; bool sizeKnown = false; UInt64 unpackSize = 0;
  bool Open(const Buf &d, bool lzma86, std::string &err) {
    data = d; is86 = lzma86;
    size_t off = lzma86 ? 1 : 0;
    if (data.size() < 13 + off) { err = "Is not archive"; return false; }
    if (lzma86 && data[0] > 1) { err = "Is not archive"; return false; }
    const Byte *props = data.data() + off;
    if (props[0] >= 9 * 5 * 5) { err = "Is not archive"; return false; }
    UInt32 dict = GetUi32(props + 1);
    UInt64 us = GetUi64(props + 5);
    sizeKnown = us != (UInt64)-1; unpackSize = us;
    if (sizeKnown && us > ((UInt64)1 << 56)) { err = "Is not archive"; return false; }
    // dict sanity: 7-zip checks that dict is power-of-2-ish
    { unsigned d = props[0]; unsigned lc = d % 9; d /= 9; unsigned lp = d % 5; unsigned pb = d / 5; if (lc > 8 || lp > 4 || pb > 4) { err = "Is not archive"; return false; } }
    if (dict != 0 && dict < 4096 && !lzma86) { /* allowed */ }
    method = "LZMA:" + DictSizeToString(dict);
    if (lzma86) method = (data[0] ? "BCJ " : "") + method;
    ArcItem it; it.hasSize = sizeKnown; it.size = us; it.hasPackSize = false; it.method = method;
    it.props.push_back({"Size", sizeKnown ? UInt64ToStr(us) : ""}); it.props.push_back({"Packed Size", ""}); it.props.push_back({"Method", method});
    items.push_back(it);
