// ---------------- split ----------------
class SplitArchive : public IArchive {
public:
  Buf data; std::vector<ArcItem> items; std::vector<std::string> volumes; UInt64 totalSize = 0;
  bool Open(const Buf &d, const std::string &path, std::string &err) {
    data = d;
    std::string base = GetBaseName(path); std::string dir = GetDirPrefix(path);
    size_t dot = base.find_last_of('.');
    if (dot == std::string::npos || base.substr(dot + 1) != "001") { err = "Is not archive"; return false; }
    std::string stem = base.substr(0, dot);
    totalSize = 0;
    for (unsigned i = 1; ; i++) {
      char b[16]; snprintf(b, sizeof(b), ".%03u", i);
      std::string vp = dir + stem + b;
      struct stat st;
      if (stat(vp.c_str(), &st) != 0) break;
      volumes.push_back(vp); totalSize += (UInt64)st.st_size;
    }
    if (volumes.empty()) { err = "Is not archive"; return false; }
    ArcItem it; it.path = stem; it.hasSize = true; it.size = totalSize; it.hasPackSize = true; it.packSize = totalSize;
    it.props.push_back({"Path", stem}); it.props.push_back({"Size", UInt64ToStr(totalSize)});
    items.push_back(it);
    return true;
  }
  std::string TypeName() const override { return "Split"; }
  std::vector<PropVal> ArchiveProps() const override { std::vector<PropVal> r; r.push_back({"Physical Size", UInt64ToStr(totalSize)}); r.push_back({"Volumes", UInt64ToStr((UInt64)volumes.size())}); return r; }
  size_t NumItems() const override { return 1; }
  const ArcItem &Item(size_t i) const override { return items[i]; }
  UInt64 PhysSize() const override { return totalSize; }
  bool IsMultiVolume() const override { return true; }
  ExtractResult ExtractItem(size_t, const std::string &, std::function<void(const Byte *, size_t)> out, bool &crcChecked) override {
    crcChecked = false;
    for (const auto &v : volumes) { Buf b; int err; if (!ReadWholeFile(v, b, err)) return kDataError; out(b.data(), b.size()); }
    return kOK;
  }
};
IArchive *OpenSplit(const Buf &data, const std::string &path, const std::string &, bool &needPassword, std::string &err) {
  needPassword = false; SplitArchive *a = new SplitArchive(); if (!a->Open(data, path, err)) { delete a; return nullptr; } return a;
}
