int CommandExtract(const Options &o) {
  bool testMode = o.command == kTest;
  bool fullPaths = o.command == kExtractFull;
  ArcScanResult scan = ScanArchives(o, true);
  OutStream *so = g_Out;
  unsigned numTryArcs = 0, numOkArcs = 0, numCantOpen = 0, numArcsWithError = 0, numArcsWithWarnings = 0, numOpenArcWarnings = 0, numFileErrors = 0;
  ExtractStat stat;
  int overwriteMode = o.overwriteMode; // -1 ask, 0 overwrite, 1 skip, 2 rename existing, 3 rename extracted
  std::string password = o.password;
  bool passwordAsked = o.passwordEnabled;

  for (const std::string &arcPath : scan.paths) {
    numTryArcs++;
    if (so) *so << endl << (testMode ? "Testing archive: " : "Extracting archive: ") << arcPath << endl;
    if (so) so->Flush();
    OpenedArc oa;
    OpenArcFile(o, arcPath, oa, false);
    if (!oa.openOk) {
      if (g_Err) {
        *g_Err << "ERROR: " << arcPath << endl;
        if (oa.sysErr) *g_Err << ErrnoMessage(oa.sysErr) << endl;
        else PrintOpenArchiveError(*g_Err, oa);
      }
      numCantOpen++;
      continue;
    }
    IArchive &arc = *oa.arc;
    std::vector<std::string> warns = arc.Warnings();
    if (!warns.empty() && so) { *so << endl << "WARNINGS:" << endl; for (auto &w : warns) *so << w << endl; *so << endl; }
    if (so) PrintArcProps(*so, oa);
    if (!warns.empty()) { numArcsWithWarnings++; numOpenArcWarnings += warns.size(); }
    unsigned fileErrorsInArc = 0;
    stat.packSize += oa.data.size();
    // selection
    std::vector<size_t> selected;
    for (size_t i = 0; i < arc.NumItems(); i++) {
      const ArcItem &it = arc.Item(i);
      std::string name = GetItemDisplayName(it, arcPath, oa.format);
      if (!o.censor.includeItems.empty() || !o.censor.excludeItems.empty()) { if (!o.censor.CheckPath(name, !it.isDir)) continue; }
      selected.push_back(i);
    }
    // password prompt if needed
    if (!testMode || true) {
      bool needPw = false;
      for (size_t i : selected) if (arc.Item(i).encrypted) needPw = true;
      if (needPw && !passwordAsked) {
        if (so) { *so << endl << "Enter password:" << endl; so->Flush(); }
        if (!g_StdOut.enabled) {}
        password = ReadLineFromStdin();
        passwordAsked = true;
      }
    }
    std::vector<std::pair<std::string, ArcTime>> dirTimes;
    std::string outDir = o.outputDirSet ? o.outputDir : "";
    for (size_t idx : selected) {
      const ArcItem &it = arc.Item(idx);
      std::string name = GetItemDisplayName(it, arcPath, oa.format);
      std::string relPath = fullPaths ? SanitizePath(name) : GetBaseName(SanitizePath(name));
      if (relPath.empty()) relPath = GetItemDisplayName(it, arcPath, oa.format);
      std::string fullPath = outDir + relPath;
      if (o.logLevel >= 1 && so) { *so << (testMode ? "T " : "- ") << name; if (it.isDir) *so << "/"; *so << endl; }
      if (it.isDir) {
        stat.numDirs++;
        if (!testMode && !o.stdOutMode) { CreateDirs(fullPath); dirTimes.push_back({fullPath, it.mtime}); }
        continue;
      }
      stat.numFiles++;
      // determine target
      bool skip = false;
      std::string target = fullPath;
      if (!testMode && !o.stdOutMode) {
        if (!CreateDirs(GetDirPrefix(fullPath))) {}
        struct stat st;
        if (lstat(target.c_str(), &st) == 0) {
          if (S_ISDIR(st.st_mode)) {
            if (g_Err) *g_Err << "ERROR: Can not open output file : " << ErrnoMessage(EISDIR) << " : " << target << endl;
            fileErrorsInArc++; stat.unpackSize += it.size; continue;
          }
          int mode = overwriteMode;
          if (mode == -1) {
            for (;;) {
              if (so) {
                *so << endl << "Would you like to replace the existing file:" << endl;
                *so << "  Path:     " << target << endl;
                *so << "  Size:     " << SizeToString_Smart((UInt64)st.st_size) << endl;
                *so << "  Modified: " << FileTimeToString(UnixToFileTime(st.st_mtim.tv_sec, (UInt32)st.st_mtim.tv_nsec), true, 0) << endl;
                *so << "with the file from archive:" << endl;
                *so << "  Path:     " << name << endl;
                *so << "  Size:     " << (it.hasSize ? SizeToString_Smart(it.size) : std::string("")) << endl;
                *so << "  Modified: " << (it.mtime.defined ? FileTimeToString(it.mtime.ft, true, 0) : std::string("")) << endl;
                *so << "? (Y)es / (N)o / (A)lways / (S)kip all / A(u)to rename all / (Q)uit? ";
                so->Flush();
              }
              std::string ans = ReadLineFromStdin();
              std::string a = ToLower(Trim(ans));
              if (a == "y") { mode = 0; break; }
              if (a == "n") { mode = 1; break; }
              if (a == "a") { mode = 0; overwriteMode = 0; break; }
              if (a == "s") { mode = 1; overwriteMode = 1; break; }
              if (a == "u") { mode = 3; overwriteMode = 3; break; }
              if (a == "q") throw BreakException();
            }
          }
          if (mode == 1) skip = true;
          else if (mode == 2) { std::string nn = MakeRenamed(target); rename(target.c_str(), nn.c_str()); }
          else if (mode == 3) { target = MakeRenamed(target); }
          else { unlink(target.c_str()); }
        }
      }
      if (skip) { stat.unpackSize += it.size; continue; }
      // extract
      int fd = -1;
      bool isLink = it.hasPosixMode && ((it.posixMode & 0170000) == 0120000);
      Buf linkData;
      UInt64 written = 0;
      if (!testMode && !o.stdOutMode && !isLink) {
        fd = open(target.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0666);
        if (fd < 0) {
          int e = errno;
          if (g_Err) *g_Err << "ERROR: Can not open output file : " << ErrnoMessage(e) << " : " << target << endl;
          fileErrorsInArc++; stat.unpackSize += it.size; continue;
        }
      }
      bool crcChecked = false;
      ExtractResult res;
      try {
        res = arc.ExtractItem(idx, password, [&](const Byte *p, size_t n) {
          written += n;
          if (fd >= 0) { size_t off = 0; while (off < n) { ssize_t w = write(fd, p + off, n - off); if (w <= 0) throw SystemException(errno); off += (size_t)w; } }
          else if (o.stdOutMode && !testMode) { fwrite(p, 1, n, stdout); }
          else if (isLink) linkData.insert(linkData.end(), p, p + n);
        }, crcChecked);
      } catch (SystemException &) { if (fd >= 0) close(fd); throw; }
      catch (std::bad_alloc &) { res = kDataError; }
      catch (...) { res = kDataError; }
      if (fd >= 0) { close(fd); }
      if (isLink && !testMode && !o.stdOutMode) {
        std::string tgt((const char*)linkData.data(), linkData.size());
        unlink(target.c_str());
        if (symlink(tgt.c_str(), target.c_str()) != 0) { if (g_Err) *g_Err << "ERROR: Can not create symbolic link : " << ErrnoMessage(errno) << " : " << target << endl; fileErrorsInArc++; }
      }
      stat.unpackSize += it.hasSize ? it.size : written;
      if (res != kOK) {
        std::string msg = ExtractResultMessage(res);
        if (it.encrypted) {
          if (res == kDataError || res == kWrongPassword) msg = "Data Error in encrypted file. Wrong password?";
          else if (res == kCRCError) msg = "CRC Failed in encrypted file. Wrong password?";
        } else if (res == kWrongPassword) msg = "Wrong password";
        if (g_Err) *g_Err << "ERROR: " << msg << " : " << name << endl;
        fileErrorsInArc++;
      } else if (fd >= 0 || isLink) {
        if (it.hasPosixMode && !isLink) chmod(target.c_str(), it.posixMode & 07777);
        else if (it.hasAttrib && !it.hasPosixMode && !isLink && (it.attrib & FILE_ATTRIBUTE_READONLY_)) chmod(target.c_str(), 0444);
        if (!isLink) SetFileTimes(target, it.mtime, false);
      }
      if (o.stdOutMode && !testMode) fflush(stdout);
    }
    // set dir times (deepest first)
    for (size_t k = dirTimes.size(); k != 0;) { k--; SetFileTimes(dirTimes[k].first, dirTimes[k].second, true); }
    if (so) {
      if (fileErrorsInArc == 0) *so << "Everything is Ok" << endl;
      else *so << endl << "Sub items Errors: " << fileErrorsInArc << endl;
    }
    if (fileErrorsInArc) { numArcsWithError++; numFileErrors += fileErrorsInArc; } else numOkArcs++;
  }
  if (so) {
    *so << endl;
    if (numTryArcs > 1) { *so << "Archives: " << numTryArcs << endl; *so << "OK archives: " << numOkArcs << endl; }
    if (numCantOpen != 0) *so << "Can't open as archive: " << numCantOpen << endl;
    if (numArcsWithError != 0) *so << "Archives with Errors: " << numArcsWithError << endl;
    if (numArcsWithWarnings != 0) *so << "Archives with Warnings: " << numArcsWithWarnings << endl;
    if (numOpenArcWarnings != 0) { *so << endl << "Warnings: " << numOpenArcWarnings << endl; }
    if (numFileErrors != 0) { *so << endl << "Sub items Errors: " << numFileErrors << endl; }
  }
  if (numArcsWithError != 0 || numFileErrors != 0) { if (so) so->Flush(); return 2; }
  if (so) {
    if (stat.numDirs != 0) *so << "Folders: " << stat.numDirs << endl;
    if (stat.numFiles != 1 || stat.numDirs != 0) *so << "Files: " << stat.numFiles << endl;
    *so << "Size:       " << stat.unpackSize << endl;
    *so << "Compressed: " << stat.packSize << endl;
  }
  if (numCantOpen != 0) return 2;
  return 0;
}
