// ---------------- settings parsing ----------------
static bool ParseSizeValue(const std::string &s0, UInt64 &v) {
  std::string s = s0; UInt64 n; size_t end;
  if (!ParseUInt64(s, n, &end)) return false;
  std::string suf = ToLower(s.substr(end));
  if (suf.empty()) { v = n; return true; }
  if (suf == "b") { v = n; return true; }
  if (suf == "k") { v = n << 10; return true; }
  if (suf == "m") { v = n << 20; return true; }
  if (suf == "g") { v = n << 30; return true; }
  return false;
}
static bool ParseDictValue(const std::string &s0, UInt32 &v) {
  // number without suffix = log2
  std::string s = s0; UInt64 n; size_t end;
  if (!ParseUInt64(s, n, &end)) return false;
  std::string suf = ToLower(s.substr(end));
  if (suf.empty()) { if (n > 31) return false; v = (UInt32)1 << n; return true; }
  if (suf == "b") { v = (UInt32)n; return true; }
  if (suf == "k") { v = (UInt32)(n << 10); return true; }
  if (suf == "m") { v = (UInt32)(n << 20); return true; }
  if (suf == "g") { v = (UInt32)(n << 30); return true; }
  return false;
}
static bool ParseBool(const std::string &s, bool &v) {
  std::string l = ToLower(s);
  if (l.empty() || l == "on" || l == "+" || l == "1" || l == "yes") { v = true; return true; }
  if (l == "off" || l == "-" || l == "0" || l == "no") { v = false; return true; }
  return false;
}

static void Invalid() { throw SystemException((int)E_INVALIDARG_, false); }

void CompressSettings::Parse(const std::vector<Property> &props, const std::string &arcType) {
  for (const Property &p : props) {
    std::string name = ToLower(p.name);
    std::string val = p.value;
    if (name.empty()) Invalid();
    // -mx5 style: name contains digits at end
    if (name[0] == 'x' && !p.hasValue) {
      std::string num = name.substr(1);
      if (num.empty()) { level = 9; continue; }
      UInt64 v; size_t e; if (!ParseUInt64(num, v, &e) || e != num.size()) Invalid();
      level = (int)std::min<UInt64>(v, 9); continue;
    }
    if (name == "x") { if (!p.hasValue) { level = 9; continue; } UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); level = (int)std::min<UInt64>(v, 9); continue; }
    // numbered methods
    if (name[0] >= '0' && name[0] <= '9') {
      UInt64 idx; size_t e; if (!ParseUInt64(name, idx, &e) || e != name.size()) Invalid();
      if (!p.hasValue) Invalid();
      MethodSpec ms;
      std::vector<std::string> parts = SplitString(val, ':');
      ms.name = parts[0];
      if (!MethodNameToId(ms.name, ms.id)) Invalid();
      for (size_t i = 1; i < parts.size(); i++) {
        size_t eq = parts[i].find('=');
        if (eq == std::string::npos) ms.params.push_back({ToLower(parts[i]), ""});
        else ms.params.push_back({ToLower(parts[i].substr(0, eq)), parts[i].substr(eq + 1)});
      }
      if (methods.size() <= idx) methods.resize(idx + 1);
      methods[idx] = ms;
      continue;
    }
    if (name == "mt") { if (!p.hasValue || val.empty()) { numThreads = GetNumCpus(); continue; } bool b; if (ParseBool(val, b)) { numThreads = b ? GetNumCpus() : 1; continue; } UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); numThreads = (unsigned)v; continue; }
    if (name.size() > 2 && name.substr(0, 2) == "mt" && !p.hasValue) { std::string num = name.substr(2); UInt64 v; size_t e; if (!ParseUInt64(num, v, &e) || e != num.size()) Invalid(); numThreads = (unsigned)v; continue; }
    if (name == "s") {
      solidSet = true;
      if (!p.hasValue || val.empty()) { solid = true; continue; }
      bool b; if (ParseBool(val, b)) { solid = b; continue; }
      // s=e, s=100f10m
      std::string l = ToLower(val); size_t i = 0;
      if (i < l.size() && l[i] == 'e') { solidPerExt = true; i++; }
      while (i < l.size()) {
        UInt64 n; size_t e; if (!ParseUInt64(l.substr(i), n, &e)) Invalid();
        i += e; if (i >= l.size()) Invalid();
        char c = l[i++];
        if (c == 'f') solidFiles = n; else if (c == 'b') solidBytes = n; else if (c == 'k') solidBytes = n << 10; else if (c == 'm') solidBytes = n << 20; else if (c == 'g') solidBytes = n << 30; else Invalid();
      }
      solid = true; continue;
    }
    if (name == "hc") { bool b; if (!ParseBool(val, b)) Invalid(); compressHeaders = b; continue; }
    if (name == "he") { bool b; if (!ParseBool(val, b)) Invalid(); encryptHeaders = b; continue; }
    if (name == "hcf") { continue; }
    if (name == "f") { bool b; if (!p.hasValue || ParseBool(val, b)) { filterOn = p.hasValue ? b : true; continue; } filterName = val; filterOn = true; continue; }
    if (name == "d") { if (!ParseDictValue(val, dictSize)) Invalid(); continue; }
    if (name == "fb") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); fb = (int)v; continue; }
    if (name == "mc") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); mc = (int)v; continue; }
    if (name == "lc") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); lc = (int)v; continue; }
    if (name == "lp") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); lp = (int)v; continue; }
    if (name == "pb") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); pb = (int)v; continue; }
    if (name == "a") { UInt64 v; size_t e; if (!ParseUInt64(val, v, &e) || e != val.size()) Invalid(); algo = (int)v; continue; }
    if (name == "mf") { mf = ToLower(val); continue; }
    if (name == "qs") { bool b; if (!ParseBool(val, b)) Invalid(); sortByType = b; continue; }
    if (name == "tc") { bool b; if (!ParseBool(val, b)) Invalid(); storeCTime = b; tmFlagsSet = true; continue; }
    if (name == "ta") { bool b; if (!ParseBool(val, b)) Invalid(); storeATime = b; tmFlagsSet = true; continue; }
    if (name == "tm") { bool b; if (!ParseBool(val, b)) Invalid(); storeMTime = b; tmFlagsSet = true; continue; }
    if (name == "tr" || name == "memuse" || name == "cu" || name == "cl" || name == "cp" || name == "em" || name == "pass" || name == "mem" || name == "o" || name == "tp" || name == "tz" || name == "ms") { raw[name] = val; continue; }
    // unknown
    Invalid();
  }
  (void)arcType;
}
bool CompressSettings::IsCopy() const {
  if (level == 0 && methods.empty()) return true;
  if (!methods.empty() && methods[0].id == k_Copy) return true;
  return false;
}

// ---------------- OutFile ----------------
bool OutFile::Open(const std::string &path, bool stdoutMode, int &err) {
  toStdout = stdoutMode; finalPath = path; written = 0;
  if (stdoutMode) { fd = 1; return true; }
  tmpPath = path + ".tmp";
  fd = open(tmpPath.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0666);
  if (fd < 0) { err = errno; return false; }
  return true;
}
void OutFile::Write(const Byte *p, size_t n) {
  size_t off = 0;
  while (off < n) { ssize_t w = write(fd, p + off, n - off); if (w < 0) { if (errno == EINTR) continue; throw SystemException(errno); } off += (size_t)w; }
  written += n;
}
bool OutFile::Close(bool commit, int &err) {
  if (toStdout) { fflush(stdout); return true; }
  if (fd >= 0) close(fd); fd = -1;
  if (!commit) { unlink(tmpPath.c_str()); return true; }
  if (rename(tmpPath.c_str(), finalPath.c_str()) != 0) { err = errno; unlink(tmpPath.c_str()); return false; }
  return true;
}

