static UInt64 DetectExeFilter(const std::string &phyPath) {
  // returns filter method id (k_BCJ etc.) or 0
  int fd = open(phyPath.c_str(), O_RDONLY);
  if (fd < 0) return 0;
  Byte buf[1 << 12]; ssize_t n = read(fd, buf, sizeof(buf)); close(fd);
  if (n < 64) return 0;
  if (memcmp(buf, "\x7FELF", 4) == 0) {
    bool is64 = buf[4] == 2; bool le = buf[5] == 1;
    if ((buf[4] != 1 && buf[4] != 2) || (buf[5] != 1 && buf[5] != 2)) return 0;
    UInt32 machine = le ? GetUi16(buf + 18) : ((buf[18] << 8) | buf[19]);
    UInt32 etype = le ? GetUi16(buf + 16) : ((buf[16] << 8) | buf[17]);
    if (etype == 0 || etype > 4) return 0;
    unsigned ehsize = le ? GetUi16(buf + (is64 ? 52 : 40)) : ((buf[(is64 ? 52 : 40)] << 8) | buf[(is64 ? 52 : 40) + 1]);
    if (ehsize != (is64 ? 64u : 52u)) return 0;
    switch (machine) {
      case 3: case 62: return k_BCJ;
      case 183: return k_ARM64;
      case 40: return k_ARMT;
      case 20: case 21: return le ? 0 : k_PPC;
      case 2: case 18: case 43: return k_SPARC;
      case 50: return k_IA64;
      case 243: return k_RISCV;
    }
    return 0;
  }
  if (buf[0] == 'M' && buf[1] == 'Z') {
    UInt32 peOff = GetUi32(buf + 60);
    if (peOff + 24 > (UInt32)n || peOff < 64) return 0;
    if (memcmp(buf + peOff, "PE\0\0", 4) != 0) return 0;
    UInt32 machine = GetUi16(buf + peOff + 4);
    UInt32 optSize = GetUi16(buf + peOff + 20);
    if (optSize < 96) return 0;
    switch (machine) { case 0x14c: case 0x8664: return k_BCJ; case 0xAA64: return k_ARM64; case 0x1c0: case 0x1c4: return k_ARMT; case 0x200: return k_IA64; }
    return 0;
  }
  if ((GetUi32(buf) == 0xFEEDFACE || GetUi32(buf) == 0xFEEDFACF) ) {
    UInt32 cpu = GetUi32(buf + 4);
    if (cpu == 7 || cpu == 0x01000007) return k_BCJ;
    if (cpu == 0x0100000C) return k_ARM64;
    if (cpu == 12) return k_ARMT;
    if (cpu == 18 || cpu == 0x01000012) return k_PPC;
  }
  return 0;
}

static bool IsExeExt(const std::string &name) {
  std::string base = GetBaseName(name); size_t dot = base.find_last_of('.');
  if (dot == std::string::npos) return false;
  std::string ext = ToLower(base.substr(dot + 1));
  return ext == "exe" || ext == "dll" || ext == "ocx" || ext == "sfx" || ext == "sys";
}

// ---------------- 7z creation ----------------
struct FolderEncodeResult { SzFolder folder; std::vector<Buf> packStreams; };

static UInt32 LevelDict(int level) {
  return (level <= 3 ? ((UInt32)1 << (level * 2 + 16)) : (level <= 6 ? ((UInt32)1 << (level + 20)) : (level <= 7 ? ((UInt32)1 << 27) : ((UInt32)1 << 28))));
}

struct SzEncoderChain {
  std::vector<MethodSpec> methods; // encode order (first applied first)
  bool encrypt = false; std::string password;
};

static void ApplyLzmaParams(LzmaProps &lp, const CompressSettings &cs, const MethodSpec &ms) {
  lp.level = cs.level;
  if (cs.dictSize) lp.dictSize = cs.dictSize;
  if (cs.fb) lp.fb = cs.fb; if (cs.mc) lp.mc = cs.mc; if (cs.lc >= 0) lp.lc = cs.lc; if (cs.lp >= 0) lp.lp = cs.lp; if (cs.pb >= 0) lp.pb = cs.pb; if (cs.algo >= 0) lp.algo = cs.algo; if (!cs.mf.empty()) lp.mf = cs.mf;
  for (auto &pr : ms.params) {
    const std::string &k = pr.first, &v = pr.second;
    if (k == "d") { UInt32 d; if (!ParseDictValue(v, d)) Invalid(); lp.dictSize = d; }
    else if (k == "fb") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.fb = (int)n; }
    else if (k == "mc") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.mc = (int)n; }
    else if (k == "lc") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.lc = (int)n; }
    else if (k == "lp") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.lp = (int)n; }
    else if (k == "pb") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.pb = (int)n; }
    else if (k == "a") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.algo = (int)n; }
    else if (k == "mf") lp.mf = ToLower(v);
    else if (k == "x") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.level = (int)n; }
    else if (k == "mt") {}
    else Invalid();
  }
}

static UInt64 Lzma2BlockSize(UInt32 dictSize) {
  const UInt64 kMinSize = (UInt64)1 << 20, kMaxSize = (UInt64)1 << 28;
  UInt64 blockSize = (UInt64)dictSize << 2;
  if (blockSize < kMinSize) blockSize = kMinSize;
  if (blockSize > kMaxSize) blockSize = kMaxSize;
  if (blockSize < dictSize) blockSize = dictSize;
  blockSize += kMinSize - 1; blockSize &= ~(kMinSize - 1);
  return blockSize;
}

// Encode data with chain -> folder (storage order: last encoder first)
static FolderEncodeResult EncodeFolder(const Buf &data, const SzEncoderChain &chain, const CompressSettings &cs, UInt64 reduceSize) {
  FolderEncodeResult r;
  Buf cur = data;
  std::vector<SzCoder> coders;       // in encode order
  std::vector<UInt64> outSizes;      // output size of each encoder (= input size of coder in storage)
  std::vector<UInt64> inSizes;
  for (const MethodSpec &ms : chain.methods) {
    SzCoder c; c.id = ms.id;
    UInt64 inSize = cur.size();
    Buf out;
    switch (ms.id) {
      case k_Copy: out = cur; break;
      case k_LZMA2: {
        LzmaProps lp; ApplyLzmaParams(lp, cs, ms); lp.reduceSize = reduceSize; lp.Normalize();
        unsigned nt = cs.numThreads ? cs.numThreads : GetNumCpus();
        unsigned blockThreads = nt >= 2 ? nt / (lp.algo == 0 ? 1 : 2) : 1;
        if (blockThreads < 1) blockThreads = 1;
        Byte prop; out = Lzma2Encode(cur, lp, prop, Lzma2BlockSize(lp.GetDictSizeReduced()), blockThreads);
        c.props.push_back(prop);
        break;
      }
      case k_LZMA: {
        LzmaProps lp; ApplyLzmaParams(lp, cs, ms); lp.reduceSize = reduceSize; lp.Normalize();
        Byte props[5]; out = LzmaEncode(cur, lp, props); c.props.assign(props, props + 5);
        break;
      }
      case k_Deflate: { int lvl = cs.level; for (auto &pr : ms.params) if (pr.first == "x") lvl = atoi(pr.second.c_str()); out = DeflateEncode(cur, lvl); break; }
      case k_BZip2: { int lvl = cs.level; for (auto &pr : ms.params) if (pr.first == "x") lvl = atoi(pr.second.c_str()); out = BZip2Encode(cur, lvl); break; }
      case k_BCJ: case k_ARM: case k_ARMT: case k_PPC: case k_SPARC: out = BranchEncode(ms.id, cur); break;
      case k_Delta: { unsigned d = 1; for (auto &pr : ms.params) if (pr.first == "" || pr.first == "d") { UInt64 n; if (ParseUInt64(pr.second.empty() ? pr.first : pr.second, n)) d = (unsigned)n; } if (!ms.params.empty() && ms.params[0].second.empty() && !ms.params[0].first.empty()) { UInt64 n; if (ParseUInt64(ms.params[0].first, n)) d = (unsigned)n; } if (d < 1 || d > 256) Invalid(); out = DeltaEncode(cur, d); c.props.push_back((Byte)(d - 1)); break; }
      case k_Swap2: out = ::Swap2(cur); break;
      case k_Swap4: out = ::Swap4(cur); break;
      default: throw UnsupportedMethod();
    }
    coders.push_back(c); inSizes.push_back(inSize); outSizes.push_back(out.size());
    cur = std::move(out);
  }
  if (chain.encrypt) {
    SzCoder c; c.id = k_AES; UInt64 inSize = cur.size();
    Buf out = Aes7zEncode(cur, chain.password, c.props);
    coders.push_back(c); inSizes.push_back(inSize); outSizes.push_back(out.size());
    cur = std::move(out);
  }
  // storage order: reverse
  size_t n = coders.size();
  for (size_t i = n; i != 0;) { i--; r.folder.coders.push_back(coders[i]); r.folder.unpackSizes.push_back(inSizes[i]); }
  for (UInt32 i = 1; i < n; i++) r.folder.bindPairs.push_back({i, i - 1});
  r.folder.packStreams = {0};
  r.packStreams.push_back(cur);
  return r;
}

