static std::string ArcTypeFromName(const std::string &path) {
  const FormatInfo *f = FindFormatByExt(path);
  if (f && f->canUpdate) return f->name;
  return "7z";
}

static int CompareUpdateNames(const std::string &a, const std::string &b) { return CompareFileNames(a, b); }

int CommandUpdate(const Options &o) {
  CompressSettings cs;
  // archive path
  std::string arcPath = o.archiveName;
  bool stdOutMode = o.stdOutMode;
  bool arcExists = false; struct stat arcSt;
  if (!stdOutMode && stat(arcPath.c_str(), &arcSt) == 0) { if (S_ISDIR(arcSt.st_mode)) throw MessageException("The file is a directory"); arcExists = true; }
  std::string arcType;
  if (o.arcTypeSet) {
    std::string t = o.arcType; size_t c = t.find(':'); if (c != std::string::npos) t = t.substr(0, c);
    const FormatInfo *f = FindFormatByName(t);
    if (!f) throw MessageException("Unsupported archive type");
    if (!f->canUpdate) throw MessageException("Unsupported archive type");
    arcType = f->name;
  }
  // Open existing
  OpenedArc oa; bool opened = false;
  if (arcExists) {
    if (g_Out) { *g_Out << "Open archive: " << arcPath << endl; g_Out->Flush(); }
    OpenArcFile(o, arcPath, oa, false);
    if (!oa.openOk) {
      if (oa.sysErr) throw SystemException(oa.sysErr);
      // 7-Zip: cannot update non-archive
      if (g_Err) { *g_Err << endl << "ERROR: " << arcPath << " : "; PrintOpenArchiveError(*g_Err, oa); *g_Err << endl; }
      throw MessageException("Can not open the file as archive");
    }
    opened = true;
    if (arcType.empty()) arcType = oa.format->name;
    else if (!StrEqNoCase(arcType, oa.format->name)) throw MessageException("Archive type mismatch");
    if (!oa.format->canUpdate) throw MessageException("Can not update archive of this type");
    if (g_Out) PrintArcProps(*g_Out, oa);
  }
  if (arcType.empty()) arcType = ArcTypeFromName(arcPath);
  cs.Parse(o.properties, arcType);
  if (o.sfxMode) throw MessageException("SFX is not supported");
  if (!o.volumeSizes.empty()) throw MessageException("Volumes are not supported");

  // Scan
  DirItems dirItems;
  bool stdInMode = o.stdInMode;
  if (!stdInMode) {
    if (g_Out) { *g_Out << "Scanning the drive:" << endl; g_Out->Flush(); }
    std::string excl;
    if (!stdOutMode) {
      // absolute compare: exclude archive file by physical path
      excl = arcPath;
    }
    EnumerateItems(o.censor, dirItems, !o.symLinks, excl);
    // also exclude the tmp file path & archive by comparing inode
    for (const auto &e : dirItems.errors) PrintScanWarningsImmediate(e.path, e.err);
    if (g_Out) *g_Out << FilesFoldersString(dirItems.numDirs, dirItems.numFiles, true, dirItems.totalSize) << endl << endl;
  }

  // Build update items
  std::vector<UpdateItem> items;
  std::vector<bool> arcUsed;
  IArchive *oldArc = opened ? oa.arc.get() : nullptr;
  if (oldArc) arcUsed.assign(oldArc->NumItems(), false);
  // sort dir items by name
  std::vector<size_t> dirOrder(dirItems.items.size());
  for (size_t i = 0; i < dirOrder.size(); i++) dirOrder[i] = i;
  std::stable_sort(dirOrder.begin(), dirOrder.end(), [&](size_t a, size_t b) { return CompareUpdateNames(dirItems.items[a].logPath, dirItems.items[b].logPath) < 0; });
  // Action table
  bool isDelete = o.command == kDelete, isRename = o.command == kRename, isUpdateCmd = o.command == kUpdate;
