static UInt64 DetectExeFilter(const std::string &phyPath) {
  // returns filter method id (k_BCJ etc.) or 0
  int fd = open(phyPath.c_str(), O_RDONLY);
  if (fd < 0) return 0;
  Byte buf[1 << 12]; ssize_t n = read(fd, buf, sizeof(buf)); close(fd);
  if (n < 64) return 0;
  if (memcmp(buf, "\x7FELF", 4) == 0) {
    bool is64 = buf[4] == 2; bool le = buf[5] == 1;
    if ((buf[4] != 1 && buf[4] != 2) || (buf[5] != 1 && buf[5] != 2)) return 0;
    UInt32 machine = le ? GetUi16(buf + 18) : ((buf[18] << 8) | buf[19]);
    UInt32 etype = le ? GetUi16(buf + 16) : ((buf[16] << 8) | buf[17]);
    if (etype == 0 || etype > 4) return 0;
    unsigned ehsize = le ? GetUi16(buf + (is64 ? 52 : 40)) : ((buf[(is64 ? 52 : 40)] << 8) | buf[(is64 ? 52 : 40) + 1]);
    if (ehsize != (is64 ? 64u : 52u)) return 0;
    switch (machine) {
      case 3: case 62: return k_BCJ;
      case 183: return k_ARM64;
      case 40: return k_ARMT;
      case 20: case 21: return le ? 0 : k_PPC;
      case 2: case 18: case 43: return k_SPARC;
      case 50: return k_IA64;
      case 243: return k_RISCV;
    }
    return 0;
  }
  if (buf[0] == 'M' && buf[1] == 'Z') {
    UInt32 peOff = GetUi32(buf + 60);
    if (peOff + 24 > (UInt32)n || peOff < 64) return 0;
    if (memcmp(buf + peOff, "PE\0\0", 4) != 0) return 0;
    UInt32 machine = GetUi16(buf + peOff + 4);
    UInt32 optSize = GetUi16(buf + peOff + 20);
    if (optSize < 96) return 0;
    switch (machine) { case 0x14c: case 0x8664: return k_BCJ; case 0xAA64: return k_ARM64; case 0x1c0: case 0x1c4: return k_ARMT; case 0x200: return k_IA64; }
    return 0;
  }
  if ((GetUi32(buf) == 0xFEEDFACE || GetUi32(buf) == 0xFEEDFACF) ) {
    UInt32 cpu = GetUi32(buf + 4);
    if (cpu == 7 || cpu == 0x01000007) return k_BCJ;
    if (cpu == 0x0100000C) return k_ARM64;
    if (cpu == 12) return k_ARMT;
    if (cpu == 18 || cpu == 0x01000012) return k_PPC;
  }
  return 0;
}

static bool IsExeExt(const std::string &name) {
  std::string base = GetBaseName(name); size_t dot = base.find_last_of('.');
  if (dot == std::string::npos) return false;
  std::string ext = ToLower(base.substr(dot + 1));
  return ext == "exe" || ext == "dll" || ext == "ocx" || ext == "sfx" || ext == "sys";
}

// ---------------- 7z creation ----------------
struct FolderEncodeResult { SzFolder folder; std::vector<Buf> packStreams; };

static UInt32 LevelDict(int level) {
  return (level <= 3 ? ((UInt32)1 << (level * 2 + 16)) : (level <= 6 ? ((UInt32)1 << (level + 20)) : (level <= 7 ? ((UInt32)1 << 27) : ((UInt32)1 << 28))));
}

struct SzEncoderChain {
  std::vector<MethodSpec> methods; // encode order (first applied first)
  bool encrypt = false; std::string password;
};

static void ApplyLzmaParams(LzmaProps &lp, const CompressSettings &cs, const MethodSpec &ms) {
  lp.level = cs.level;
  if (cs.dictSize) lp.dictSize = cs.dictSize;
  if (cs.fb) lp.fb = cs.fb; if (cs.mc) lp.mc = cs.mc; if (cs.lc >= 0) lp.lc = cs.lc; if (cs.lp >= 0) lp.lp = cs.lp; if (cs.pb >= 0) lp.pb = cs.pb; if (cs.algo >= 0) lp.algo = cs.algo; if (!cs.mf.empty()) lp.mf = cs.mf;
  for (auto &pr : ms.params) {
    const std::string &k = pr.first, &v = pr.second;
    if (k == "d") { UInt32 d; if (!ParseDictValue(v, d)) Invalid(); lp.dictSize = d; }
    else if (k == "fb") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.fb = (int)n; }
    else if (k == "mc") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.mc = (int)n; }
    else if (k == "lc") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.lc = (int)n; }
    else if (k == "lp") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.lp = (int)n; }
    else if (k == "pb") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.pb = (int)n; }
    else if (k == "a") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.algo = (int)n; }
    else if (k == "mf") lp.mf = ToLower(v);
    else if (k == "x") { UInt64 n; if (!ParseUInt64(v, n)) Invalid(); lp.level = (int)n; }
    else if (k == "mt") {}
    else Invalid();
  }
}

static UInt64 Lzma2BlockSize(UInt32 dictSize) {
  const UInt64 kMinSize = (UInt64)1 << 20, kMaxSize = (UInt64)1 << 28;
  UInt64 blockSize = (UInt64)dictSize << 2;
  if (blockSize < kMinSize) blockSize = kMinSize;
  if (blockSize > kMaxSize) blockSize = kMaxSize;
  if (blockSize < dictSize) blockSize = dictSize;
  blockSize += kMinSize - 1; blockSize &= ~(kMinSize - 1);
  return blockSize;
}

// Encode data with chain -> folder (storage order: last encoder first)
static FolderEncodeResult EncodeFolder(const Buf &data, const SzEncoderChain &chain, const CompressSettings &cs, UInt64 reduceSize) {
  FolderEncodeResult r;
  Buf cur = data;
  std::vector<SzCoder> coders;       // in encode order
  std::vector<UInt64> outSizes;      // output size of each encoder (= input size of coder in storage)
  std::vector<UInt64> inSizes;
  for (const MethodSpec &ms : chain.methods) {
    SzCoder c; c.id = ms.id;
    UInt64 inSize = cur.size();
    Buf out;
    switch (ms.id) {
      case k_Copy: out = cur; break;
      case k_LZMA2: {
        LzmaProps lp; ApplyLzmaParams(lp, cs, ms); lp.reduceSize = reduceSize; lp.Normalize();
        unsigned nt = cs.numThreads ? cs.numThreads : GetNumCpus();
        unsigned blockThreads = nt >= 2 ? nt / (lp.algo == 0 ? 1 : 2) : 1;
        if (blockThreads < 1) blockThreads = 1;
        Byte prop; out = Lzma2Encode(cur, lp, prop, Lzma2BlockSize(lp.GetDictSizeReduced()), blockThreads);
        c.props.push_back(prop);
        break;
      }
      case k_LZMA: {
        LzmaProps lp; ApplyLzmaParams(lp, cs, ms); lp.reduceSize = reduceSize; lp.Normalize();
        Byte props[5]; out = LzmaEncode(cur, lp, props); c.props.assign(props, props + 5);
        break;
      }
      case k_Deflate: { int lvl = cs.level; for (auto &pr : ms.params) if (pr.first == "x") lvl = atoi(pr.second.c_str()); out = DeflateEncode(cur, lvl); break; }
      case k_BZip2: { int lvl = cs.level; for (auto &pr : ms.params) if (pr.first == "x") lvl = atoi(pr.second.c_str()); out = BZip2Encode(cur, lvl); break; }
      case k_BCJ: case k_ARM: case k_ARMT: case k_PPC: case k_SPARC: out = BranchEncode(ms.id, cur); break;
      case k_Delta: { unsigned d = 1; for (auto &pr : ms.params) if (pr.first == "" || pr.first == "d") { UInt64 n; if (ParseUInt64(pr.second.empty() ? pr.first : pr.second, n)) d = (unsigned)n; } if (!ms.params.empty() && ms.params[0].second.empty() && !ms.params[0].first.empty()) { UInt64 n; if (ParseUInt64(ms.params[0].first, n)) d = (unsigned)n; } if (d < 1 || d > 256) Invalid(); out = DeltaEncode(cur, d); c.props.push_back((Byte)(d - 1)); break; }
      case k_Swap2: out = ::Swap2(cur); break;
      case k_Swap4: out = ::Swap4(cur); break;
      default: throw UnsupportedMethod();
    }
    coders.push_back(c); inSizes.push_back(inSize); outSizes.push_back(out.size());
    cur = std::move(out);
  }
  if (chain.encrypt) {
    SzCoder c; c.id = k_AES; UInt64 inSize = cur.size();
    Buf out = Aes7zEncode(cur, chain.password, c.props);
    coders.push_back(c); inSizes.push_back(inSize); outSizes.push_back(out.size());
    cur = std::move(out);
  }
  // storage order: reverse
  size_t n = coders.size();
  for (size_t i = n; i != 0;) { i--; r.folder.coders.push_back(coders[i]); r.folder.unpackSizes.push_back(inSizes[i]); }
  for (UInt32 i = 1; i < n; i++) r.folder.bindPairs.push_back({i, i - 1});
  r.folder.packStreams = {0};
  r.packStreams.push_back(cur);
  return r;
}

struct SzNewBlock { std::vector<size_t> itemIdx; UInt64 filterId = 0; UInt64 totalSize = 0; };

// ---------------- main update ----------------
static std::string ArcTypeFromName(const std::string &path) {
  const FormatInfo *f = FindFormatByExt(path);
  if (f && f->canUpdate) return f->name;
  return "7z";
}

static int CompareUpdateNames(const std::string &a, const std::string &b) { return CompareFileNames(a, b); }

int CommandUpdate(const Options &o) {
  CompressSettings cs;
  // archive path
  std::string arcPath = o.archiveName;
  bool stdOutMode = o.stdOutMode;
  bool arcExists = false; struct stat arcSt;
  if (!stdOutMode && stat(arcPath.c_str(), &arcSt) == 0) { if (S_ISDIR(arcSt.st_mode)) throw MessageException("The file is a directory"); arcExists = true; }
  std::string arcType;
  if (o.arcTypeSet) {
    std::string t = o.arcType; size_t c = t.find(':'); if (c != std::string::npos) t = t.substr(0, c);
    const FormatInfo *f = FindFormatByName(t);
    if (!f) throw MessageException("Unsupported archive type");
    if (!f->canUpdate) throw MessageException("Unsupported archive type");
    arcType = f->name;
  }
  // Open existing
  OpenedArc oa; bool opened = false;
  if (arcExists) {
    if (g_Out) { *g_Out << "Open archive: " << arcPath << endl; g_Out->Flush(); }
    OpenArcFile(o, arcPath, oa, false);
    if (!oa.openOk) {
      if (oa.sysErr) throw SystemException(oa.sysErr);
      // 7-Zip: cannot update non-archive
      if (g_Err) { *g_Err << endl << "ERROR: " << arcPath << " : "; PrintOpenArchiveError(*g_Err, oa); *g_Err << endl; }
      throw MessageException("Can not open the file as archive");
    }
    opened = true;
    if (arcType.empty()) arcType = oa.format->name;
    else if (!StrEqNoCase(arcType, oa.format->name)) throw MessageException("Archive type mismatch");
    if (!oa.format->canUpdate) throw MessageException("Can not update archive of this type");
    if (g_Out) PrintArcProps(*g_Out, oa);
  }
  if (arcType.empty()) arcType = ArcTypeFromName(arcPath);
  cs.Parse(o.properties, arcType);
  if (o.sfxMode) throw MessageException("SFX is not supported");
  if (!o.volumeSizes.empty()) throw MessageException("Volumes are not supported");

  // Scan
  DirItems dirItems;
  bool stdInMode = o.stdInMode;
  if (!stdInMode) {
    if (g_Out) { *g_Out << "Scanning the drive:" << endl; g_Out->Flush(); }
    std::string excl;
    if (!stdOutMode) {
      // absolute compare: exclude archive file by physical path
      excl = arcPath;
    }
    EnumerateItems(o.censor, dirItems, !o.symLinks, excl);
    // also exclude the tmp file path & archive by comparing inode
    for (const auto &e : dirItems.errors) PrintScanWarningsImmediate(e.path, e.err);
    if (g_Out) *g_Out << FilesFoldersString(dirItems.numDirs, dirItems.numFiles, true, dirItems.totalSize) << endl << endl;
  }

  // Build update items
  std::vector<UpdateItem> items;
  std::vector<bool> arcUsed;
  IArchive *oldArc = opened ? oa.arc.get() : nullptr;
  if (oldArc) arcUsed.assign(oldArc->NumItems(), false);
  // sort dir items by name
  std::vector<size_t> dirOrder(dirItems.items.size());
  for (size_t i = 0; i < dirOrder.size(); i++) dirOrder[i] = i;
  std::stable_sort(dirOrder.begin(), dirOrder.end(), [&](size_t a, size_t b) { return CompareUpdateNames(dirItems.items[a].logPath, dirItems.items[b].logPath) < 0; });
  // Action table
  bool isDelete = o.command == kDelete, isRename = o.command == kRename, isUpdateCmd = o.command == kUpdate;
  // default actions: a: p1 q1 r2 x2 y2 z2 w2 ; u: p1 q1 r2 x1 y2 z1 w2; d: p1 q0 r0 x0 y0 z0 w0
  int actions[7];
  if (isDelete) { int a[7] = {1,0,0,0,0,0,0}; memcpy(actions, a, sizeof(a)); }
  else if (isUpdateCmd) { int a[7] = {1,1,2,1,2,1,2}; memcpy(actions, a, sizeof(a)); }
  else { int a[7] = {1,1,2,2,2,2,2}; memcpy(actions, a, sizeof(a)); }
  // parse -u switch (simple: p#q#r#x#y#z#w#)
  for (const std::string &u : o.updateOptions) {
    size_t i = 0; if (i < u.size() && u[i] == '-') { i++; }
    while (i < u.size()) {
      char c = u[i++];
      if (c == '!') break;
      int idx = -1;
      switch (c) { case 'p': idx = 0; break; case 'q': idx = 1; break; case 'r': idx = 2; break; case 'x': idx = 3; break; case 'y': idx = 4; break; case 'z': idx = 5; break; case 'w': idx = 6; break; default: throw CmdLineException("Unsupported -u option", u); }
      if (i >= u.size() || u[i] < '0' || u[i] > '3') throw CmdLineException("Unsupported -u option", u);
      actions[idx] = u[i++] - '0';
    }
  }
  UInt64 deleteFiles = 0, deleteDirs = 0, deleteSize = 0, keepFiles = 0, keepDirs = 0, keepSize = 0, addFiles = 0, addDirs = 0, addSize = 0;
  bool addSizeKnown = true;
  std::vector<std::pair<std::string,std::string>> renames = o.renamePairs;
  if (oldArc) {
    for (size_t ai = 0; ai < oldArc->NumItems(); ai++) {
      const ArcItem &a = oldArc->Item(ai);
      std::string aname = GetItemDisplayName(a, arcPath, oa.format);
      // matched by censor?
      bool matched = o.censor.CheckPath(aname, !a.isDir) && !(o.censor.includeItems.empty() && (isDelete || isRename));
      if (isRename) {
        // rename: keep all, change names
        UpdateItem ui; ui.arcIndex = (int)ai; ui.name = aname; ui.isDir = a.isDir; ui.size = a.size; ui.newData = false; ui.newProps = false;
        for (auto &rp : renames) {
          std::vector<std::string> parts = SplitPathToParts(aname), pp = SplitPathToParts(rp.first);
          if (parts.size() >= pp.size()) {
            bool ok = true; for (size_t k = 0; k < pp.size(); k++) if (!DoesWildcardMatchName(pp[k], parts[k])) { ok = false; break; }
            if (ok) { std::string nn = rp.second; for (size_t k = pp.size(); k < parts.size(); k++) nn += "/" + parts[k]; ui.name = nn; ui.newProps = true; break; }
          }
        }
        items.push_back(ui); arcUsed[ai] = true;
        if (a.isDir) keepDirs++; else { keepFiles++; keepSize += a.size; }
        continue;
      }
      // find disk item with same name
      int di = -1;
      if (matched) {
        // binary search in sorted dirOrder
        size_t lo = 0, hi = dirOrder.size();
        while (lo < hi) { size_t mid = (lo + hi) / 2; int c = CompareUpdateNames(dirItems.items[dirOrder[mid]].logPath, aname); if (c < 0) lo = mid + 1; else hi = mid; }
        if (lo < dirOrder.size() && dirItems.items[dirOrder[lo]].logPath == aname) di = (int)dirOrder[lo];
      }
      PairState st;
      if (!matched) st = kNotMasked;
      else if (di < 0) st = kOnlyInArchive;
      else {
        const DirItem &d = dirItems.items[di];
        if (a.isDir != d.isDir) { st = kOnlyInArchive; di = -1; }
        else if (a.isDir) st = kSameFiles;
        else {
          UInt64 dm = d.MTimeFT();
          if (!a.mtime.defined) st = kUnknownNewerFiles;
          else {
            // compare with precision: 7z stores 100ns; compare directly
            UInt64 am = a.mtime.ft;
            if (a.mtime.prec == 0) { dm = (dm / 10000000) * 10000000; }
            else if (a.mtime.prec == 1) { dm = (dm / 20000000) * 20000000; am = (am / 20000000) * 20000000; }
            if (am == dm && a.size == d.size) st = kSameFiles;
            else if (am > dm) st = kNewInArchive;
            else st = kOldInArchive;
          }
        }
      }
      int act = actions[st];
      if (act == kIgnore) { if (a.isDir) deleteDirs++; else { deleteFiles++; deleteSize += a.size; } continue; }
      if (act == kCopy || di < 0) {
        UpdateItem ui; ui.arcIndex = (int)ai; ui.name = aname; ui.isDir = a.isDir; ui.size = a.size; ui.newData = false; ui.newProps = false;
        items.push_back(ui); arcUsed[ai] = true;
        if (di >= 0) {} // disk item consumed
        if (a.isDir) keepDirs++; else { keepFiles++; keepSize += a.size; }
        if (di >= 0) { const_cast<DirItem&>(dirItems.items[di]).phyPath = "\x01consumed"; }
        continue;
      }
      // compress from disk: mark disk item as replacing
      arcUsed[ai] = true;
      const_cast<DirItem&>(dirItems.items[di]).logPath += "\x01replace"; // marker
    }
  }
  // new disk items
  if (!isRename) for (size_t k : dirOrder) {
    DirItem &d = dirItems.items[k];
    if (d.phyPath == "\x01consumed") continue;
    bool replace = false;
    if (EndsWith(d.logPath, "\x01replace")) { replace = true; d.logPath = d.logPath.substr(0, d.logPath.size() - 8); }
    if (!replace && oldArc && !isDelete) {
      // only on disk -> action r
      if (actions[kOnlyOnDisk] != kCompress) continue;
    }
    if (isDelete) continue;
    UpdateItem ui; ui.dirIndex = (int)k; ui.name = d.logPath; ui.isDir = d.isDir; ui.size = d.size; ui.newData = true; ui.newProps = true;
    ui.mtime = d.MTimeFT(); ui.mtimeDefined = true; ui.ctime = d.CTimeFT(); ui.atime = d.ATimeFT();
    ui.attrib = d.attrib; ui.attribDefined = true; ui.posixMode = d.mode;
    ui.exeAnalyzed = replace; (void)replace;
    ui.exeAnalyzed = false;
    items.push_back(ui);
    if (d.isDir) addDirs++; else { addFiles++; addSize += d.size; }
  }
  if (stdInMode) {
    UpdateItem ui; ui.newData = true; ui.newProps = true; ui.dirIndex = -2;
    std::string nm = o.stdInName;
    if (nm.empty()) { std::string base = GetBaseName(arcPath); size_t dot = base.find_last_of('.'); nm = (dot == std::string::npos || dot == 0) ? base : base.substr(0, dot); }
    ui.name = nm; ui.mtime = CurrentFileTime(); ui.mtimeDefined = true; ui.attrib = FILE_ATTRIBUTE_ARCHIVE_ | FILE_ATTRIBUTE_UNIX_EXTENSION_ | (0100644u << 16); ui.attribDefined = true; ui.posixMode = 0100644;
    items.push_back(ui); addFiles++; addSizeKnown = false;
  }

  // print
  if (g_Out) {
    *g_Out << (opened ? "Updating archive: " : "Creating archive: ") << (stdOutMode ? std::string("") : arcPath) << endl << endl;
    if (deleteFiles + deleteDirs != 0) *g_Out << "Delete data from archive: " << FilesFoldersString(deleteDirs, deleteFiles, true, deleteSize) << endl;
    if (keepFiles + keepDirs != 0) *g_Out << "Keep old data in archive: " << FilesFoldersString(keepDirs, keepFiles, true, keepSize) << endl;
    *g_Out << "Add new data to archive: " << FilesFoldersString(addDirs, addFiles, addSizeKnown, addSize) << endl;
    *g_Out << endl;
    g_Out->Flush();
  }

  UInt64 filesRead = 0;
  int err = 0;
  OutFile out;
  if (!out.Open(arcPath, stdOutMode, err)) throw SystemException(err);
  auto writer = [&](const Byte *p, size_t n) { out.Write(p, n); };
  auto readItemData = [&](const UpdateItem &ui, Buf &data) -> bool {
    if (ui.dirIndex == -2) { // stdin
      data.clear(); Byte buf[1 << 16];
      for (;;) { ssize_t n = read(0, buf, sizeof(buf)); if (n < 0) throw SystemException(errno); if (n == 0) break; data.insert(data.end(), buf, buf + n); }
      return true;
    }
    if (ui.newData) {
      const DirItem &d = dirItems.items[ui.dirIndex];
      int e; if (!ReadWholeFile(d.phyPath, data, e)) { if (g_Err) *g_Err << endl << "WARNING: " << ErrnoMessage(e) << endl << d.phyPath << endl << endl; return false; }
      return true;
    }
    data.clear(); bool cc;
    ExtractResult r = oldArc->ExtractItem((size_t)ui.arcIndex, o.password, [&](const Byte *p, size_t n) { data.insert(data.end(), p, p + n); }, cc);
    if (r != kOK) throw MessageException("Data error in old archive");
    return true;
  };

  try {
    if (arcType == "7z") {
      // ---- 7z ----
      Sz7zArchive *old7 = opened ? dynamic_cast<Sz7zArchive*>(oldArc) : nullptr;
      // determine chain
      SzEncoderChain chain;
      bool copyMode = cs.IsCopy();
      std::vector<MethodSpec> mainMethods;
      if (cs.methods.empty()) { MethodSpec ms; ms.name = cs.level == 0 ? "Copy" : "LZMA2"; ms.id = cs.level == 0 ? k_Copy : k_LZMA2; mainMethods.push_back(ms); }
      else for (auto &m : cs.methods) if (!m.name.empty()) mainMethods.push_back(m);
      bool useFilterAnalysis = cs.filterOn && !copyMode;
      bool explicitFilter = false;
      for (auto &m : mainMethods) if (m.id == k_BCJ || m.id == k_BCJ2 || m.id == k_ARM || m.id == k_ARMT || m.id == k_PPC || m.id == k_SPARC || m.id == k_ARM64 || m.id == k_RISCV || m.id == k_Delta) explicitFilter = true;
      if (explicitFilter) useFilterAnalysis = false;
      chain.methods = mainMethods;
      chain.encrypt = o.passwordEnabled && !o.password.empty();
      chain.password = o.password;
      bool encryptHeaders = cs.encryptHeaders && chain.encrypt;
      // dict for solid size
      UInt32 mainDict = cs.dictSize ? cs.dictSize : LevelDict(cs.level);
      for (auto &m : mainMethods) if (m.id == k_LZMA || m.id == k_LZMA2) for (auto &pr : m.params) if (pr.first == "d") { UInt32 d; if (ParseDictValue(pr.second, d)) mainDict = d; }
      UInt64 numSolidBytes, numSolidFiles = cs.solidFiles;
      if (!cs.solid) { numSolidBytes = 0; }
      else if (cs.solidBytes != (UInt64)-1) numSolidBytes = cs.solidBytes;
      else {
        if (copyMode) numSolidBytes = 0;
        else { numSolidBytes = (UInt64)mainDict << 7; const UInt64 kMin = (UInt64)1 << 24, kMax = (UInt64)1 << 32; if (numSolidBytes < kMin) numSolidBytes = kMin; if (numSolidBytes > kMax) numSolidBytes = kMax; }
      }
      if (numSolidBytes == 0) numSolidFiles = 1;

      // classify items
      std::vector<size_t> emptyIdx, dataIdx;
      for (size_t i = 0; i < items.size(); i++) { if (items[i].isDir || items[i].size == 0 && !(items[i].dirIndex == -2)) emptyIdx.push_back(i); else dataIdx.push_back(i); }
      // sort empty: dirs first by name, then empty files by name
      std::stable_sort(emptyIdx.begin(), emptyIdx.end(), [&](size_t a, size_t b) {
        const UpdateItem &x = items[a], &y = items[b];
        if (x.isDir != y.isDir) return x.isDir;
        return CompareUpdateNames(x.name, y.name) < 0;
      });
      // folders: copied old folders (all items kept and not newData), repack folders, new blocks
      SzOutDb db; std::vector<Buf> packStreams;
      std::vector<std::vector<size_t>> folderItems; // per new folder: item indices in items (data items)
      std::vector<SzFolder> newFolders; std::vector<std::vector<Buf>> newPack;
      std::vector<size_t> dataFromArc, dataNew;
      for (size_t i : dataIdx) { if (items[i].newData) dataNew.push_back(i); else dataFromArc.push_back(i); }
      UInt64 reduceSize = 0; for (size_t i : dataNew) reduceSize += items[i].size;
      // old folders
      if (old7) {
        std::vector<std::vector<size_t>> perFolder(old7->db.folders.size());
        for (size_t i : dataFromArc) perFolder[old7->db.files[items[i].arcIndex].folderIndex].push_back(i);
        for (size_t f = 0; f < perFolder.size(); f++) {
          if (perFolder[f].empty()) continue;
          const SzFolder &of = old7->db.folders[f];
          // all items of folder kept?
          bool allKept = perFolder[f].size() == of.numUnpackStreams;
          // sort items by original order
          std::sort(perFolder[f].begin(), perFolder[f].end(), [&](size_t a, size_t b) { return items[a].arcIndex < items[b].arcIndex; });
          if (allKept) {
            SzFolder nf = of; nf.firstPackStreamIndex = 0;
            std::vector<Buf> ps;
            for (size_t k = 0; k < of.packStreams.size(); k++) {
              UInt32 pi = of.firstPackStreamIndex + (UInt32)k;
              UInt64 start = old7->db.packStreamStart[pi], size = old7->db.packSizes[pi];
              ps.push_back(Buf(old7->data.begin() + (size_t)start, old7->data.begin() + (size_t)(start + size)));
            }
            newFolders.push_back(nf); newPack.push_back(ps); folderItems.push_back(perFolder[f]);
          } else {
            if (g_Out && o.logLevel >= 2) *g_Out << "R #" << (UInt64)f << endl;
            // repack: decode kept items, encode as one block (respecting solid limits)
            Buf data;
            std::vector<size_t> blockItems;
            // print skipped/repacked per item in folder order
            if (g_Out && o.logLevel >= 2) {
              for (size_t fi = old7->db.folderStartFileIndex[f]; fi < old7->db.files.size(); fi++) {
                if (old7->db.files[fi].folderIndex != (int)f) { if (old7->db.files[fi].hasStream) break; else continue; }
                bool kept = false; for (size_t i : perFolder[f]) if ((size_t)items[i].arcIndex == fi) kept = true;
                *g_Out << (kept ? "R " : ". ") << old7->db.files[fi].name << endl;
              }
            }
            for (size_t i : perFolder[f]) { Buf d; readItemData(items[i], d); data.insert(data.end(), d.begin(), d.end()); blockItems.push_back(i); }
            FolderEncodeResult fr = EncodeFolder(data, chain, cs, reduceSize ? reduceSize : data.size());
            newFolders.push_back(fr.folder); newPack.push_back(fr.packStreams); folderItems.push_back(blockItems);
          }
        }
      }
      // new data: analysis for exe
      std::vector<UInt64> filterOf(items.size(), 0);
      if (useFilterAnalysis) {
        for (size_t i : dataNew) {
          UpdateItem &ui = items[i];
          if (ui.dirIndex < 0) continue;
          const DirItem &d = dirItems.items[ui.dirIndex];
          if (ui.size < 2048) continue;
          bool exec = (d.mode & 0111) != 0;
          if (!exec && !IsExeExt(ui.name)) continue;
          if (g_Out && o.logLevel >= 3) *g_Out << "A " << ui.name << endl;
          UInt64 fid = DetectExeFilter(d.phyPath);
          if (fid == k_BCJ || fid == k_ARMT || fid == k_PPC || fid == k_SPARC || fid == k_ARM) filterOf[i] = fid; // supported encoders
          else filterOf[i] = 0;
        }
      }
      // groups: 0 then filter ids ascending
      std::vector<UInt64> groupIds; groupIds.push_back(0);
      for (size_t i : dataNew) { UInt64 f = filterOf[i]; if (f && std::find(groupIds.begin(), groupIds.end(), f) == groupIds.end()) groupIds.push_back(f); }
      std::sort(groupIds.begin() + 1, groupIds.end());
      for (UInt64 gid : groupIds) {
        std::vector<size_t> g;
        for (size_t i : dataNew) if (filterOf[i] == gid) g.push_back(i);
        if (g.empty()) continue;
        std::stable_sort(g.begin(), g.end(), [&](size_t a, size_t b) { return CompareUpdateNames(items[a].name, items[b].name) < 0; });
