import sys
data = open(sys.argv[1],'rb').read()
kTop = 1 << 24
class RC:
    def __init__(s): s.low = 0; s.range = 0xFFFFFFFF; s.cache = 0; s.cacheSize = 1; s.out = 0
    def shiftlow(s):
        if (s.low & 0xFFFFFFFF) < 0xFF000000 or (s.low >> 32) != 0:
            s.out += s.cacheSize; s.cacheSize = 0
        s.cacheSize += 1
        s.low = (s.low & 0x00FFFFFF) << 8
    def bit(s, probs, idx, b):
        p = probs[idx]; bound = (s.range >> 11) * p
        if b == 0: s.range = bound; probs[idx] = p + ((2048 - p) >> 5)
        else: s.low += bound; s.range -= bound; probs[idx] = p - (p >> 5)
        while s.range < kTop: s.range <<= 8; s.shiftlow()
    def processed(s): return s.out + s.cacheSize
def simulate(data, start):
    rc = RC(); isMatch = [1024]*(12*16); lit = [1024]*(0x300*8)
    pos = 0; prev = 0; state = 0
    n = len(data) - start
    while pos < n:
        b = data[start+pos]
        posState = pos & 3
        rc.bit(isMatch, state*16+posState, 0)
        base = (prev >> 5) * 0x300
        sym = 1
        for i in range(7, -1, -1):
            bitv = (b >> i) & 1
            rc.bit(lit, base + sym, bitv); sym = (sym << 1) | bitv
        prev = b; pos += 1
        if pos + 4096 + 300 >= (1 << 21) or rc.processed() + 16384 >= 65536: break
    return pos
pos = 0; sizes = []
while pos < len(data):
    u = simulate(data, pos); sizes.append(u); pos += u
print(sizes)
